window.LECTURES = [{"schema_version": "1.0.0", "lecture": {"id": "LING-L01", "number": 1, "title": "Language and Linguistics", "language": "en", "source_filename": "Lec 1(1).ppt", "source_slide_count": 17, "question_count": 80, "scope": "Lecture 1 only; original practice examples apply the concepts taught in the supplied slides.", "exam_alignment": "Concept-based practice. No past paper or official examination blueprint was supplied.", "answer_model": "Single best answer. answer_id refers to an option id, not its displayed position. Preserve option ids when shuffling.", "display_guidance": "In learning mode, display explanation followed by example after the learner answers. Source slides and clarification notes can appear in a reference panel."}, "references": [{"id": "lecture_01", "type": "user_supplied_slides", "title": "Lecture 1", "filename": "Lec 1(1).ppt", "library_file_id": "libfile_da8b945ae8008191a02cd386c637f611", "note": "Author definitions are paraphrased as attributed in the slides, not presented as independently verified verbatim quotations."}, {"id": "nidcd_asl", "type": "authoritative_clarification", "organization": "National Institute on Deafness and Other Communication Disorders, NIH", "title": "American Sign Language", "url": "https://www.nidcd.nih.gov/health/american-sign-language", "supports": "Natural sign languages are full languages. ASL is a natural language with grammar distinct from English."}, {"id": "duality_chapter", "type": "scholarly_clarification", "title": "On duality of patterning", "publication": "Simultaneous Structure in Phonology", "publisher": "Oxford University Press", "url": "https://academic.oup.com/book/8665/chapter-abstract/154660911", "supports": "Duality distinguishes a level of meaningful units from the units without meaning that compose them."}], "clarifications": [{"id": "CL01", "source_slides": [4, 9], "question_ids": ["LING-L01-Q020", "LING-L01-Q021"], "note": "Treat the slides’ vocal-language emphasis as an account of spoken language. Do not exclude natural sign languages or imply that writing is necessary for language.", "reference_ids": ["nidcd_asl"]}, {"id": "CL02", "source_slides": [6], "question_ids": ["LING-L01-Q036", "LING-L01-Q037", "LING-L01-Q038", "LING-L01-Q039"], "note": "Slide 6 places discreteness beside duality. The questions distinguish discrete units from the two levels of patterning rather than treating the terms as synonyms.", "reference_ids": ["duality_chapter"]}, {"id": "CL03", "source_slides": [2, 5], "question_ids": ["LING-L01-Q009", "LING-L01-Q025", "LING-L01-Q026", "LING-L01-Q027"], "note": "Non-instinctive and cultural transmission concern learning a particular community language. They do not imply absence of biological language capacity."}, {"id": "CL04", "source_slides": [5, 6], "question_ids": ["LING-L01-Q028", "LING-L01-Q029", "LING-L01-Q030", "LING-L01-Q031"], "note": "Creativity and productivity overlap in the slides. Questions do not impose a rigid distinction unsupported by the lecture."}, {"id": "CL05", "source_slides": [10, 11, 12, 13], "note": "Functions may overlap. Scenario questions identify a dominant purpose through explicit context rather than assuming that wording alone fixes function."}, {"id": "CL06", "source_slides": [4, 5, 6], "question_ids": ["LING-L01-Q040"], "note": "The introductory contrast with animal communication is not converted into an absolute claim that every individual feature is exclusive to humans."}], "coverage": [{"source_slides": [1, 2, 3], "focus": "Language as symbol, code, and behavior; Sapir, Bloch and Trager, Hall, and Chomsky.", "question_ids": ["LING-L01-Q001", "LING-L01-Q002", "LING-L01-Q003", "LING-L01-Q004", "LING-L01-Q005", "LING-L01-Q006", "LING-L01-Q007", "LING-L01-Q008", "LING-L01-Q009", "LING-L01-Q010", "LING-L01-Q011", "LING-L01-Q012"]}, {"source_slides": [4, 7, 8, 9], "focus": "Communication, systematicity, arbitrariness, symbolic convention, social behavior, and speech/writing.", "question_ids": ["LING-L01-Q011", "LING-L01-Q012", "LING-L01-Q013", "LING-L01-Q014", "LING-L01-Q015", "LING-L01-Q016", "LING-L01-Q017", "LING-L01-Q018", "LING-L01-Q019", "LING-L01-Q020", "LING-L01-Q021", "LING-L01-Q022"]}, {"source_slides": [5, 6], "focus": "Interchangeability, cultural transmission, creativity, productivity, displacement, discreteness, duality, and the human-language comparison.", "question_ids": ["LING-L01-Q023", "LING-L01-Q024", "LING-L01-Q025", "LING-L01-Q026", "LING-L01-Q027", "LING-L01-Q028", "LING-L01-Q029", "LING-L01-Q030", "LING-L01-Q031", "LING-L01-Q032", "LING-L01-Q033", "LING-L01-Q034", "LING-L01-Q035", "LING-L01-Q036", "LING-L01-Q037", "LING-L01-Q038", "LING-L01-Q039", "LING-L01-Q040"]}, {"source_slides": [10, 11, 12, 13], "focus": "All seven named language functions, with identification and contextual contrasts.", "question_ids": ["LING-L01-Q041", "LING-L01-Q042", "LING-L01-Q043", "LING-L01-Q044", "LING-L01-Q045", "LING-L01-Q046", "LING-L01-Q047", "LING-L01-Q048", "LING-L01-Q049", "LING-L01-Q050", "LING-L01-Q051", "LING-L01-Q052", "LING-L01-Q053", "LING-L01-Q054", "LING-L01-Q055", "LING-L01-Q056", "LING-L01-Q057", "LING-L01-Q058", "LING-L01-Q059", "LING-L01-Q060", "LING-L01-Q061", "LING-L01-Q062", "LING-L01-Q063", "LING-L01-Q064", "LING-L01-Q065", "LING-L01-Q066", "LING-L01-Q067", "LING-L01-Q068"]}, {"source_slides": [14], "focus": "Linguistics; history, acquisition, structure, and use.", "question_ids": ["LING-L01-Q069", "LING-L01-Q070", "LING-L01-Q071", "LING-L01-Q072"]}, {"source_slides": [15, 16], "focus": "Learning and teaching, dictionaries, translation, language technology, writing systems, communication across groups, linguistic difficulties, multilingual settings, and endangered languages.", "question_ids": ["LING-L01-Q073", "LING-L01-Q074", "LING-L01-Q075", "LING-L01-Q076", "LING-L01-Q077", "LING-L01-Q078", "LING-L01-Q079", "LING-L01-Q080"]}], "excluded_slides": [{"slide": 17, "reason": "Closing thank-you slide; no examinable content."}], "topics": [{"id": "definitions", "title": "Language: definitions and perspectives", "question_count": 12}, {"id": "characteristics", "title": "Characteristics and symbolic organization", "question_count": 10}, {"id": "design_features", "title": "Features of communication systems", "question_count": 18}, {"id": "functions_informative", "title": "Informative function", "question_count": 4}, {"id": "functions_interpersonal", "title": "Interpersonal function", "question_count": 4}, {"id": "functions_performative", "title": "Performative function", "question_count": 4}, {"id": "functions_emotive", "title": "Emotive function", "question_count": 4}, {"id": "functions_phatic", "title": "Phatic communion", "question_count": 4}, {"id": "functions_recreational", "title": "Recreational function", "question_count": 4}, {"id": "functions_metalingual", "title": "Metalingual function", "question_count": 4}, {"id": "linguistics", "title": "Nature and scope of linguistics", "question_count": 4}, {"id": "applications", "title": "Applications of linguistic analysis", "question_count": 8}], "statistics": {"difficulty": {"easy": 21, "medium": 46, "hard": 13}, "cognitive_level": {"understand": 18, "remember": 12, "analyze": 19, "apply": 31}, "answer_distribution": {"A": 20, "B": 20, "C": 20, "D": 20}}, "questions": [{"id": "LING-L01-Q001", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [1, 4], "difficulty": "easy", "cognitive_level": "understand", "question": "Which description best brings together the views of language introduced in this lecture?", "explanation": "Language connects forms with meanings through shared conventions. Its units combine according to rules, allowing people to communicate and interact. It includes much more than writing or emotional reactions.", "example": "Friends use familiar words and sentence patterns to arrange a meeting.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A rule-governed system of symbols used in human communication and social interaction"}, {"id": "B", "text": "A set of emotional reactions that requires no shared conventions"}, {"id": "C", "text": "A collection of written signs used only to record information"}, {"id": "D", "text": "A fixed list of sounds repeated without combining them"}], "answer_id": "A"}, {"id": "LING-L01-Q002", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [2], "difficulty": "easy", "cognitive_level": "remember", "question": "In the definition attributed to Sapir in the slides, what does language communicate through voluntarily produced symbols?", "explanation": "Sapir’s definition in the lecture gives language a broad communicative role. People use symbols to express thoughts, feelings, and wants, rather than to transmit facts alone.", "example": "“I miss home” expresses a feeling, while “I want to visit home” expresses a desire.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Only facts that can be checked scientifically"}, {"id": "B", "text": "Ideas, emotions, and desires"}, {"id": "C", "text": "Only relationships between written letters"}, {"id": "D", "text": "Only instructions about immediate physical dangers"}], "answer_id": "B"}, {"id": "LING-L01-Q003", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [2], "difficulty": "easy", "cognitive_level": "remember", "question": "Which scholars are associated in the lecture with a definition emphasizing arbitrary vocal symbols and cooperation within a social group?", "explanation": "The lecture attributes this combination of arbitrariness, vocal symbols, and social cooperation to Bloch and Trager. The focus is on language as a shared resource for group activity.", "example": "A group uses agreed words to divide tasks and organize an event.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Hall"}, {"id": "B", "text": "Bloch and Trager"}, {"id": "C", "text": "Sapir"}, {"id": "D", "text": "Chomsky"}], "answer_id": "B"}, {"id": "LING-L01-Q004", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [3], "difficulty": "easy", "cognitive_level": "remember", "question": "Which account in the lecture emphasizes language as an institution involving habitual oral–auditory symbols?", "explanation": "The slides associate Hall with language as a social institution and with habitual communication through oral–auditory symbols. This describes the spoken-language emphasis of that account.", "example": "People repeatedly use familiar spoken expressions to interact in their community.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Hall’s account"}, {"id": "B", "text": "Sapir’s account"}, {"id": "C", "text": "Bloch and Trager’s account"}, {"id": "D", "text": "Chomsky’s account"}], "answer_id": "A"}, {"id": "LING-L01-Q005", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [3], "difficulty": "easy", "cognitive_level": "remember", "question": "In Chomsky’s definition as presented in the lecture, sentences are constructed from what?", "explanation": "The definition highlights how a limited inventory of elements can support sentence formation. It does not describe language as a memorized list of complete messages.", "example": "Familiar words can combine in a new sentence such as “The little robot borrowed my umbrella.”", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A fixed set of complete sentences that speakers memorize"}, {"id": "B", "text": "A set of written letters with no structural rules"}, {"id": "C", "text": "A finite set of elements"}, {"id": "D", "text": "A separate unlimited vocabulary for every sentence"}], "answer_id": "C"}, {"id": "LING-L01-Q006", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [3], "difficulty": "medium", "cognitive_level": "understand", "question": "Which statement accurately represents the relationship between sentence length and the set of sentences in Chomsky’s definition on the slide?", "explanation": "The length of one sentence and the size of the set of possible sentences are different matters. A sentence can contain a finite number of elements even when speakers can keep producing further sentences.", "example": "“Ali smiled” is short, and adding “Mary said that” creates another finite sentence.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Every sentence must have the same length because the elements are finite."}, {"id": "B", "text": "Each sentence is finite in length, while the set of sentences may be finite or infinite."}, {"id": "C", "text": "Each sentence must be infinite in length, while the set of sentences is finite."}, {"id": "D", "text": "The number of elements must be infinite for any sentence to be possible."}], "answer_id": "B"}, {"id": "LING-L01-Q007", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [2, 3], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which comparison best captures the different emphases of Bloch and Trager’s and Chomsky’s definitions in the lecture?", "explanation": "These definitions view language from different angles. One foregrounds a social group using symbols together. The other foregrounds sentences and the elements from which they are constructed.", "example": "Organizing a group discussion illustrates social cooperation; examining possible sentence forms illustrates formal structure.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Bloch and Trager emphasize writing, while Chomsky emphasizes emotional expression."}, {"id": "B", "text": "Bloch and Trager describe animal calls, while Chomsky describes only dictionary meanings."}, {"id": "C", "text": "Bloch and Trager exclude symbols, while Chomsky excludes sentences."}, {"id": "D", "text": "Bloch and Trager emphasize social cooperation, while Chomsky emphasizes the formal construction of sentences."}], "answer_id": "D"}, {"id": "LING-L01-Q008", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [2, 3], "difficulty": "medium", "cognitive_level": "apply", "question": "A teacher discusses how language helps people express affection and wishes through intentional symbols. Which definition in the lecture most directly matches this emphasis?", "explanation": "The emphasis on communicating emotions and desires through voluntarily produced symbols most directly follows Sapir’s formulation in the slides. Other definitions overlap but foreground different features.", "example": "“I hope you succeed” conveys a wish through an intentional linguistic message.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Hall’s definition"}, {"id": "B", "text": "Sapir’s definition"}, {"id": "C", "text": "Chomsky’s definition"}, {"id": "D", "text": "Bloch and Trager’s definition"}], "answer_id": "B"}, {"id": "LING-L01-Q009", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [2, 4, 5], "difficulty": "medium", "cognitive_level": "understand", "question": "How should the term “non-instinctive” in Sapir’s slide definition be understood alongside cultural transmission?", "explanation": "The point concerns learning a community’s particular language. It should not be turned into a claim that biology has no role in human language or that formal teaching is necessary for acquisition.", "example": "A child growing up with Urdu-speaking caregivers learns Urdu through interaction.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A particular language is learned through social experience rather than inherited as a ready-made code."}, {"id": "B", "text": "Children must receive formal grammar lessons before they can communicate."}, {"id": "C", "text": "Humans have no biological capacity that supports language learning."}, {"id": "D", "text": "Every person invents a private language without contact with others."}], "answer_id": "A"}, {"id": "LING-L01-Q010", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [1, 4, 8], "difficulty": "medium", "cognitive_level": "understand", "question": "What does it mean to describe language as a code in the context of this lecture?", "explanation": "A code here is a shared system for representing and interpreting meanings. It need not be secret. Understanding depends on knowing the conventions of the language.", "example": "English speakers recognize “book” as a familiar word because they have learned its use.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Listeners can interpret all languages without learning their conventions."}, {"id": "B", "text": "People share conventions that connect linguistic forms with meanings."}, {"id": "C", "text": "Every word naturally resembles the thing it names."}, {"id": "D", "text": "Every utterance is a secret message that must be encrypted."}], "answer_id": "B"}, {"id": "LING-L01-Q011", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [4, 10, 11], "difficulty": "medium", "cognitive_level": "apply", "question": "A student greets a lecturer formally but uses a familiar nickname with a close friend. Which characteristic of language does this most directly illustrate?", "explanation": "Language choices respond to relationships and social situations. Forms of address can signal respect, closeness, or distance even when people are speaking the same language.", "example": "The student says “Good morning, Professor” in class and “Hi, Sami” to a friend.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Language requires a written form for every interaction."}, {"id": "B", "text": "Language is a form of social behavior."}, {"id": "C", "text": "Language refers only to visible objects."}, {"id": "D", "text": "Language consists of unchanging sounds without social meaning."}], "answer_id": "B"}, {"id": "LING-L01-Q012", "lecture_id": "LING-L01", "topic_id": "definitions", "source_slides": [1, 4], "difficulty": "medium", "cognitive_level": "analyze", "question": "Why is “language is simply a list of words” an incomplete account of language?", "explanation": "Vocabulary is part of language, but knowing words alone does not explain sentence structure or appropriate use. Speakers also know how forms combine and how messages work in interaction.", "example": "Knowing “has,” “he,” and “arrived” is different from knowing how to form “He has arrived.”", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "It assumes that language can express feelings as well as facts."}, {"id": "B", "text": "It allows speakers to use words in social interaction."}, {"id": "C", "text": "It recognizes that communities share linguistic symbols."}, {"id": "D", "text": "It leaves out the rules and conventions through which words combine and function in communication."}], "answer_id": "D"}, {"id": "LING-L01-Q013", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [4, 7], "difficulty": "easy", "cognitive_level": "understand", "question": "What does the lecture mean when it calls language a system?", "explanation": "A system has organized relationships among its parts. In language, rules constrain how units combine, although the exact rules differ across languages.", "example": "In an ordinary English statement, “She has arrived” follows a familiar pattern.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Its meanings exist independently of any community conventions."}, {"id": "B", "text": "Its words can appear in any order without affecting interpretation."}, {"id": "C", "text": "Its elements combine according to shared rules."}, {"id": "D", "text": "Its speakers must use identical sentences in every situation."}], "answer_id": "C"}, {"id": "LING-L01-Q014", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "Which sentence best repairs the lecture’s example “Been he wounded has” as an ordinary English declarative sentence?", "explanation": "Ordinary English declaratives place the subject before the auxiliary sequence. Here, “has” comes before “been,” followed by the past participle “wounded.” Rearranging words affects grammatical structure.", "example": "The same pattern appears in “She has been invited.”", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Has been he wounded."}, {"id": "B", "text": "He been has wounded."}, {"id": "C", "text": "He has been wounded."}, {"id": "D", "text": "Wounded he been has."}], "answer_id": "C"}, {"id": "LING-L01-Q015", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [4, 7], "difficulty": "medium", "cognitive_level": "understand", "question": "Which interpretation best explains the description of language as a “system of systems”?", "explanation": "Language has several organized levels that work together. Sounds help form words, words combine into larger structures, and those structures contribute to meaning.", "example": "In “The cats slept,” sound patterns, the plural ending, word order, and meaning all contribute.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Each speaker uses several unrelated private languages at once."}, {"id": "B", "text": "Every language uses the same sounds and word order."}, {"id": "C", "text": "Writing completely replaces all other linguistic organization."}, {"id": "D", "text": "Language contains interacting patterns of sounds, word formation, sentence structure, and meaning."}], "answer_id": "D"}, {"id": "LING-L01-Q016", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [7, 8], "difficulty": "easy", "cognitive_level": "understand", "question": "What is meant by the arbitrariness of a word such as “pen”?", "explanation": "Arbitrariness concerns the relationship between a linguistic form and its meaning. A community learns and maintains that relationship, so arbitrary does not mean meaningless or constantly changing.", "example": "English “pen” and Urdu “qalam” can name the same kind of writing instrument.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Its sound physically resembles the object in every language."}, {"id": "B", "text": "It cannot be understood by more than one person."}, {"id": "C", "text": "Its form has no necessary natural connection with the object it names."}, {"id": "D", "text": "Its meaning changes randomly every time it is spoken."}], "answer_id": "C"}, {"id": "LING-L01-Q017", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [5, 8], "difficulty": "medium", "cognitive_level": "apply", "question": "English uses “water” and Urdu uses “pani” for the same everyday substance. Which property is most directly illustrated?", "explanation": "Different languages can attach different forms to the same referent. This supports the view that the form–meaning link is conventional rather than naturally required.", "example": "The same familiar object may be called “book” in English and “kitab” in Urdu.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Displacement"}, {"id": "B", "text": "Productivity"}, {"id": "C", "text": "Arbitrariness"}, {"id": "D", "text": "Interchangeability"}], "answer_id": "C"}, {"id": "LING-L01-Q018", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [8], "difficulty": "medium", "cognitive_level": "understand", "question": "What does the rose illustration in the lecture suggest about names and the things they name?", "explanation": "The illustration separates a linguistic label from its referent. A name represents something by convention, while the object’s physical properties do not depend on that label.", "example": "Calling a rose by an Urdu or English name does not alter its fragrance.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "All languages must use the same name for the same flower."}, {"id": "B", "text": "A name determines the physical smell of a flower."}, {"id": "C", "text": "Names are unnecessary for linguistic communication."}, {"id": "D", "text": "Changing a name does not by itself change the properties of the thing named."}], "answer_id": "D"}, {"id": "LING-L01-Q019", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [4, 8], "difficulty": "medium", "cognitive_level": "understand", "question": "Why can a linguistic symbol refer to an idea as well as a physical object?", "explanation": "A symbol does not need to resemble a physical thing. Shared linguistic conventions allow words to represent actions, qualities, emotions, and abstract concepts as well as objects.", "example": "“Justice” refers to an abstract concept, while “chair” can refer to a physical object.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Every linguistic symbol must be a drawing of a visible object."}, {"id": "B", "text": "Abstract ideas have identical spoken forms in every language."}, {"id": "C", "text": "Only objects that are present can receive names."}, {"id": "D", "text": "Symbols can represent meanings established through shared use, including abstract meanings."}], "answer_id": "D"}, {"id": "LING-L01-Q020", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [9], "difficulty": "easy", "cognitive_level": "understand", "question": "Which observation supports the lecture’s point that speech is primary in the development of spoken-language literacy?", "explanation": "For children acquiring a spoken language, everyday interaction generally supports speech before literacy instruction. This is a point about spoken languages, not a reason to exclude natural sign languages.", "example": "A child may tell a story orally before being able to write the same story.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Children commonly learn to speak a community language before learning to read and write it."}, {"id": "B", "text": "Children must master spelling before understanding spoken words."}, {"id": "C", "text": "A spoken language cannot exist without a standardized alphabet."}, {"id": "D", "text": "Writing and speech always develop at exactly the same time in each child."}], "answer_id": "A"}, {"id": "LING-L01-Q021", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [4, 9], "difficulty": "medium", "cognitive_level": "analyze", "question": "How should the lecture’s broad claim that language is vocal be qualified?", "explanation": "Vocal communication describes spoken languages. It is too restrictive as a definition of all language because natural sign languages have their own grammar and can express complex meanings.", "example": "American Sign Language has its own grammatical system and is not simply English represented by gestures.", "reference_ids": ["lecture_01", "nidcd_asl"], "options": [{"id": "A", "text": "Hand movements cannot express grammatical relationships."}, {"id": "B", "text": "Natural sign languages are incomplete versions of written languages."}, {"id": "C", "text": "A language becomes a full language only after it receives an alphabet."}, {"id": "D", "text": "Speech uses a vocal–auditory channel, but natural sign languages are full languages using a visual–gestural channel."}], "answer_id": "D"}, {"id": "LING-L01-Q022", "lecture_id": "LING-L01", "topic_id": "characteristics", "source_slides": [7, 8], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which statement correctly relates arbitrariness to the rule-governed nature of language?", "explanation": "Arbitrariness and systematicity describe different relationships. The first concerns how a form is linked to meaning. The second concerns how linguistic elements are organized and combined.", "example": "The label “cat” is conventional, but “The cat is sleeping” still follows English sentence patterns.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Rule-governed combinations require every word to resemble its referent."}, {"id": "B", "text": "Arbitrary words prevent speakers from sharing any grammatical patterns."}, {"id": "C", "text": "Form–meaning links can be conventional while combinations of forms still follow rules."}, {"id": "D", "text": "Arbitrariness means that listeners decide a completely new meaning for each word on every occasion."}], "answer_id": "C"}, {"id": "LING-L01-Q023", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5], "difficulty": "easy", "cognitive_level": "remember", "question": "Which property allows participants in ordinary conversation to function as both senders and receivers of messages?", "explanation": "Interchangeability refers to the capacity to produce as well as receive linguistic messages. It concerns participant roles, rather than whether a message is about the present or the past.", "example": "One friend asks a question, listens to the reply, and then answers a question in return.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Arbitrariness"}, {"id": "B", "text": "Displacement"}, {"id": "C", "text": "Interchangeability"}, {"id": "D", "text": "Cultural transmission"}], "answer_id": "C"}, {"id": "LING-L01-Q024", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5], "difficulty": "medium", "cognitive_level": "apply", "question": "During a discussion, Ayesha explains an idea, listens to Bilal, and then responds. Which feature is most directly shown by these changing roles?", "explanation": "Ayesha is capable of both producing and understanding messages. The focus of this example is the exchange of speaker and listener roles, rather than the novelty or internal structure of the messages.", "example": "A classroom discussion lets the same student ask, answer, and listen.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Productivity"}, {"id": "B", "text": "Duality of patterning"}, {"id": "C", "text": "Displacement"}, {"id": "D", "text": "Interchangeability"}], "answer_id": "D"}, {"id": "LING-L01-Q025", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5], "difficulty": "easy", "cognitive_level": "understand", "question": "What is cultural transmission in language?", "explanation": "Cultural transmission means that the language a person learns depends on linguistic experience in a community. It does not mean that each child genetically inherits the vocabulary of their ancestors.", "example": "A child regularly interacting with Punjabi-speaking family members can learn Punjabi.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Learning a particular language through interaction with other users"}, {"id": "B", "text": "Learning language only by studying printed grammar rules"}, {"id": "C", "text": "Producing every sentence through a fixed reflex"}, {"id": "D", "text": "Inheriting a complete vocabulary through biological ancestry"}], "answer_id": "A"}, {"id": "LING-L01-Q026", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5], "difficulty": "medium", "cognitive_level": "apply", "question": "A child whose parents speak Urdu grows up using English with caregivers and classmates and becomes an English speaker. Which feature does this most directly illustrate?", "explanation": "A particular language develops through exposure and interaction. Family ancestry alone does not determine which language or languages a child will acquire.", "example": "Children can acquire a language used in their daily environment even when their parents have a different first language.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Cultural transmission"}, {"id": "B", "text": "Interchangeability"}, {"id": "C", "text": "Discreteness"}, {"id": "D", "text": "Displacement"}], "answer_id": "A"}, {"id": "LING-L01-Q027", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which conclusion is justified by the idea of cultural transmission?", "explanation": "Cultural transmission concerns the learning of particular linguistic conventions through experience. It does not settle all questions about the biological capacity for language and does not require formal lessons.", "example": "A child can learn everyday sentence patterns through conversation before studying grammar at school.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A child can learn a community’s language without encountering any of its use."}, {"id": "B", "text": "All children need classroom instruction to learn a first language."}, {"id": "C", "text": "Human biology has no role in the ability to acquire language."}, {"id": "D", "text": "Experience helps determine which particular language a person acquires."}], "answer_id": "D"}, {"id": "LING-L01-Q028", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5], "difficulty": "easy", "cognitive_level": "understand", "question": "Which example best illustrates linguistic creativity as described in the lecture?", "explanation": "Creativity involves making meaningful new uses of language. New expressions remain interpretable because speakers and listeners share words, patterns, and relevant context.", "example": "Listeners can understand “My timetable is a hungry monster” as a new way of describing a demanding schedule.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A speaker replaces all shared conventions with private sounds."}, {"id": "B", "text": "A listener needs to memorize every complete sentence before understanding it."}, {"id": "C", "text": "A speaker produces a new expression that listeners understand from familiar linguistic resources."}, {"id": "D", "text": "A speaker can only repeat messages heard earlier."}], "answer_id": "C"}, {"id": "LING-L01-Q029", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5, 6], "difficulty": "medium", "cognitive_level": "apply", "question": "A student understands “The sleepy robot borrowed my bicycle,” although she has never encountered that sentence before. Which feature is most directly illustrated?", "explanation": "Productivity allows users to create and understand new messages from familiar elements. Understanding is not limited to a stored list of sentences encountered previously.", "example": "Knowing common words and sentence patterns helps a listener understand a newly invented story.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Productivity"}, {"id": "B", "text": "Interchangeability"}, {"id": "C", "text": "Arbitrariness"}, {"id": "D", "text": "Cultural transmission"}], "answer_id": "A"}, {"id": "LING-L01-Q030", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "medium", "cognitive_level": "understand", "question": "What does it mean to describe human language as open-ended?", "explanation": "Open-endedness concerns the range of messages that can be produced. Individual sentences remain finite, and their construction still depends on linguistic patterns.", "example": "A speaker can describe a new invention without needing a separate pre-existing signal for the entire description.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Every sentence must contain an unlimited number of words."}, {"id": "B", "text": "Every speaker must know every possible word."}, {"id": "C", "text": "Users can keep forming new messages rather than relying on a closed list of complete signals."}, {"id": "D", "text": "No rules constrain the formation of messages."}], "answer_id": "C"}, {"id": "LING-L01-Q031", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5, 6], "difficulty": "medium", "cognitive_level": "analyze", "question": "How are creativity and productivity related in this lecture?", "explanation": "The lecture uses these terms with overlapping emphasis on novelty. They should not be forced into a strict opposition when the examples show the same broad capacity to extend language.", "example": "Inventing a new but understandable description shows the creative and productive potential of language.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Creativity concerns past events, while productivity concerns switching speaker roles."}, {"id": "B", "text": "Both concern the ability to form or interpret novel linguistic expressions."}, {"id": "C", "text": "Creativity requires meaningless sounds, while productivity requires fixed messages."}, {"id": "D", "text": "Creativity concerns only spelling, while productivity concerns only handwriting."}], "answer_id": "B"}, {"id": "LING-L01-Q032", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "easy", "cognitive_level": "remember", "question": "Which feature allows speakers to discuss people, places, and events beyond the immediate situation?", "explanation": "Displacement frees communication from the immediate here and now. Speakers can refer to the past, the future, distant locations, and imagined situations.", "example": "“We will visit Karachi next month” refers to a future event away from the current location.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Displacement"}, {"id": "B", "text": "Arbitrariness"}, {"id": "C", "text": "Interchangeability"}, {"id": "D", "text": "Discreteness"}], "answer_id": "A"}, {"id": "LING-L01-Q033", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "medium", "cognitive_level": "apply", "question": "Which utterance most clearly demonstrates displacement?", "explanation": "The correct utterance refers to a time before the speaker’s birth and people’s earlier lives. The other statements describe objects or events in the immediate situation.", "example": "Recounting a childhood memory also uses language beyond the present moment.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "“My grandparents lived in Multan before I was born.”"}, {"id": "B", "text": "“I can hear you speaking beside me.”"}, {"id": "C", "text": "“The light above us is on now.”"}, {"id": "D", "text": "“This cup in my hand is hot.”"}], "answer_id": "A"}, {"id": "LING-L01-Q034", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "medium", "cognitive_level": "apply", "question": "Students discuss what life would be like in a city floating above the clouds. Which feature lets language refer to this imagined situation?", "explanation": "Displacement includes reference to hypothetical and imaginary situations. The referent does not have to exist in front of the speakers, or even exist in the real world.", "example": "A story about a talking mountain can refer to an imagined world.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Interchangeability"}, {"id": "B", "text": "Displacement"}, {"id": "C", "text": "Cultural transmission"}, {"id": "D", "text": "Discreteness"}], "answer_id": "B"}, {"id": "LING-L01-Q035", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [5, 6], "difficulty": "hard", "cognitive_level": "analyze", "question": "A student describes tomorrow’s trip using a sentence no one in the class has heard before. Which two features are most directly involved?", "explanation": "Reference to tomorrow illustrates displacement. Forming a new sentence illustrates productivity. A single utterance can demonstrate more than one property of language.", "example": "“Tomorrow our class will interview a baker beside the old railway station” combines future reference with a new message.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Interchangeability and cultural transmission"}, {"id": "B", "text": "Displacement and productivity"}, {"id": "C", "text": "Cultural transmission and discreteness"}, {"id": "D", "text": "Arbitrariness and interchangeability"}], "answer_id": "B"}, {"id": "LING-L01-Q036", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "medium", "cognitive_level": "understand", "question": "In the description of language features, what does discreteness refer to?", "explanation": "Discreteness concerns units that count as distinct within a linguistic system. It helps explain how combinations can differ when one unit is replaced. It is related to, but not identical with, duality.", "example": "In English, changing the initial sound of “pin” to the initial sound of “bin” changes the word.", "reference_ids": ["lecture_01", "duality_chapter"], "options": [{"id": "A", "text": "The requirement that every utterance express a complete emotion"}, {"id": "B", "text": "The absence of boundaries between any linguistic units"}, {"id": "C", "text": "The ability to talk only about objects that are present"}, {"id": "D", "text": "The organization of language into distinguishable units that can combine"}], "answer_id": "D"}, {"id": "LING-L01-Q037", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "medium", "cognitive_level": "apply", "question": "The words “pat” and “bat” differ in one identifiable sound unit. Which feature does this most directly illustrate?", "explanation": "A language treats certain units as distinct, and changing a unit can change the linguistic form. This example draws attention to separable sound units rather than reference beyond the present.", "example": "Replacing the final sound in “cap” with the final sound in “cat” produces a different word.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Interchangeability"}, {"id": "B", "text": "Discreteness"}, {"id": "C", "text": "Cultural transmission"}, {"id": "D", "text": "Displacement"}], "answer_id": "B"}, {"id": "LING-L01-Q038", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "medium", "cognitive_level": "understand", "question": "Which example best illustrates duality of patterning?", "explanation": "Duality involves two levels of organization: units without meaning at one level combine into meaningful units at another. The slide mentions duality beside discreteness, but the two terms should be distinguished.", "example": "The sounds /k/, /æ/, and /t/ do not individually mean the animal, but together form “cat.”", "reference_ids": ["lecture_01", "duality_chapter"], "options": [{"id": "A", "text": "A greeting makes a relationship more comfortable."}, {"id": "B", "text": "A speaker refers to an event that happened yesterday."}, {"id": "C", "text": "Individually meaningless sound units combine to form meaningful words."}, {"id": "D", "text": "A student alternates between listening and speaking."}], "answer_id": "C"}, {"id": "LING-L01-Q039", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [6], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which statement best distinguishes discreteness from duality of patterning?", "explanation": "These properties describe related but different aspects of organization. Distinctness alone is the focus of discreteness. Duality adds a relationship between a level without meaning and a level with meaning.", "example": "Separate sounds illustrate discreteness; combining those sounds to make meaningful words illustrates duality.", "reference_ids": ["lecture_01", "duality_chapter"], "options": [{"id": "A", "text": "Discreteness concerns distant events, while duality concerns present events."}, {"id": "B", "text": "Discreteness concerns written language only, while duality concerns spoken language only."}, {"id": "C", "text": "Discreteness concerns distinct units, while duality concerns meaningless units combining into meaningful units."}, {"id": "D", "text": "Discreteness concerns emotional expression, while duality concerns social greetings."}], "answer_id": "C"}, {"id": "LING-L01-Q040", "lecture_id": "LING-L01", "topic_id": "design_features", "source_slides": [4, 5, 6], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which claim about human language and animal communication is most defensible when interpreting this introductory lecture?", "explanation": "The lecture’s comparison should not become an absolute denial of animal communication. The important contrast is the extensive combination of properties in human language, including highly flexible expression.", "example": "People can explain a complex hypothetical plan rather than communicate only an immediate warning.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Every feature listed in the lecture is entirely absent from every other species."}, {"id": "B", "text": "Human language combines flexible structure and open-ended expression, although some individual communication features may also occur in other species."}, {"id": "C", "text": "Human language is limited to a fixed set of signals about immediate needs."}, {"id": "D", "text": "Other species cannot exchange any information at all."}], "answer_id": "B"}, {"id": "LING-L01-Q041", "lecture_id": "LING-L01", "topic_id": "functions_informative", "source_slides": [10, 13], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the main purpose of the informative function of language?", "explanation": "The informative function concerns giving or exchanging information. A statement may have other effects, but its central task in this use is to tell the listener something.", "example": "“The library closes at six” gives information about opening hours.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "To convey information"}, {"id": "B", "text": "To perform an authorized institutional act"}, {"id": "C", "text": "To analyse the form of a linguistic expression"}, {"id": "D", "text": "To enjoy the sound of words for its own sake"}], "answer_id": "A"}, {"id": "LING-L01-Q042", "lecture_id": "LING-L01", "topic_id": "functions_informative", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A class representative says, “The examination will begin at 9 a.m. in Room 12,” to tell students the arrangements. Which function is dominant?", "explanation": "The speaker provides practical facts about an event. The stated context makes information delivery the main purpose, rather than entertainment, emotional expression, or discussion of language itself.", "example": "An announcement of a revised timetable serves the same informative purpose.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Recreational"}, {"id": "B", "text": "Emotive"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Informative"}], "answer_id": "D"}, {"id": "LING-L01-Q043", "lecture_id": "LING-L01", "topic_id": "functions_informative", "source_slides": [10, 11, 13], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which utterance most clearly serves an informative purpose rather than merely opening a social exchange?", "explanation": "The pharmacy statement supplies specific information about the world. The other utterances primarily establish or maintain social contact in the contexts suggested by their wording.", "example": "“The bus leaves from Gate 3” gives information that a listener can use.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "“Hello, it is lovely to see you.”"}, {"id": "B", "text": "“Nice to meet you at last.”"}, {"id": "C", "text": "“The pharmacy on this street closes at eight tonight.”"}, {"id": "D", "text": "“Good morning, how are things?”"}], "answer_id": "C"}, {"id": "LING-L01-Q044", "lecture_id": "LING-L01", "topic_id": "functions_informative", "source_slides": [10, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "A radio presenter reads a weather forecast to help listeners plan their journeys. Why is the informative function dominant?", "explanation": "Function depends on communicative purpose, not the topic alone. Weather talk can maintain social contact, but this forecast mainly supplies information for listeners’ decisions.", "example": "“Heavy rain is expected this evening” informs listeners when used in a forecast.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A forecast changes the weather by being spoken."}, {"id": "B", "text": "Mentioning the weather always makes an utterance phatic."}, {"id": "C", "text": "The central purpose is to provide information about expected weather conditions."}, {"id": "D", "text": "Every public announcement is primarily recreational."}], "answer_id": "C"}, {"id": "LING-L01-Q045", "lecture_id": "LING-L01", "topic_id": "functions_interpersonal", "source_slides": [10, 13], "difficulty": "easy", "cognitive_level": "understand", "question": "What does the interpersonal function of language primarily concern in this lecture?", "explanation": "The interpersonal function concerns how participants relate to one another. Language can indicate respect, familiarity, authority, distance, or a speaker’s stance during interaction.", "example": "A respectful form of address can signal the relationship between a student and a lecturer.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Listing the meanings of words in a dictionary"}, {"id": "B", "text": "Expressing and negotiating relationships, social roles, and attitudes in interaction"}, {"id": "C", "text": "Inventing rhymes only for enjoyment"}, {"id": "D", "text": "Describing only the physical properties of sounds"}], "answer_id": "B"}, {"id": "LING-L01-Q046", "lecture_id": "LING-L01", "topic_id": "functions_interpersonal", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "In a formal request, a student addresses the recipient as “Dear Professor Ahmed” to acknowledge the academic relationship. Which function is most directly illustrated?", "explanation": "The form of address marks the relationship between writer and recipient. It communicates respect and social positioning, rather than reporting a fact or analysing the words themselves.", "example": "“Yours sincerely” can help maintain an appropriately formal relationship in a letter.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Recreational"}, {"id": "B", "text": "Informative"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Interpersonal"}], "answer_id": "D"}, {"id": "LING-L01-Q047", "lecture_id": "LING-L01", "topic_id": "functions_interpersonal", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A lecturer changes “Submit this immediately” to “Could you please submit this today?” to soften the request. Which function is most relevant to this change?", "explanation": "The two requests concern a similar action, but their wording presents a different relationship to the listener. The softer version manages politeness and social distance.", "example": "“Would you mind helping?” can make a request sound less abrupt than “Help me.”", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Interpersonal"}, {"id": "B", "text": "Recreational"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Informative"}], "answer_id": "A"}, {"id": "LING-L01-Q048", "lecture_id": "LING-L01", "topic_id": "functions_interpersonal", "source_slides": [10, 11, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "Within the lecture’s classification, which distinction between interpersonal and phatic uses is most useful?", "explanation": "These functions overlap. Phatic greetings are one way to manage social relations, while interpersonal meaning also includes choices that show respect, authority, or attitude beyond greetings.", "example": "“Hello” opens contact; choosing “Professor” rather than a nickname also marks the social relationship.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Interpersonal use contains information, while phatic use cannot contain any factual words."}, {"id": "B", "text": "Interpersonal use is always written, while phatic use is always spoken."}, {"id": "C", "text": "Interpersonal use broadly concerns relationships and stance, while phatic use specifically establishes or maintains social contact."}, {"id": "D", "text": "Interpersonal use describes past events, while phatic use describes future events."}], "answer_id": "C"}, {"id": "LING-L01-Q049", "lecture_id": "LING-L01", "topic_id": "functions_performative", "source_slides": [10, 13], "difficulty": "easy", "cognitive_level": "understand", "question": "What distinguishes the performative function in the lecture’s institutional examples?", "explanation": "In these examples, saying the words is part of doing something within an accepted procedure. Appropriate authority and circumstances matter, as in formal sentencing or a marriage ceremony.", "example": "An authorized official’s declaration during a valid ceremony can establish a new social status.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "An appropriately authorized utterance helps carry out an act or establish a social status."}, {"id": "B", "text": "The speaker describes any action performed in the distant past."}, {"id": "C", "text": "The utterance defines a word without affecting any social situation."}, {"id": "D", "text": "The speaker uses unusual vocabulary to entertain an audience."}], "answer_id": "A"}, {"id": "LING-L01-Q050", "lecture_id": "LING-L01", "topic_id": "functions_performative", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "During a valid court proceeding, a judge says, “I sentence you to six months’ imprisonment.” Which language function is dominant?", "explanation": "The judge is carrying out a judicial act through an authorized declaration. The utterance does more than report a sentence that someone else has already imposed.", "example": "The contrast is “The judge sentenced him yesterday,” which ordinarily reports an earlier act.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Phatic"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Recreational"}], "answer_id": "A"}, {"id": "LING-L01-Q051", "lecture_id": "LING-L01", "topic_id": "functions_performative", "source_slides": [10, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "An actor says “I pronounce you married” in a rehearsal. Why does this normally fail to create a real marriage?", "explanation": "The institutional effect of a declaration depends on more than its wording. Repeating ceremonial words in a play does not by itself satisfy the conditions of an actual marriage procedure.", "example": "A student acting as a judge in a classroom does not impose a real prison sentence.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "The rehearsal lacks the relevant institutional circumstances and authority for the act."}, {"id": "B", "text": "The words are too short to perform any social act."}, {"id": "C", "text": "A performative utterance must contain a technical linguistic term."}, {"id": "D", "text": "Only written language can establish a social status."}], "answer_id": "A"}, {"id": "LING-L01-Q052", "lecture_id": "LING-L01", "topic_id": "functions_performative", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which utterance reports an institutional act rather than carrying it out?", "explanation": "The journalist describes an earlier event, so the dominant use is informative. The other utterances occur as part of the relevant official acts themselves.", "example": "“They named the ship yesterday” reports a naming rather than naming the ship at that moment.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "An authorized official says during a ceremony, “I name this ship Horizon.”"}, {"id": "B", "text": "A judge says in court, “I sentence you to six months.”"}, {"id": "C", "text": "An authorized celebrant makes the required marriage declaration during the ceremony."}, {"id": "D", "text": "A journalist says, “The judge sentenced the defendant yesterday.”"}], "answer_id": "D"}, {"id": "LING-L01-Q053", "lecture_id": "LING-L01", "topic_id": "functions_emotive", "source_slides": [11, 13], "difficulty": "easy", "cognitive_level": "remember", "question": "Which function is most directly associated with expressing strong feelings or affecting an audience emotionally?", "explanation": "The emotive function gives prominence to feelings and emotional response. It can express a speaker’s excitement, pain, frustration, admiration, or similar reaction.", "example": "“Wow, what a wonderful surprise!” expresses excitement.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Informative"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Emotive"}], "answer_id": "D"}, {"id": "LING-L01-Q054", "lecture_id": "LING-L01", "topic_id": "functions_emotive", "source_slides": [11, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "After seeing a beautiful mountain view, a visitor exclaims, “Wow! What a sight!” Which function is dominant?", "explanation": "The visitor is reacting with admiration rather than mainly providing information about the mountain. The context makes emotional expression the central purpose of the utterance.", "example": "“Oh no!” after disappointing news can similarly express an emotional reaction.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Emotive"}, {"id": "B", "text": "Performative"}, {"id": "C", "text": "Phatic"}, {"id": "D", "text": "Metalingual"}], "answer_id": "A"}, {"id": "LING-L01-Q055", "lecture_id": "LING-L01", "topic_id": "functions_emotive", "source_slides": [11, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A speaker describes families’ suffering in moving language to make an audience feel compassion. Which function is being foregrounded?", "explanation": "The language aims to affect the audience’s feelings. It may also supply facts, but the scenario specifically emphasizes creating an emotional response.", "example": "A moving appeal can encourage listeners to feel concern for people affected by a flood.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Emotive"}, {"id": "B", "text": "Metalingual"}, {"id": "C", "text": "Recreational"}, {"id": "D", "text": "Phatic"}], "answer_id": "A"}, {"id": "LING-L01-Q056", "lecture_id": "LING-L01", "topic_id": "functions_emotive", "source_slides": [10, 11, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which change shifts a message most clearly from neutral information toward emotional expression?", "explanation": "The added exclamation foregrounds joy. The alternatives mainly add or change factual information, although any of them could carry emotion in a particular context.", "example": "“Sadly, we lost” explicitly signals a feeling that “We lost” may leave unstated.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Changing “The team won” to “Hurray! Our team finally won!”"}, {"id": "B", "text": "Changing “The team won” to “The team won by two goals.”"}, {"id": "C", "text": "Changing “The team won” to “The result appears on the noticeboard.”"}, {"id": "D", "text": "Changing “The team won” to “The match ended at five.”"}], "answer_id": "A"}, {"id": "LING-L01-Q057", "lecture_id": "LING-L01", "topic_id": "functions_phatic", "source_slides": [11, 13], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the main purpose of phatic communion?", "explanation": "Phatic language keeps interaction socially comfortable and signals willingness to communicate. The relationship often matters more than exchanging new information.", "example": "A brief “Good morning” can acknowledge another person and open an exchange.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "To identify the grammatical category of a word"}, {"id": "B", "text": "To establish or maintain social contact"}, {"id": "C", "text": "To carry out an official judicial decision"}, {"id": "D", "text": "To construct an entirely new writing system"}], "answer_id": "B"}, {"id": "LING-L01-Q058", "lecture_id": "LING-L01", "topic_id": "functions_phatic", "source_slides": [11, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "Two neighbors exchange “Good morning” while passing each other, without seeking new information. Which function is dominant?", "explanation": "The greeting acknowledges the relationship and maintains friendly contact. The scenario rules out a main purpose of asking for or providing factual information.", "example": "A casual “Hello, nice to see you” can serve the same social purpose.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Informative"}, {"id": "B", "text": "Performative"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Phatic"}], "answer_id": "D"}, {"id": "LING-L01-Q059", "lecture_id": "LING-L01", "topic_id": "functions_phatic", "source_slides": [11, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "At a reception, a guest says “Lovely weather, isn’t it?” mainly to begin a friendly conversation. Which function is dominant?", "explanation": "Although the words mention weather, their main purpose here is to open contact. Classifying a function requires attention to why the speaker is using the utterance.", "example": "A brief comment about the journey can also break the ice between strangers.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Metalingual"}, {"id": "C", "text": "Phatic"}, {"id": "D", "text": "Recreational"}], "answer_id": "C"}, {"id": "LING-L01-Q060", "lecture_id": "LING-L01", "topic_id": "functions_phatic", "source_slides": [10, 11, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "In which context does “How are you?” function primarily as a genuine request for information?", "explanation": "The same wording can have different purposes. The clinician’s question requests relevant information, while the other contexts emphasize routine social acknowledgment.", "example": "A friend who notices distress and asks carefully about it may also be seeking a real account.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A passerby says it as a routine greeting and continues walking."}, {"id": "B", "text": "Two colleagues exchange it automatically before moving to another topic."}, {"id": "C", "text": "A host says it quickly to acknowledge each arriving guest."}, {"id": "D", "text": "A clinician asks a patient to describe changes in symptoms and waits for a detailed response."}], "answer_id": "D"}, {"id": "LING-L01-Q061", "lecture_id": "LING-L01", "topic_id": "functions_recreational", "source_slides": [12, 13], "difficulty": "easy", "cognitive_level": "remember", "question": "Which function involves using language for the pleasure of using it?", "explanation": "Recreational language foregrounds enjoyment of words, sounds, rhythm, or verbal play. Its main purpose in such a context is entertainment rather than practical information.", "example": "Friends may repeat a tongue twister simply because it is fun to say.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Recreational"}, {"id": "C", "text": "Informative"}, {"id": "D", "text": "Metalingual"}], "answer_id": "B"}, {"id": "LING-L01-Q062", "lecture_id": "LING-L01", "topic_id": "functions_recreational", "source_slides": [12, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "Children repeat a silly rhyme, laughing at its rhythm and sound. Which function is dominant?", "explanation": "The children enjoy the linguistic performance itself. The scenario does not make the rhyme a lesson about language or an exchange of factual information.", "example": "Playing with rhyming names can be recreational even when it communicates little new information.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Informative"}, {"id": "B", "text": "Recreational"}, {"id": "C", "text": "Performative"}, {"id": "D", "text": "Metalingual"}], "answer_id": "B"}, {"id": "LING-L01-Q063", "lecture_id": "LING-L01", "topic_id": "functions_recreational", "source_slides": [12, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A student writes a playful poem mainly because she enjoys shaping its rhyme and rhythm. Which function is foregrounded?", "explanation": "The stated purpose is enjoyment of language. Poems can serve many functions, including emotional expression, but this question identifies pleasure in verbal creation as the main one.", "example": "Making up humorous verses with friends can serve the same recreational purpose.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Recreational"}, {"id": "C", "text": "Phatic"}, {"id": "D", "text": "Metalingual"}], "answer_id": "B"}, {"id": "LING-L01-Q064", "lecture_id": "LING-L01", "topic_id": "functions_recreational", "source_slides": [12, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "The same tongue twister is used in two activities. Which activity most clearly makes the use metalingual rather than recreational?", "explanation": "When the tongue twister becomes evidence for explaining language, the use is metalingual. Enjoying or performing it for amusement foregrounds recreation instead.", "example": "Discussing which sounds recur in “red lorry, yellow lorry” turns attention to language itself.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "A performer includes it in a light-hearted wordplay game."}, {"id": "B", "text": "A teacher uses it to explain the difference between two speech sounds."}, {"id": "C", "text": "Friends compete to say it quickly for fun."}, {"id": "D", "text": "A child repeats it because its rhythm is amusing."}], "answer_id": "B"}, {"id": "LING-L01-Q065", "lecture_id": "LING-L01", "topic_id": "functions_metalingual", "source_slides": [12, 13], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the metalingual function of language?", "explanation": "Metalingual use makes language the subject of the message. Definitions, explanations of grammar, and comments about word meanings are common examples.", "example": "“A verb can express an action or a state” is a statement about language.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Using an exclamation to show sudden excitement"}, {"id": "B", "text": "Using a greeting to maintain social contact"}, {"id": "C", "text": "Using a declaration to impose a legal sentence"}, {"id": "D", "text": "Using language to explain or discuss language itself"}], "answer_id": "D"}, {"id": "LING-L01-Q066", "lecture_id": "LING-L01", "topic_id": "functions_metalingual", "source_slides": [12, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A teacher says, “In this sentence, ‘quickly’ tells us how the action happens.” Which function is dominant?", "explanation": "The teacher is using language to explain the role of a linguistic expression. The message is about how the sentence works rather than about a real-world event involving speed.", "example": "Explaining that “books” contains a plural ending is another metalingual use.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Phatic"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Recreational"}], "answer_id": "C"}, {"id": "LING-L01-Q067", "lecture_id": "LING-L01", "topic_id": "functions_metalingual", "source_slides": [12, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A learner asks, “What does ‘generous’ mean?” Which function is most directly involved?", "explanation": "The learner asks about the meaning of a word, so language itself is the topic. A question can be metalingual just as a definition or explanation can.", "example": "“Does ‘bank’ refer to a riverbank here?” also asks about linguistic meaning.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Performative"}, {"id": "B", "text": "Phatic"}, {"id": "C", "text": "Metalingual"}, {"id": "D", "text": "Recreational"}], "answer_id": "C"}, {"id": "LING-L01-Q068", "lecture_id": "LING-L01", "topic_id": "functions_metalingual", "source_slides": [10, 12, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which pair correctly distinguishes talking about an object from talking about the word that names it?", "explanation": "The first utterance gives information about something in the world. The second classifies a linguistic expression. The difference lies in what the utterance makes its subject.", "example": "“Water is cold” concerns a substance; “‘Water’ has five letters” concerns the written word.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "“The book is on the desk” is informative about an object; “‘Book’ is a noun” is metalingual."}, {"id": "B", "text": "“The book is on the desk” is metalingual; “‘Book’ is a noun” is performative."}, {"id": "C", "text": "“The book is on the desk” is phatic; “‘Book’ is a noun” is recreational."}, {"id": "D", "text": "“The book is on the desk” is performative; “‘Book’ is a noun” is emotive."}], "answer_id": "A"}, {"id": "LING-L01-Q069", "lecture_id": "LING-L01", "topic_id": "linguistics", "source_slides": [14], "difficulty": "easy", "cognitive_level": "remember", "question": "How does the lecture define linguistics?", "explanation": "Linguistics investigates language systematically, including its structure, history, acquisition, and use. Being a linguist does not mean knowing every language or only correcting errors.", "example": "A linguist may investigate how speakers form questions in a particular language.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "The study of written literature without attention to language"}, {"id": "B", "text": "The ability to speak every language fluently"}, {"id": "C", "text": "The correction of spelling mistakes alone"}, {"id": "D", "text": "The scientific study of language"}], "answer_id": "D"}, {"id": "LING-L01-Q070", "lecture_id": "LING-L01", "topic_id": "linguistics", "source_slides": [14], "difficulty": "easy", "cognitive_level": "understand", "question": "Which set best reflects the areas of investigation explicitly identified in the lecture’s account of linguistics?", "explanation": "The lecture presents linguistics as a broad investigation of how language develops, is learned, is organized, and is used. Its scope extends beyond a single practical language skill.", "example": "Studying how children learn sentence patterns concerns acquisition; studying those patterns concerns structure.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "History, acquisition, structure, and use of languages"}, {"id": "B", "text": "Poetry, drama, fiction, and literary prizes only"}, {"id": "C", "text": "Translation speed, accent imitation, memorization, and proofreading only"}, {"id": "D", "text": "Spelling, handwriting, printing, and page layout only"}], "answer_id": "A"}, {"id": "LING-L01-Q071", "lecture_id": "LING-L01", "topic_id": "linguistics", "source_slides": [14], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher records how children begin combining words over several months. Which area named in the lecture is being investigated most directly?", "explanation": "The researcher is investigating how language develops in learners. The focus is the process of acquiring linguistic abilities, rather than historical change across generations.", "example": "Tracking a child’s move from single words to short combinations is an acquisition study.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Language history"}, {"id": "B", "text": "Writing-system design"}, {"id": "C", "text": "Dictionary compilation"}, {"id": "D", "text": "Language acquisition"}], "answer_id": "D"}, {"id": "LING-L01-Q072", "lecture_id": "LING-L01", "topic_id": "linguistics", "source_slides": [14], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher compares older and newer forms of a language to explain changes across generations. Which area named in the lecture is most directly involved?", "explanation": "The comparison examines language over time. This differs from observing one learner’s development or analysing the purpose of a particular conversation.", "example": "Comparing older and present-day word forms can reveal patterns of linguistic change.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Everyday greeting routines"}, {"id": "B", "text": "Language history"}, {"id": "C", "text": "First-language acquisition"}, {"id": "D", "text": "Computer-interface design"}], "answer_id": "B"}, {"id": "LING-L01-Q073", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A teacher analyses recurring difficulties in learners’ English sentences and uses the results to improve lessons. Which application from the lecture is most directly illustrated?", "explanation": "Linguistic analysis can help teachers identify patterns in learners’ language and plan instruction. The analysis serves the practical goal of improving language learning.", "example": "A teacher may design practice after noticing that students regularly omit a required auxiliary.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Writing-system development"}, {"id": "B", "text": "Dictionary compilation"}, {"id": "C", "text": "Endangered-language documentation"}, {"id": "D", "text": "Language learning and teaching"}], "answer_id": "D"}, {"id": "LING-L01-Q074", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A team collects words, records their meanings, and adds examples to a reference resource. Which application listed in the lecture best matches this work?", "explanation": "Dictionaries organize information about words and their uses. Linguistic analysis helps distinguish meanings, record forms, and select examples that show how words occur.", "example": "A dictionary entry can separate the financial and riverside meanings of “bank.”", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Dictionary development"}, {"id": "B", "text": "Translation between two existing texts"}, {"id": "C", "text": "Improvement of a spoken-command interface"}, {"id": "D", "text": "Development of a community writing system"}], "answer_id": "A"}, {"id": "LING-L01-Q075", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A translator examines a message’s meaning and context before expressing it in another language. Which lecture application is most directly involved?", "explanation": "Translation uses understanding of linguistic forms, meanings, and contexts to express a message in another language. It often requires more than replacing each word separately.", "example": "An English greeting may need a natural Urdu equivalent rather than a word-by-word rendering.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Writing-system development"}, {"id": "B", "text": "Language-acquisition research"}, {"id": "C", "text": "Translation"}, {"id": "D", "text": "Dictionary compilation"}], "answer_id": "C"}, {"id": "LING-L01-Q076", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "Researchers help design a computer system that recognizes spoken requests. Which application mentioned in the lecture best fits this project?", "explanation": "Language technology can use linguistic knowledge to process human input. Recognizing a spoken request requires a system to connect sound patterns with linguistic information.", "example": "A voice interface may interpret “Set an alarm for seven” as a request to create an alarm.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Compilation of a printed dictionary"}, {"id": "B", "text": "Documentation of an endangered language"}, {"id": "C", "text": "Development of a community writing system"}, {"id": "D", "text": "Linguistic input to computer systems"}], "answer_id": "D"}, {"id": "LING-L01-Q077", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A community works with researchers to choose consistent symbols for writing its language. Which application listed in the lecture is most directly involved?", "explanation": "Developing a writing system involves decisions about how to represent linguistic forms visually. Linguistic analysis can inform those decisions alongside community preferences and practical needs.", "example": "The community may discuss which symbol should represent a frequently used speech sound.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Analysis of multilingual classroom interaction"}, {"id": "B", "text": "Compilation of word definitions"}, {"id": "C", "text": "Writing-system development"}, {"id": "D", "text": "Translation of a completed novel"}], "answer_id": "C"}, {"id": "LING-L01-Q078", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A hospital investigates misunderstandings between staff and patients from different language communities. Which application from the lecture best matches the problem?", "explanation": "Linguistic analysis can identify differences in language use that affect understanding across groups. This can inform clearer communication suited to the participants and setting.", "example": "Staff may learn to explain unfamiliar terms clearly and check what patients have understood.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Analysis of how children first combine words"}, {"id": "B", "text": "Communication across social, cultural, and ethnic groups"}, {"id": "C", "text": "Development of a system for representing sounds in writing"}, {"id": "D", "text": "Reconstruction of older word forms across related languages"}], "answer_id": "B"}, {"id": "LING-L01-Q079", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "Only a few older speakers still use a community language, so researchers and community members record stories and everyday speech. Which application is most directly illustrated?", "explanation": "The project concerns a language whose continued use is at risk. Recording speech can preserve evidence of its forms and uses and support community efforts, although recording alone does not ensure continued use.", "example": "Community recordings can provide material for locally developed learning resources.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "Design of an automatic translation interface"}, {"id": "B", "text": "Work on endangered languages"}, {"id": "C", "text": "Analysis of first-language development in infants"}, {"id": "D", "text": "Development of a writing system for a widely used language"}], "answer_id": "B"}, {"id": "LING-L01-Q080", "lecture_id": "LING-L01", "topic_id": "applications", "source_slides": [14, 15, 16], "difficulty": "hard", "cognitive_level": "analyze", "question": "A university serving speakers of several languages wants its notices to reach all students. Which research question most directly applies the lecture’s concern with language issues in multilingual societies?", "explanation": "The practical concern is access to information across language groups. Investigating who understands which languages and expressions can inform communication in a multilingual institution. The alternatives concern language too, but do not directly address this access problem.", "example": "A notice may need clear English and Urdu versions when a single version would leave some readers uncertain.", "reference_ids": ["lecture_01"], "options": [{"id": "A", "text": "How have the letter shapes on older campus signs changed over time?"}, {"id": "B", "text": "Which recurring sound patterns occur in one student’s early speech recordings?"}, {"id": "C", "text": "Which languages and wording would make the notices understandable to the student groups?"}, {"id": "D", "text": "How does one dictionary arrange the different meanings of a campus-related word?"}], "answer_id": "C"}]}, {"schema_version": "1.0.0", "lecture": {"id": "LING-L02", "number": 2, "title": "Branches of Linguistics", "language": "en", "source_filename": "Lec 2-branches of linguistics(1).ppt", "source_slide_count": 20, "question_count": 90, "scope": "Lecture 2; original examples apply the definitions and distinctions taught in the supplied slides. One brief externally referenced definition explains the anthropological branch named on slide 4.", "exam_alignment": "Concept-based practice. No past paper or official examination blueprint was supplied.", "answer_model": "Single best answer. answer_id refers to an option id, not its displayed position. Preserve option ids when shuffling.", "display_guidance": "In learning mode, display explanation followed by example after the learner answers. Source slides and clarification notes can appear in a reference panel."}, "references": [{"id": "lecture_02", "type": "user_supplied_slides", "title": "Lecture 2: Branches of Linguistics", "filename": "Lec 2-branches of linguistics(1).ppt", "library_file_id": "libfile_3f6e56e927d8819190bb25fe22b8968c"}, {"id": "utoronto_anthropology", "type": "authoritative_clarification", "organization": "Department of Anthropology, University of Toronto", "title": "Subfields", "url": "https://www.anthropology.utoronto.ca/node/9", "supports": "Introductory identification of the language-and-culture focus of linguistic anthropology, a field named but not defined on slide 4."}], "clarifications": [{"id": "CL01", "source_slides": [4, 5], "question_ids": ["LING-L02-Q002", "LING-L02-Q003", "LING-L02-Q005", "LING-L02-Q006"], "note": "Micro/macro categories follow the slides when explicitly tested. They are not treated as universally fixed boundaries, and overlapping fields are distinguished by the stated research focus."}, {"id": "CL02", "source_slides": [8], "question_ids": ["LING-L02-Q027", "LING-L02-Q028", "LING-L02-Q029", "LING-L02-Q030"], "note": "Although presented on a micro-labelled slide, lexicography is explicitly described there as dictionary compilation and a possible branch of applied linguistics."}, {"id": "CL03", "source_slides": [8], "question_ids": ["LING-L02-Q023"], "note": "The suffix -ly is adjective-forming in friendly. Questions do not generalize its function to every word ending in -ly."}, {"id": "CL04", "source_slides": [15], "question_ids": ["LING-L02-Q072"], "note": "Language acquisition is treated as a major psycholinguistic area. The slide’s unqualified ranking of it as the best-developed branch is not turned into an examination fact."}, {"id": "CL05", "source_slides": [17], "question_ids": ["LING-L02-Q080", "LING-L02-Q083", "LING-L02-Q084"], "note": "Computational linguistics studies natural language with computational tools and models. Programming languages may be tools. Merely using a computer does not make a project computational linguistics."}, {"id": "CL06", "source_slides": [18], "question_ids": ["LING-L02-Q085", "LING-L02-Q086", "LING-L02-Q087"], "note": "Brain damage is one source of neurolinguistic evidence, not a definition of the field’s entire scope. Behavioral difficulties are not treated as sufficient to locate a single brain region."}, {"id": "CL07", "source_slides": [4], "question_ids": ["LING-L02-Q090"], "note": "The overview’s label Anthropological is interpreted as the language-and-culture branch. Its brief introductory definition is externally referenced and clearly identified as clarification.", "reference_ids": ["utoronto_anthropology"]}, {"id": "CL08", "source_slides": [13, 14], "question_ids": ["LING-L02-Q069"], "note": "The slide’s wording about retrievable interpretations is explained as identifiable textual evidence and reasoning that readers can examine; it does not imply one mandatory response to a literary text."}], "coverage": [{"topic_id": "overview", "focus": "Overview and branch classification", "source_slides": [3, 4, 5, 6, 7, 9, 10, 11], "question_ids": ["LING-L02-Q001", "LING-L02-Q002", "LING-L02-Q003", "LING-L02-Q004", "LING-L02-Q005", "LING-L02-Q006"]}, {"topic_id": "phonetics", "focus": "Phonetics and its three subfields", "source_slides": [7], "question_ids": ["LING-L02-Q007", "LING-L02-Q008", "LING-L02-Q009", "LING-L02-Q010", "LING-L02-Q011", "LING-L02-Q012", "LING-L02-Q013", "LING-L02-Q014"]}, {"topic_id": "phonology", "focus": "Phonology and its relationship to phonetics", "source_slides": [6, 7], "question_ids": ["LING-L02-Q015", "LING-L02-Q016", "LING-L02-Q017", "LING-L02-Q018", "LING-L02-Q019", "LING-L02-Q020"]}, {"topic_id": "morphology", "focus": "Morphology and word structure", "source_slides": [7, 8, 9], "question_ids": ["LING-L02-Q021", "LING-L02-Q022", "LING-L02-Q023", "LING-L02-Q024", "LING-L02-Q025", "LING-L02-Q026"]}, {"topic_id": "lexicography", "focus": "Lexicography and dictionary compilation", "source_slides": [8, 9, 16], "question_ids": ["LING-L02-Q027", "LING-L02-Q028", "LING-L02-Q029", "LING-L02-Q030"]}, {"topic_id": "syntax", "focus": "Syntax and sentence structure", "source_slides": [8, 9], "question_ids": ["LING-L02-Q031", "LING-L02-Q032", "LING-L02-Q033", "LING-L02-Q034", "LING-L02-Q035", "LING-L02-Q036"]}, {"topic_id": "semantics", "focus": "Semantics and linguistic meaning", "source_slides": [9, 10], "question_ids": ["LING-L02-Q037", "LING-L02-Q038", "LING-L02-Q039", "LING-L02-Q040", "LING-L02-Q041", "LING-L02-Q042"]}, {"topic_id": "pragmatics", "focus": "Pragmatics and contextual interpretation", "source_slides": [9, 10, 11], "question_ids": ["LING-L02-Q043", "LING-L02-Q044", "LING-L02-Q045", "LING-L02-Q046", "LING-L02-Q047", "LING-L02-Q048", "LING-L02-Q049", "LING-L02-Q050"]}, {"topic_id": "sociolinguistics", "focus": "Sociolinguistics and social factors", "source_slides": [11, 16], "question_ids": ["LING-L02-Q051", "LING-L02-Q052", "LING-L02-Q053", "LING-L02-Q054", "LING-L02-Q055", "LING-L02-Q056", "LING-L02-Q057"]}, {"topic_id": "discourse", "focus": "Discourse analysis and connected language", "source_slides": [9, 12], "question_ids": ["LING-L02-Q058", "LING-L02-Q059", "LING-L02-Q060", "LING-L02-Q061", "LING-L02-Q062"]}, {"topic_id": "stylistics", "focus": "Stylistics and linguistic choices", "source_slides": [11, 13], "question_ids": ["LING-L02-Q063", "LING-L02-Q064", "LING-L02-Q065", "LING-L02-Q066"]}, {"topic_id": "literary_stylistics", "focus": "Literary stylistics and textual evidence", "source_slides": [14], "question_ids": ["LING-L02-Q067", "LING-L02-Q068", "LING-L02-Q069"]}, {"topic_id": "psycholinguistics", "focus": "Psycholinguistics and mental processing", "source_slides": [15, 18], "question_ids": ["LING-L02-Q070", "LING-L02-Q071", "LING-L02-Q072", "LING-L02-Q073", "LING-L02-Q074"]}, {"topic_id": "applied", "focus": "Applied and forensic linguistics", "source_slides": [16], "question_ids": ["LING-L02-Q075", "LING-L02-Q076", "LING-L02-Q077", "LING-L02-Q078", "LING-L02-Q079"]}, {"topic_id": "computational", "focus": "Computational linguistics and its aims", "source_slides": [15, 17], "question_ids": ["LING-L02-Q080", "LING-L02-Q081", "LING-L02-Q082", "LING-L02-Q083", "LING-L02-Q084"]}, {"topic_id": "neurolinguistics", "focus": "Neurolinguistics and the brain basis of language", "source_slides": [18], "question_ids": ["LING-L02-Q085", "LING-L02-Q086", "LING-L02-Q087"]}, {"topic_id": "cognitive", "focus": "Cognitive linguistics and information organization", "source_slides": [19], "question_ids": ["LING-L02-Q088", "LING-L02-Q089"]}, {"topic_id": "anthropological", "focus": "Anthropological branch: introductory identification", "source_slides": [4], "question_ids": ["LING-L02-Q090"]}], "excluded_slides": [{"slide": 1, "reason": "Opening slide with no substantive teaching text."}, {"slide": 2, "reason": "Section title only."}, {"slide": 20, "reason": "Closing thank-you slide."}], "topics": [{"id": "overview", "title": "Overview and branch classification", "question_count": 6}, {"id": "phonetics", "title": "Phonetics and its three subfields", "question_count": 8}, {"id": "phonology", "title": "Phonology and its relationship to phonetics", "question_count": 6}, {"id": "morphology", "title": "Morphology and word structure", "question_count": 6}, {"id": "lexicography", "title": "Lexicography and dictionary compilation", "question_count": 4}, {"id": "syntax", "title": "Syntax and sentence structure", "question_count": 6}, {"id": "semantics", "title": "Semantics and linguistic meaning", "question_count": 6}, {"id": "pragmatics", "title": "Pragmatics and contextual interpretation", "question_count": 8}, {"id": "sociolinguistics", "title": "Sociolinguistics and social factors", "question_count": 7}, {"id": "discourse", "title": "Discourse analysis and connected language", "question_count": 5}, {"id": "stylistics", "title": "Stylistics and linguistic choices", "question_count": 4}, {"id": "literary_stylistics", "title": "Literary stylistics and textual evidence", "question_count": 3}, {"id": "psycholinguistics", "title": "Psycholinguistics and mental processing", "question_count": 5}, {"id": "applied", "title": "Applied and forensic linguistics", "question_count": 5}, {"id": "computational", "title": "Computational linguistics and its aims", "question_count": 5}, {"id": "neurolinguistics", "title": "Neurolinguistics and the brain basis of language", "question_count": 3}, {"id": "cognitive", "title": "Cognitive linguistics and information organization", "question_count": 2}, {"id": "anthropological", "title": "Anthropological branch: introductory identification", "question_count": 1}], "statistics": {"difficulty": {"easy": 23, "medium": 48, "hard": 19}, "cognitive_level": {"understand": 15, "remember": 15, "analyze": 25, "apply": 35}, "answer_distribution": {"A": 23, "B": 23, "C": 22, "D": 22}}, "questions": [{"id": "LING-L02-Q001", "lecture_id": "LING-L02", "topic_id": "overview", "source_slides": [3], "difficulty": "easy", "cognitive_level": "understand", "question": "What connects the different branches of linguistics introduced in this lecture?", "explanation": "Linguistics studies language. Its branches ask different questions about structure, meaning, use, learning, and processing, while sharing language as their central subject.", "example": "A researcher can study either sentence structure or language choice in a community as part of linguistics.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "They all investigate spelling rather than speech."}, {"id": "B", "text": "They all concentrate on translating literary texts."}, {"id": "C", "text": "They investigate different aspects of human language."}, {"id": "D", "text": "They all prescribe a single correct accent."}], "answer_id": "C"}, {"id": "LING-L02-Q002", "lecture_id": "LING-L02", "topic_id": "overview", "source_slides": [4, 5], "difficulty": "easy", "cognitive_level": "remember", "question": "Which set consists entirely of microlinguistic branches in the classification used by these slides?", "explanation": "The slides place phonetics, phonology, morphology, syntax, semantics, and pragmatics under microlinguistics. This is the lecture’s organizing scheme rather than a universal boundary between disciplines.", "example": "Analysing how word parts combine falls under morphology in this scheme.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Phonology, sociolinguistics, and syntax"}, {"id": "B", "text": "Syntax, neurolinguistics, and discourse analysis"}, {"id": "C", "text": "Phonology, morphology, and syntax"}, {"id": "D", "text": "Morphology, psycholinguistics, and stylistics"}], "answer_id": "C"}, {"id": "LING-L02-Q003", "lecture_id": "LING-L02", "topic_id": "overview", "source_slides": [4, 5], "difficulty": "easy", "cognitive_level": "remember", "question": "Which set consists entirely of macrolinguistic fields as listed in the lecture?", "explanation": "The lecture groups these three fields under macrolinguistics. Each connects the study of language with broader questions about society, mental activity, or computation.", "example": "Investigating how computers process natural language belongs to computational linguistics.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Computational linguistics, semantics, and phonetics"}, {"id": "B", "text": "Psycholinguistics, syntax, and phonology"}, {"id": "C", "text": "Sociolinguistics, morphology, and computational linguistics"}, {"id": "D", "text": "Sociolinguistics, psycholinguistics, and computational linguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q004", "lecture_id": "LING-L02", "topic_id": "overview", "source_slides": [5, 6], "difficulty": "medium", "cognitive_level": "understand", "question": "Which mapping follows the core-branch diagram in the lecture?", "explanation": "The diagram organizes core branches by their main focus. These labels are a useful starting point, although a real research question can involve more than one level.", "example": "Word endings suggest morphology, while the arrangement of words in a sentence suggests syntax.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Sounds: morphology; words: syntax; sentences: semantics; meaning: phonetics"}, {"id": "B", "text": "Sounds: phonetics/phonology; words: morphology; sentences: syntax; meaning: semantics/pragmatics"}, {"id": "C", "text": "Sounds: semantics; words: phonology; sentences: pragmatics; meaning: morphology"}, {"id": "D", "text": "Sounds: syntax; words: pragmatics; sentences: phonetics; meaning: phonology"}], "answer_id": "B"}, {"id": "LING-L02-Q005", "lecture_id": "LING-L02", "topic_id": "overview", "source_slides": [5, 7, 11], "difficulty": "hard", "cognitive_level": "analyze", "question": "A project measures pronunciation and relates its variation to speakers’ ages. How should its relationship to linguistic branches be understood?", "explanation": "Branches describe areas of focus, not sealed compartments. Physical measurements can supply evidence for a question about socially patterned pronunciation.", "example": "A researcher can measure vowel pronunciations and compare patterns across age groups.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "It can combine phonetic analysis with a sociolinguistic research question."}, {"id": "B", "text": "It cannot be linguistic research because it crosses branch boundaries."}, {"id": "C", "text": "It must be phonetics alone because recordings exclude social questions."}, {"id": "D", "text": "It must be sociolinguistics alone because sound measurements cannot contribute."}], "answer_id": "A"}, {"id": "LING-L02-Q006", "lecture_id": "LING-L02", "topic_id": "overview", "source_slides": [5, 9, 10], "difficulty": "medium", "cognitive_level": "analyze", "question": "Why should questions about whether pragmatics is a micro- or macro-field specify the lecture’s classification?", "explanation": "The slides place pragmatics under microlinguistics, but disciplinary groupings can vary. It is more useful to understand its subject than to treat a classification as an unchanging fact.", "example": "Interpreting a speaker’s indirect request remains a pragmatic question whichever course heading contains it.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Every linguistics textbook uses exactly the same grouping."}, {"id": "B", "text": "The word “pragmatics” has no identifiable area of study."}, {"id": "C", "text": "Such groupings are teaching conventions, while the field’s focus remains language use in context."}, {"id": "D", "text": "Pragmatics becomes phonetics when it is grouped differently."}], "answer_id": "C"}, {"id": "LING-L02-Q007", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "easy", "cognitive_level": "remember", "question": "Which question is most directly a phonetic question?", "explanation": "Phonetics investigates speech sounds as produced by speakers, transmitted as signals, and perceived by listeners. It differs from questions about words, sentence structure, or social variation.", "example": "A researcher might examine how a speaker’s tongue moves while producing a sound.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "How are clauses combined into a sentence?"}, {"id": "B", "text": "How are speech sounds produced, transmitted, or perceived?"}, {"id": "C", "text": "How are dictionary entries selected?"}, {"id": "D", "text": "How does language choice relate to social class?"}], "answer_id": "B"}, {"id": "LING-L02-Q008", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "easy", "cognitive_level": "remember", "question": "Which branch of phonetics studies the production of speech sounds in the vocal tract?", "explanation": "Articulatory phonetics examines how the speech organs produce sounds. The focus is the speaker’s physical production rather than the transmitted signal or the listener’s perception.", "example": "Studying how the lips close to produce /p/ is articulatory phonetics.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Articulatory phonetics"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Phonology"}, {"id": "D", "text": "Auditory phonetics"}], "answer_id": "A"}, {"id": "LING-L02-Q009", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher observes where the tongue touches the roof of the mouth during a consonant. Which subfield is most directly involved?", "explanation": "The evidence concerns the position and movement of a speech organ. That makes the primary focus articulatory, even if recordings or other tools support the observation.", "example": "Comparing tongue positions for two consonants investigates how they are produced.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Morphology"}, {"id": "B", "text": "Articulatory phonetics"}, {"id": "C", "text": "Acoustic phonetics"}, {"id": "D", "text": "Auditory phonetics"}], "answer_id": "B"}, {"id": "LING-L02-Q010", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "easy", "cognitive_level": "remember", "question": "Which branch of phonetics studies the physical speech signal as it travels from speaker to listener?", "explanation": "Acoustic phonetics concerns the physical properties of the speech signal. The vocal organs produce the signal, and the listener perceives it, but those are distinct points of focus.", "example": "Comparing the duration of two recorded vowels is an acoustic investigation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Auditory phonetics"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Syntax"}, {"id": "D", "text": "Articulatory phonetics"}], "answer_id": "B"}, {"id": "LING-L02-Q011", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher measures the duration and frequency patterns of recorded vowels without investigating tongue movement or listener judgments. Which subfield is the best match?", "explanation": "The measurements describe properties of the sound signal. Neither the production mechanism nor the listener’s response is the direct object of the analysis.", "example": "A display of a recording can help compare how long two vowel sounds last.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Auditory phonetics"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Acoustic phonetics"}, {"id": "D", "text": "Articulatory phonetics"}], "answer_id": "C"}, {"id": "LING-L02-Q012", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "easy", "cognitive_level": "remember", "question": "Which branch of phonetics focuses on listeners’ hearing and perception of speech sounds?", "explanation": "Auditory phonetics examines speech from the listener’s side. Acoustic phonetics examines the signal, while articulatory phonetics examines its physical production.", "example": "Asking listeners which sound they heard can provide evidence about speech perception.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Acoustic phonetics"}, {"id": "B", "text": "Auditory phonetics"}, {"id": "C", "text": "Articulatory phonetics"}, {"id": "D", "text": "Morphology"}], "answer_id": "B"}, {"id": "LING-L02-Q013", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "Participants hear a series of similar speech sounds and report whether they hear /b/ or /p/. Which phonetic subfield most directly matches the task?", "explanation": "The task records listeners’ perceptual responses. The experiment may manipulate acoustic signals, but the question asks specifically about what participants hear.", "example": "A listener may classify an ambiguous sound differently from another listener.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Auditory phonetics"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Articulatory phonetics"}, {"id": "D", "text": "Acoustic phonetics"}], "answer_id": "A"}, {"id": "LING-L02-Q014", "lecture_id": "LING-L02", "topic_id": "phonetics", "source_slides": [7], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which sequence correctly matches three observations to the phonetic subfields: lip movement, properties of the recorded signal, and listeners’ sound identification?", "explanation": "The sequence follows production, transmission, and perception. These are complementary perspectives on speech rather than three names for the same measurement.", "example": "One project can observe lip closure, analyse the recording, and ask listeners what they heard.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Auditory, articulatory, acoustic"}, {"id": "B", "text": "Acoustic, auditory, articulatory"}, {"id": "C", "text": "Articulatory, auditory, acoustic"}, {"id": "D", "text": "Articulatory, acoustic, auditory"}], "answer_id": "D"}, {"id": "LING-L02-Q015", "lecture_id": "LING-L02", "topic_id": "phonology", "source_slides": [7], "difficulty": "easy", "cognitive_level": "understand", "question": "What is the main focus of phonology in the lecture?", "explanation": "Phonology asks how sounds function together in a linguistic system. It examines patterns and relationships rather than only the physical properties of individual productions.", "example": "Investigating which sound combinations a language permits is a phonological question.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "The compilation of pronunciation dictionaries alone"}, {"id": "B", "text": "The organization of sounds within a language’s sound system"}, {"id": "C", "text": "The arrangement of paragraphs in written texts"}, {"id": "D", "text": "The physical movement of the tongue alone"}], "answer_id": "B"}, {"id": "LING-L02-Q016", "lecture_id": "LING-L02", "topic_id": "phonology", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher investigates why some sound sequences are permitted in one language but not another. Which branch is most directly involved?", "explanation": "The question concerns language-specific sound patterns. It asks about the organization of the sound system rather than the mechanics of producing one sound.", "example": "Two languages may allow different consonant sequences at the beginning of words.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Syntax"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Articulatory phonetics"}, {"id": "D", "text": "Phonology"}], "answer_id": "D"}, {"id": "LING-L02-Q017", "lecture_id": "LING-L02", "topic_id": "phonology", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "A student investigates whether exchanging two speech sounds changes word meanings in a particular language. Which branch provides the most direct perspective?", "explanation": "The question concerns the functional role of sounds within a language. Meaning-distinguishing sound relationships are part of phonological organization.", "example": "In English, replacing the first sound of “pin” with /b/ produces a different word, “bin.”", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Morphology"}, {"id": "B", "text": "Phonology"}, {"id": "C", "text": "Discourse analysis"}, {"id": "D", "text": "Acoustic phonetics"}], "answer_id": "B"}, {"id": "LING-L02-Q018", "lecture_id": "LING-L02", "topic_id": "phonology", "source_slides": [7], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which comparison best distinguishes phonetics from phonology?", "explanation": "The distinction is one of primary focus. Phonetic evidence can inform phonological analysis, so the fields interact rather than exclude each other.", "example": "Measuring a vowel’s duration is phonetic; explaining its role in a language’s sound patterns is phonological.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Phonetics examines social class; phonology examines dictionary design."}, {"id": "B", "text": "Phonetics examines written words; phonology examines sentence order."}, {"id": "C", "text": "Phonetics examines speech production, signals, and perception; phonology examines sound organization in linguistic systems."}, {"id": "D", "text": "Phonetics examines word meanings; phonology examines literary interpretation."}], "answer_id": "C"}, {"id": "LING-L02-Q019", "lecture_id": "LING-L02", "topic_id": "phonology", "source_slides": [7], "difficulty": "hard", "cognitive_level": "analyze", "question": "A study both measures consonant durations and asks how the consonants pattern in a language. Which description best fits the study?", "explanation": "A measurement describes the physical speech signal, while a question about patterned linguistic organization is phonological. Using both perspectives is a coherent research design.", "example": "Duration measurements can help investigate how a language organizes contrasting sound categories.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "It cannot be phonology because physical measurements are included."}, {"id": "B", "text": "It becomes syntax because it compares more than one sound."}, {"id": "C", "text": "It becomes lexicography because all sound patterns belong in dictionaries."}, {"id": "D", "text": "It uses phonetic evidence to investigate a phonological question."}], "answer_id": "D"}, {"id": "LING-L02-Q020", "lecture_id": "LING-L02", "topic_id": "phonology", "source_slides": [6, 7], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which pair of research questions keeps the analysis at the level of sound rather than word formation or sentence structure?", "explanation": "The first question concerns phonetics and the second phonology. The alternatives move to morphological, syntactic, semantic, lexicographic, or discourse concerns.", "example": "Tongue placement and permitted sound combinations are different questions about sounds.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "How is a consonant produced, and which consonant sequences does a language allow?"}, {"id": "B", "text": "What does a word mean, and how is a paragraph organized?"}, {"id": "C", "text": "How is a plural word formed, and where does the subject occur?"}, {"id": "D", "text": "How are dictionary meanings ordered, and how is an interview structured?"}], "answer_id": "A"}, {"id": "LING-L02-Q021", "lecture_id": "LING-L02", "topic_id": "morphology", "source_slides": [8], "difficulty": "easy", "cognitive_level": "remember", "question": "What does morphology study?", "explanation": "Morphology investigates internal word structure. Its units contribute meaning or grammatical information, so it differs from the study of speech sounds or whole conversations.", "example": "Analysing “helpful” into “help” and “-ful” is morphological analysis.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "How speech signals travel through the air"}, {"id": "B", "text": "How words are constructed from smaller meaningful or grammatical units"}, {"id": "C", "text": "How sentences form coherent conversations"}, {"id": "D", "text": "How social class influences language attitudes"}], "answer_id": "B"}, {"id": "LING-L02-Q022", "lecture_id": "LING-L02", "topic_id": "morphology", "source_slides": [8], "difficulty": "easy", "cognitive_level": "apply", "question": "The lecture analyses “friendly” as “friend” plus “-ly.” Which branch studies this construction?", "explanation": "The analysis divides a word into meaningful parts and explains how the parts combine. It is about word structure rather than the ordering of separate words in a sentence.", "example": "“Kindness” can similarly be analysed as “kind” plus “-ness.”", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Morphology"}, {"id": "B", "text": "Discourse analysis"}, {"id": "C", "text": "Phonology"}, {"id": "D", "text": "Syntax"}], "answer_id": "A"}, {"id": "LING-L02-Q023", "lecture_id": "LING-L02", "topic_id": "morphology", "source_slides": [8], "difficulty": "medium", "cognitive_level": "understand", "question": "What role does “-ly” have in the lecture’s example “friendly”?", "explanation": "In “friendly,” the suffix contributes to forming an adjective from a noun. Its role in this example should be identified from the actual word, rather than assuming that every “-ly” form is an adverb.", "example": "In “a friendly neighbor,” “friendly” describes the neighbor.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "It places “friend” into the past tense."}, {"id": "B", "text": "It changes the sentence from a statement into a question."}, {"id": "C", "text": "It combines with “friend” to form an adjective."}, {"id": "D", "text": "It combines with “friend” to mark a plural noun."}], "answer_id": "C"}, {"id": "LING-L02-Q024", "lecture_id": "LING-L02", "topic_id": "morphology", "source_slides": [8, 9], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which comparison correctly distinguishes morphology from syntax?", "explanation": "Both fields investigate linguistic structure, but at different primary levels. Morphology focuses on the makeup of a word, while syntax focuses on combinations of words.", "example": "“Unhelpful” has internal word structure; “The student was helpful” has sentence structure.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Morphology examines social identities; syntax examines brain injuries."}, {"id": "B", "text": "Morphology examines paragraph links; syntax examines dictionary selection."}, {"id": "C", "text": "Morphology examines structure within words; syntax examines how words form larger structures."}, {"id": "D", "text": "Morphology examines listeners’ hearing; syntax examines sound transmission."}], "answer_id": "C"}, {"id": "LING-L02-Q025", "lecture_id": "LING-L02", "topic_id": "morphology", "source_slides": [8], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher asks what grammatical information the ending contributes in “books” compared with “book.” Which branch is most directly involved?", "explanation": "The question concerns an ending within a word and the grammatical information it contributes. This directly matches the lecture’s description of smaller units with grammatical functions.", "example": "The ending “-s” in “books” marks more than one book.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Literary stylistics"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Morphology"}, {"id": "D", "text": "Pragmatics"}], "answer_id": "C"}, {"id": "LING-L02-Q026", "lecture_id": "LING-L02", "topic_id": "morphology", "source_slides": [7, 8], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which question is morphological rather than phonetic?", "explanation": "The correct question asks about a meaningful part of a word. The alternatives examine the signal, articulation, or perception of sounds, which are phonetic concerns.", "example": "In “unhappy,” “un-” contributes a negative meaning to the base “happy.”", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Where does the tongue move during the first vowel of “unhappy”?"}, {"id": "B", "text": "How long does the vowel last in a recording of “unhappy”?"}, {"id": "C", "text": "Which sound does a listener identify at the start of “unhappy”?"}, {"id": "D", "text": "What meaning does the prefix contribute in “unhappy”?"}], "answer_id": "D"}, {"id": "LING-L02-Q027", "lecture_id": "LING-L02", "topic_id": "lexicography", "source_slides": [8], "difficulty": "easy", "cognitive_level": "remember", "question": "Which activity defines lexicography in the lecture?", "explanation": "Lexicography concerns making dictionaries. It involves decisions about entries and the information users need about words, rather than only investigating one structural level of language.", "example": "Preparing definitions and examples for a learner’s dictionary is lexicographic work.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Investigating language processing after brain damage"}, {"id": "B", "text": "Compiling dictionaries"}, {"id": "C", "text": "Measuring speech signals"}, {"id": "D", "text": "Modelling sentence structure"}], "answer_id": "B"}, {"id": "LING-L02-Q028", "lecture_id": "LING-L02", "topic_id": "lexicography", "source_slides": [8], "difficulty": "medium", "cognitive_level": "apply", "question": "An editor decides which words to include in a learner’s dictionary and writes clear definitions with usage examples. Which field is most directly involved?", "explanation": "The editor is constructing a dictionary resource. Meaning and grammar can inform the work, but the practical focus on dictionary entries makes lexicography the best answer.", "example": "The editor may add a sample sentence to show how a difficult word is used.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Auditory phonetics"}, {"id": "B", "text": "Syntax"}, {"id": "C", "text": "Neurolinguistics"}, {"id": "D", "text": "Lexicography"}], "answer_id": "D"}, {"id": "LING-L02-Q029", "lecture_id": "LING-L02", "topic_id": "lexicography", "source_slides": [8, 16], "difficulty": "medium", "cognitive_level": "analyze", "question": "How should lexicography’s position in the slides be interpreted?", "explanation": "A slide’s location does not override its definition. The lecture explicitly connects lexicography with applied linguistics, so questions should preserve that qualification.", "example": "A learner’s dictionary can apply research on meaning and grammar to a practical reference tool.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "It is introduced beside micro-fields, but the slide also identifies dictionary compilation as an applied activity."}, {"id": "B", "text": "It is another name for the study of sound patterns."}, {"id": "C", "text": "It must study sounds only because it appears near morphology."}, {"id": "D", "text": "It cannot use linguistic analysis because dictionaries are practical resources."}], "answer_id": "A"}, {"id": "LING-L02-Q030", "lecture_id": "LING-L02", "topic_id": "lexicography", "source_slides": [8, 9], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which distinction best separates a lexicographic task from a primarily semantic research question?", "explanation": "The fields can overlap because dictionary makers need knowledge of meaning. The difference here is the goal: producing a dictionary entry versus investigating meaning itself.", "example": "Research on the meanings of “bank” can inform separate senses in a dictionary entry.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Choosing dictionary entries is syntactic; arranging words into clauses is lexicographic."}, {"id": "B", "text": "Designing a dictionary entry is lexicographic; investigating a word’s meaning relationships is semantic."}, {"id": "C", "text": "Studying meaning is unrelated to preparing useful dictionary entries."}, {"id": "D", "text": "Writing a definition is phonetic; measuring word meaning is articulatory."}], "answer_id": "B"}, {"id": "LING-L02-Q031", "lecture_id": "LING-L02", "topic_id": "syntax", "source_slides": [9], "difficulty": "easy", "cognitive_level": "remember", "question": "Which branch investigates the rules governing how words combine into sentences?", "explanation": "Syntax studies sentence structure and the organization of words into larger units. It is concerned with how a sentence is formed, rather than just with the parts inside a word.", "example": "The ordering of subject and verb is a syntactic concern.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Lexicography"}, {"id": "B", "text": "Syntax"}, {"id": "C", "text": "Acoustic phonetics"}, {"id": "D", "text": "Morphology"}], "answer_id": "B"}, {"id": "LING-L02-Q032", "lecture_id": "LING-L02", "topic_id": "syntax", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "A student investigates why “The child has arrived” is a well-formed ordinary English statement but “Child the arrived has” is not. Which branch is most directly involved?", "explanation": "The words are arranged differently, so the central issue is their structural combination. The contrast does not require a change in vocabulary or pronunciation.", "example": "Knowing word meanings alone does not tell a learner how to arrange “has,” “she,” and “left.”", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Sociolinguistics"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Phonetics"}, {"id": "D", "text": "Syntax"}], "answer_id": "D"}, {"id": "LING-L02-Q033", "lecture_id": "LING-L02", "topic_id": "syntax", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher compares how English and Urdu arrange subjects, objects, and verbs. Which branch most directly addresses this question?", "explanation": "The comparison concerns word arrangement and grammatical relationships within sentences. It therefore belongs primarily to syntax, even though other aspects of the languages may also differ.", "example": "Comparing where the verb appears in equivalent sentences is a syntactic comparison.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Syntax"}, {"id": "B", "text": "Morphology"}, {"id": "C", "text": "Lexicography"}, {"id": "D", "text": "Acoustic phonetics"}], "answer_id": "A"}, {"id": "LING-L02-Q034", "lecture_id": "LING-L02", "topic_id": "syntax", "source_slides": [8, 9], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which task is syntactic rather than morphological?", "explanation": "The syntactic task concerns how separate words combine into a larger unit. The alternatives concern parts within individual words, which are morphological questions.", "example": "Analysing the structure of “those two books” investigates a phrase rather than a suffix.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Explaining how “help” and “-ful” form “helpful”"}, {"id": "B", "text": "Explaining the plural ending in “students”"}, {"id": "C", "text": "Explaining how the words in “the very helpful student” form a phrase"}, {"id": "D", "text": "Explaining the negative prefix in “unhelpful”"}], "answer_id": "C"}, {"id": "LING-L02-Q035", "lecture_id": "LING-L02", "topic_id": "syntax", "source_slides": [9], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why does a study of sentence structure need to examine more than the meanings of individual words?", "explanation": "The same words can participate in different relationships when their arrangement changes. Syntax helps explain that organization, while semantics examines the meanings involved.", "example": "“The dog chased the cat” and “The cat chased the dog” use the same main words but assign different roles.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Grammatical relationships depend partly on how words are organized together."}, {"id": "B", "text": "Sentence structure is determined solely by how loudly words are spoken."}, {"id": "C", "text": "Dictionary order determines the grammatical role of every word."}, {"id": "D", "text": "Every word loses its meaning as soon as it enters a sentence."}], "answer_id": "A"}, {"id": "LING-L02-Q036", "lecture_id": "LING-L02", "topic_id": "syntax", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "Which research question is primarily about syntax rather than semantics?", "explanation": "The correct question asks about the placement of a grammatical element in sentence structure. The alternatives focus on meaning relationships and reference.", "example": "Comparing “She is ready” with “Is she ready?” draws attention to structural organization.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Where can an auxiliary occur when an English question is formed?"}, {"id": "B", "text": "Which objects can the word “vehicle” refer to?"}, {"id": "C", "text": "How are the meanings of “large” and “big” related?"}, {"id": "D", "text": "What meanings distinguish two senses of “bank”?"}], "answer_id": "A"}, {"id": "LING-L02-Q037", "lecture_id": "LING-L02", "topic_id": "semantics", "source_slides": [9], "difficulty": "easy", "cognitive_level": "remember", "question": "What does semantics study according to the lecture?", "explanation": "Semantics investigates linguistic meaning. It can examine words and whole sentences, including their relation to objects and situations that are real or imagined.", "example": "Asking what “vehicle” means is a semantic question.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "The selection of fonts for dictionary entries"}, {"id": "B", "text": "The physical transmission of speech sounds alone"}, {"id": "C", "text": "The social distribution of pronunciation alone"}, {"id": "D", "text": "Meaning, including how words and sentences relate to what they refer to or describe"}], "answer_id": "D"}, {"id": "LING-L02-Q038", "lecture_id": "LING-L02", "topic_id": "semantics", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher investigates how the meanings of “large” and “big” are related. Which branch is most directly involved?", "explanation": "The question concerns a relationship between word meanings. It is not primarily about how the words sound or where they occur in a sentence.", "example": "Comparing the meanings of “small” and “little” is another semantic investigation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Phonetics"}, {"id": "B", "text": "Syntax"}, {"id": "C", "text": "Semantics"}, {"id": "D", "text": "Neurolinguistics"}], "answer_id": "C"}, {"id": "LING-L02-Q039", "lecture_id": "LING-L02", "topic_id": "semantics", "source_slides": [9], "difficulty": "medium", "cognitive_level": "understand", "question": "Why can the meaning of a sentence about a dragon still be studied in semantics?", "explanation": "The lecture explicitly includes real or imaginary referents. A sentence can be meaningful and interpretable without describing something that exists in the actual world.", "example": "“The dragon guarded the tower” describes an understandable fictional situation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Every sentence about fiction belongs exclusively to phonetics."}, {"id": "B", "text": "An imaginary subject removes all possible linguistic meaning."}, {"id": "C", "text": "Semantic analysis can examine reference to imaginary entities as well as real ones."}, {"id": "D", "text": "Semantics studies only sentences whose subjects are visible."}], "answer_id": "C"}, {"id": "LING-L02-Q040", "lecture_id": "LING-L02", "topic_id": "semantics", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "A student asks how “The child opened the door” differs in meaning from “The child closed the door.” Which branch most directly addresses the difference?", "explanation": "Both sentences have a similar grammatical pattern, but they describe different events. The immediate comparison is about what the sentences mean.", "example": "“The lamp is on” and “The lamp is off” also differ in the situations they describe.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Semantics"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Discourse analysis"}, {"id": "D", "text": "Lexicography"}], "answer_id": "A"}, {"id": "LING-L02-Q041", "lecture_id": "LING-L02", "topic_id": "semantics", "source_slides": [9, 10], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which question focuses on conventional linguistic meaning rather than a particular speaker’s contextual intention?", "explanation": "The first question centres on the meaning encoded by an expression. The alternatives ask how a speaker uses that expression for a purpose in a specific interaction, which foregrounds pragmatics.", "example": "Understanding “closed” differs from inferring why someone chose to announce that a shop is closed.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Why did the speaker mention the closed shop to discourage a journey?"}, {"id": "B", "text": "Was the speaker indirectly asking the listener to leave?"}, {"id": "C", "text": "What does “closed” mean in the sentence “The shop is closed”?"}, {"id": "D", "text": "Did the listener interpret the remark as a complaint about opening hours?"}], "answer_id": "C"}, {"id": "LING-L02-Q042", "lecture_id": "LING-L02", "topic_id": "semantics", "source_slides": [9], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which comparison separates a syntactic question from a semantic question?", "explanation": "Sentence organization and sentence meaning are related but distinguishable concerns. A complete analysis may investigate both without treating them as identical.", "example": "For “The girl opened the window,” one can analyse the subject–verb–object arrangement and the event described.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Syntax asks how loud speech is; semantics asks where the tongue moves."}, {"id": "B", "text": "Syntax asks about social class; semantics asks about the age of a speaker."}, {"id": "C", "text": "Syntax asks how a sentence is structured; semantics asks what situation it describes."}, {"id": "D", "text": "Syntax asks who wrote a dictionary; semantics asks how its pages are numbered."}], "answer_id": "C"}, {"id": "LING-L02-Q043", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10], "difficulty": "easy", "cognitive_level": "remember", "question": "Which branch most directly investigates how context affects the interpretation of an utterance?", "explanation": "Pragmatics studies language use in communication. Time, place, participant relationships, and shared assumptions can influence what a speaker communicates.", "example": "A remark about a cold room can function as a request when the window is open.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Morphology"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Acoustic phonetics"}, {"id": "D", "text": "Pragmatics"}], "answer_id": "D"}, {"id": "LING-L02-Q044", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10], "difficulty": "medium", "cognitive_level": "apply", "question": "Beside an open window, a student says “It is cold in here” to get a classmate to close it. Which branch most directly studies this intended request?", "explanation": "The utterance literally describes temperature, but the context supports an additional intention. Pragmatics examines how the listener infers that intended use.", "example": "At a crowded table, “There is no space here” may similarly imply a request to move something.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Semantics"}, {"id": "B", "text": "Morphology"}, {"id": "C", "text": "Phonology"}, {"id": "D", "text": "Pragmatics"}], "answer_id": "D"}, {"id": "LING-L02-Q045", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher asks why a student uses a more formal request with a lecturer than with a close friend. The focus is how the relationship shapes the intended request. Which branch is most directly involved?", "explanation": "The lecturer–student or friendship relationship contributes to the interpretation and formulation of the request. This fits the lecture’s inclusion of social relationships within pragmatic context.", "example": "“Could you please help me?” may suit a situation in which a speaker wants to show respect.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Lexicography"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Pragmatics"}, {"id": "D", "text": "Morphology"}], "answer_id": "C"}, {"id": "LING-L02-Q046", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10], "difficulty": "medium", "cognitive_level": "apply", "question": "Different speakers say “I will meet you here tomorrow” in different places and on different days. Which branch studies how these circumstances determine the intended references?", "explanation": "Identifying the intended people, place, and day requires information about the utterance situation. The words alone do not name the same participants and location in every use.", "example": "“Here” can refer to a classroom in one conversation and a station in another.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Pragmatics"}, {"id": "B", "text": "Articulatory phonetics"}, {"id": "C", "text": "Morphology"}, {"id": "D", "text": "Lexicography"}], "answer_id": "A"}, {"id": "LING-L02-Q047", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10], "difficulty": "medium", "cognitive_level": "apply", "question": "A speaker says “The usual place?” expecting a friend to identify a familiar café. Which aspect of context is most important?", "explanation": "The speaker relies on common experience rather than naming the café. Pragmatics examines how assumptions about what the listener knows support communication.", "example": "Friends may understand “our teacher” without a name when they know which class is being discussed.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "The speaker’s assumption that the listener shares relevant knowledge"}, {"id": "B", "text": "The alphabetical position of “usual” in a dictionary"}, {"id": "C", "text": "The internal word structure of “place”"}, {"id": "D", "text": "The physical duration of each vowel in the question"}], "answer_id": "A"}, {"id": "LING-L02-Q048", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [9, 10], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which pair correctly separates a semantic focus from a pragmatic focus?", "explanation": "Meaning encoded in an expression and the communicative purpose of using it are different analytical concerns. They can both matter to understanding the same utterance.", "example": "A learner can know what “late” means yet miss that a teacher’s remark expresses dissatisfaction.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "The conventional meaning of “late” is syntactic; a complaint is phonological."}, {"id": "B", "text": "The conventional meaning of “late” is semantic; why a speaker calls someone “late” as a complaint is pragmatic."}, {"id": "C", "text": "The conventional meaning of “late” is acoustic; a complaint is morphological."}, {"id": "D", "text": "The position of “late” in a dictionary is pragmatic; the duration of its vowel is semantic."}], "answer_id": "B"}, {"id": "LING-L02-Q049", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why is the same sentence not guaranteed to communicate the same intended message in every situation?", "explanation": "The linguistic form contributes meaning, but its use can depend on circumstances. A listener may infer a warning, request, criticism, or neutral report from the same wording.", "example": "“There is a car coming” can report traffic or warn someone about to step into the road.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Sentence structure prevents speakers from implying anything beyond a literal description."}, {"id": "B", "text": "Dictionary definitions make interpretation independent of participants."}, {"id": "C", "text": "Its sound units automatically change meaning whenever the speaker moves."}, {"id": "D", "text": "Context and assumptions about participants can change what the speaker is doing with it."}], "answer_id": "D"}, {"id": "LING-L02-Q050", "lecture_id": "LING-L02", "topic_id": "pragmatics", "source_slides": [10, 11], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which project foregrounds pragmatics rather than sociolinguistic patterns across groups?", "explanation": "The first project focuses on interpreting a communicative act in context. The alternatives foreground the social distribution of language forms, choices, or attitudes. The fields may still overlap.", "example": "Understanding “Can you reach the salt?” as a request foregrounds pragmatic interpretation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Measuring which languages different occupational groups use most often"}, {"id": "B", "text": "Investigating attitudes toward regional varieties across a city"}, {"id": "C", "text": "Explaining how a listener infers an indirect request from one utterance in its immediate situation"}, {"id": "D", "text": "Comparing pronunciation patterns across age groups"}], "answer_id": "C"}, {"id": "LING-L02-Q051", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the central concern of sociolinguistics in the lecture?", "explanation": "Sociolinguistics studies how language relates to social life. The lecture includes social class, education, age, sex, ethnic origin, language choice, planning, and attitudes.", "example": "A study might ask whether different age groups favor different expressions.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "The physical production of individual sounds alone"}, {"id": "B", "text": "Relationships between language and social factors"}, {"id": "C", "text": "The placement of words in isolated sentences alone"}, {"id": "D", "text": "The design of word entries in dictionaries alone"}], "answer_id": "B"}, {"id": "LING-L02-Q052", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher compares vocabulary choices among younger and older speakers in Lahore. Which branch is most directly involved?", "explanation": "The question relates language use to age as a social factor. The location provides a setting, but the central comparison is between groups of speakers.", "example": "Researchers might compare the use of a recent slang term across age groups without assuming that age determines every individual’s choice.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Lexicography"}, {"id": "B", "text": "Neurolinguistics"}, {"id": "C", "text": "Sociolinguistics"}, {"id": "D", "text": "Syntax"}], "answer_id": "C"}, {"id": "LING-L02-Q053", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11], "difficulty": "medium", "cognitive_level": "apply", "question": "Bilingual speakers report when they choose Punjabi, Urdu, or English in different community settings. Which field most directly studies this pattern?", "explanation": "Language choice in multilingual communities is explicitly included in the lecture’s account of sociolinguistics. The issue concerns who uses which language and in what social circumstances.", "example": "A speaker might use one language at home and another in a formal meeting.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Lexicography"}, {"id": "B", "text": "Articulatory phonetics"}, {"id": "C", "text": "Morphology"}, {"id": "D", "text": "Sociolinguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q054", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11], "difficulty": "medium", "cognitive_level": "apply", "question": "Participants rate some accents as more prestigious than others. A researcher investigates these judgments as social attitudes. Which branch is most directly involved?", "explanation": "The research concerns beliefs and evaluations attached to language varieties. It studies the social attitudes themselves rather than assuming that an accent is inherently superior.", "example": "A community may associate a variety with education, even though that association is a social judgment.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Syntax"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Morphology"}, {"id": "D", "text": "Sociolinguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q055", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A team investigates which languages a multilingual community uses before advising on public-service language provision. Which pairing best describes the work?", "explanation": "The investigation concerns community language use, while the advice addresses a practical policy problem. Sociolinguistics and applied linguistics can therefore contribute to the same project.", "example": "Survey findings could inform which language versions of a public notice are needed.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Acoustic investigation contributing to automatic speech recognition"}, {"id": "B", "text": "Psycholinguistic investigation contributing to a language-learning programme"}, {"id": "C", "text": "Sociolinguistic investigation contributing to an applied language-planning task"}, {"id": "D", "text": "Morphological investigation contributing to a learner’s dictionary"}], "answer_id": "C"}, {"id": "LING-L02-Q056", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11], "difficulty": "hard", "cognitive_level": "analyze", "question": "A researcher finds an association between education level and a pronunciation pattern. Which interpretation is most careful?", "explanation": "Sociolinguistic findings describe relationships that need evidence and context. An association does not justify an absolute prediction about every person or a ranking of groups as linguistically inferior.", "example": "Two speakers with the same education level may still use different pronunciations.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Education alone necessarily determines every individual’s pronunciation."}, {"id": "B", "text": "The pattern proves that one group’s language has no grammar."}, {"id": "C", "text": "A social association makes any further analysis of language unnecessary."}, {"id": "D", "text": "The result describes a pattern in the sampled speakers and requires interpretation in its social context."}], "answer_id": "D"}, {"id": "LING-L02-Q057", "lecture_id": "LING-L02", "topic_id": "sociolinguistics", "source_slides": [11], "difficulty": "medium", "cognitive_level": "understand", "question": "Which set contains social factors explicitly included in the lecture’s description of sociolinguistics?", "explanation": "The listed factors describe dimensions of social grouping in the slide. They can be investigated in relation to language without assuming that all members of a group speak alike.", "example": "A study can compare patterns across age groups while also recording participants’ educational backgrounds.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Prefixes, suffixes, roots, word endings, and word classes"}, {"id": "B", "text": "Vowel duration, signal frequency, sound intensity, tongue position, and lip closure"}, {"id": "C", "text": "Dictionary entries, headwords, page numbers, definitions, and cross-references"}, {"id": "D", "text": "Social class, educational level, age, sex, and ethnic origin"}], "answer_id": "D"}, {"id": "LING-L02-Q058", "lecture_id": "LING-L02", "topic_id": "discourse", "source_slides": [12], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the main focus of discourse analysis as introduced in the lecture?", "explanation": "Discourse analysis examines connected language. Its focus goes beyond isolated words or sentences to how stretches of spoken or written language work together.", "example": "An interview contains linked questions and answers that can be studied as a larger interaction.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "How the tongue produces a single consonant"}, {"id": "B", "text": "How dictionary headwords are alphabetized"}, {"id": "C", "text": "How a suffix changes an individual word"}, {"id": "D", "text": "How language forms larger meaningful units such as paragraphs, conversations, and interviews"}], "answer_id": "D"}, {"id": "LING-L02-Q059", "lecture_id": "LING-L02", "topic_id": "discourse", "source_slides": [12], "difficulty": "medium", "cognitive_level": "apply", "question": "A student investigates how several sentences develop one argument across a paragraph. Which branch is most directly involved?", "explanation": "The student asks how sentences contribute to a larger meaningful whole. Analysing the paragraph as connected language makes discourse analysis the best answer.", "example": "One sentence may introduce a claim while the following sentences explain and support it.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Articulatory phonetics"}, {"id": "B", "text": "Discourse analysis"}, {"id": "C", "text": "Morphology"}, {"id": "D", "text": "Lexicography"}], "answer_id": "B"}, {"id": "LING-L02-Q060", "lecture_id": "LING-L02", "topic_id": "discourse", "source_slides": [12], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher studies how interview questions shape the sequence of answers and follow-up questions. Which field most directly fits this focus?", "explanation": "The object of analysis is the organization of a stretch of interaction. The researcher examines how contributions relate across the interview rather than analysing words in isolation.", "example": "A short answer can lead an interviewer to ask for clarification in the next turn.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Discourse analysis"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Phonology"}, {"id": "D", "text": "Morphology"}], "answer_id": "A"}, {"id": "LING-L02-Q061", "lecture_id": "LING-L02", "topic_id": "discourse", "source_slides": [9, 12], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which distinction best separates the lecture’s introductory accounts of syntax and discourse analysis?", "explanation": "The fields differ in their main unit and question, although they can interact. Discourse analysis can investigate both spoken and written material.", "example": "A clause’s word order is a syntactic concern; how that clause responds to an earlier question is a discourse concern.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Syntax studies word definitions; discourse analysis studies sound transmission."}, {"id": "B", "text": "Syntax foregrounds sentence structure; discourse analysis foregrounds connected stretches of language."}, {"id": "C", "text": "Syntax studies all social groups; discourse analysis studies the vocal organs."}, {"id": "D", "text": "Syntax studies speech only; discourse analysis studies writing only."}], "answer_id": "B"}, {"id": "LING-L02-Q062", "lecture_id": "LING-L02", "topic_id": "discourse", "source_slides": [12], "difficulty": "medium", "cognitive_level": "understand", "question": "Which set could all serve as data for discourse analysis under the lecture’s definition?", "explanation": "Each item contains connected language whose parts can contribute to a larger meaning or interaction. Discourse analysis is not restricted to formal written paragraphs.", "example": "A recorded conversation and a written interview can both be examined for how their parts connect.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "A prefix list, a suffix list, and a list of roots"}, {"id": "B", "text": "A paragraph, a conversation, and an interview"}, {"id": "C", "text": "A tongue-position diagram, a vowel waveform, and a lip-motion image"}, {"id": "D", "text": "A dictionary’s page size, binding type, and printing cost"}], "answer_id": "B"}, {"id": "LING-L02-Q063", "lecture_id": "LING-L02", "topic_id": "stylistics", "source_slides": [13], "difficulty": "easy", "cognitive_level": "understand", "question": "What does stylistics investigate in the lecture?", "explanation": "Stylistics asks how choices in language contribute to a particular style or effect. It can examine choices made by individuals or social groups in specific situations.", "example": "A public notice and a friendly message may use different wording to suit different purposes.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Linguistic choices and variation in relation to situation and intended effects"}, {"id": "B", "text": "The identification of all words with the same ending"}, {"id": "C", "text": "The physical hearing of sounds without considering language choices"}, {"id": "D", "text": "The location of language functions in brain tissue"}], "answer_id": "A"}, {"id": "LING-L02-Q064", "lecture_id": "LING-L02", "topic_id": "stylistics", "source_slides": [13], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher compares an advertisement’s short sentences and vivid vocabulary with a formal report to explain their different effects on readers. Which branch is foregrounded?", "explanation": "The analysis connects identifiable language choices with style and communicative effect. It does more than label one text as interesting or another as formal.", "example": "An advertisement may repeat a short phrase to make its message memorable.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Auditory phonetics"}, {"id": "B", "text": "Neurolinguistics"}, {"id": "C", "text": "Stylistics"}, {"id": "D", "text": "Lexicography"}], "answer_id": "C"}, {"id": "LING-L02-Q065", "lecture_id": "LING-L02", "topic_id": "stylistics", "source_slides": [13], "difficulty": "medium", "cognitive_level": "apply", "question": "A speaker chooses brief, repeated phrases to make a public address sound urgent. Which research question is most directly stylistic?", "explanation": "A stylistic question links features of the wording to the effect the speaker seeks. Physical measurement, perception, and automatic transcription ask different primary questions.", "example": "Repeating “Act now” may create urgency, which the analyst should support with evidence from the speech.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Which software converts the recording into a written transcript?"}, {"id": "B", "text": "Which participants have difficulty hearing the speech?"}, {"id": "C", "text": "How do the chosen phrases and repetition contribute to the sense of urgency?"}, {"id": "D", "text": "How long does each vowel last in milliseconds?"}], "answer_id": "C"}, {"id": "LING-L02-Q066", "lecture_id": "LING-L02", "topic_id": "stylistics", "source_slides": [11, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which focus most clearly foregrounds stylistics rather than a sociolinguistic survey of group differences?", "explanation": "The first focus connects textual choices with style and effect. The other questions foreground social distribution or attitudes. These interests can overlap in broader research.", "example": "Examining how a notice achieves an impersonal tone is a stylistic analysis.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Comparing which regional accents listeners rate most favorably"}, {"id": "B", "text": "Explaining how a writer’s sentence and vocabulary choices create a formal tone in a particular text"}, {"id": "C", "text": "Investigating language choice across occupational groups"}, {"id": "D", "text": "Comparing age groups’ reported use of a local variety"}], "answer_id": "B"}, {"id": "LING-L02-Q067", "lecture_id": "LING-L02", "topic_id": "literary_stylistics", "source_slides": [14], "difficulty": "easy", "cognitive_level": "understand", "question": "What makes literary stylistics distinct within the lecture’s account of stylistics?", "explanation": "Literary stylistics uses evidence from linguistic form to support interpretations of literature. The lecture includes fiction, drama, and poetry among the genres that can be compared.", "example": "An analyst can examine repeated sentence patterns in a poem to support an interpretation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "It applies linguistic methods to the interpretation and comparison of literary texts."}, {"id": "B", "text": "It replaces all textual evidence with a reader’s personal preference."}, {"id": "C", "text": "It deals only with the physical printing of novels."}, {"id": "D", "text": "It evaluates literature without examining its language."}], "answer_id": "A"}, {"id": "LING-L02-Q068", "lecture_id": "LING-L02", "topic_id": "literary_stylistics", "source_slides": [14], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher analyses sound repetition, word choices, and sentence patterns in a poem to explain its effect. Which field is the most direct match?", "explanation": "The object is a literary text, and the method connects linguistic evidence to interpretation. Several linguistic levels may contribute to one literary stylistic analysis.", "example": "Repeated sounds may reinforce a pattern that also appears in the poem’s vocabulary.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Language planning"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Neurolinguistics"}, {"id": "D", "text": "Literary stylistics"}], "answer_id": "D"}, {"id": "LING-L02-Q069", "lecture_id": "LING-L02", "topic_id": "literary_stylistics", "source_slides": [14], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which approach best supports the lecture’s aim of making literary interpretations retrievable and comparable?", "explanation": "An interpretation is easier to assess when readers can locate the evidence and follow the reasoning. Linguistic analysis can make that reasoning explicit without requiring identical responses from all readers.", "example": "An analyst can point to repeated questions in a dramatic speech and explain their contribution to uncertainty.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "State that a poem feels powerful without identifying any textual features."}, {"id": "B", "text": "Assume that every reader must respond identically to each sentence."}, {"id": "C", "text": "Identify specific linguistic patterns and show how they support the proposed interpretation."}, {"id": "D", "text": "Rank texts only by the personal reputation of their authors."}], "answer_id": "C"}, {"id": "LING-L02-Q070", "lecture_id": "LING-L02", "topic_id": "psycholinguistics", "source_slides": [15], "difficulty": "easy", "cognitive_level": "remember", "question": "Which field studies mental processes involved in planning, producing, perceiving, and understanding language?", "explanation": "Psycholinguistics investigates language as a mental activity. It asks how users learn, produce, and understand language, rather than limiting itself to the outward forms of sentences.", "example": "A researcher may investigate how a listener retrieves the meaning of a familiar word.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Literary stylistics"}, {"id": "B", "text": "Lexicography"}, {"id": "C", "text": "Sociolinguistics"}, {"id": "D", "text": "Psycholinguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q071", "lecture_id": "LING-L02", "topic_id": "psycholinguistics", "source_slides": [15], "difficulty": "medium", "cognitive_level": "apply", "question": "An experiment investigates how memory demands affect a listener’s understanding of long sentences. Which field is most directly involved?", "explanation": "The question connects comprehension with a mental resource: memory. The lecture explicitly gives memory limitations as an example of a psycholinguistic concern.", "example": "A listener may struggle to retain the beginning of a sentence while processing a long continuation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Psycholinguistics"}, {"id": "B", "text": "Sociolinguistics"}, {"id": "C", "text": "Lexicography"}, {"id": "D", "text": "Articulatory phonetics"}], "answer_id": "A"}, {"id": "LING-L02-Q072", "lecture_id": "LING-L02", "topic_id": "psycholinguistics", "source_slides": [15], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher tracks how children learn to produce and understand their first language. Which field named in the lecture directly includes this area?", "explanation": "Language acquisition is a major area discussed under psycholinguistics in the lecture. The study concerns the development of linguistic knowledge and processing abilities.", "example": "A researcher may record changes in a child’s word combinations over several months.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Literary stylistics"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Lexicography"}, {"id": "D", "text": "Psycholinguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q073", "lecture_id": "LING-L02", "topic_id": "psycholinguistics", "source_slides": [15], "difficulty": "medium", "cognitive_level": "apply", "question": "A study investigates how speakers select words and plan an utterance before saying it. Which field is most directly involved?", "explanation": "The primary question concerns mental processes of language production. A conversation could provide data, but the focus is planning an utterance rather than organizing the exchange as a whole.", "example": "A speaker may pause while retrieving a word needed to complete a message.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Psycholinguistics"}, {"id": "B", "text": "Sociolinguistics"}, {"id": "C", "text": "Lexicography"}, {"id": "D", "text": "Discourse analysis"}], "answer_id": "A"}, {"id": "LING-L02-Q074", "lecture_id": "LING-L02", "topic_id": "psycholinguistics", "source_slides": [15, 18], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which distinction best separates psycholinguistics from neurolinguistics at the introductory level?", "explanation": "The fields overlap because mental processing is supported by the brain. The distinction is the primary explanatory focus, not an absolute separation between unrelated subjects.", "example": "A memory-load task foregrounds processing; relating language performance to brain damage foregrounds the neural basis.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Psycholinguistics excludes comprehension; neurolinguistics excludes production."}, {"id": "B", "text": "Psycholinguistics studies writing only; neurolinguistics studies speech only."}, {"id": "C", "text": "Psycholinguistics foregrounds mental language processes; neurolinguistics foregrounds their brain basis."}, {"id": "D", "text": "Psycholinguistics studies social class; neurolinguistics studies dictionary entries."}], "answer_id": "C"}, {"id": "LING-L02-Q075", "lecture_id": "LING-L02", "topic_id": "applied", "source_slides": [16], "difficulty": "easy", "cognitive_level": "understand", "question": "What is the main concern of applied linguistics in the lecture?", "explanation": "Applied linguistics connects knowledge about language with real needs. The lecture includes teaching, policy, translation, advertising, classrooms, and legal contexts.", "example": "Research on learners’ difficulties can inform improvements to language lessons.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Using linguistic methods and findings to address practical language-related problems"}, {"id": "B", "text": "Compiling every possible sentence into a single dictionary"}, {"id": "C", "text": "Restricting language research to the mechanics of sound transmission"}, {"id": "D", "text": "Avoiding practical settings in favor of isolated examples only"}], "answer_id": "A"}, {"id": "LING-L02-Q076", "lecture_id": "LING-L02", "topic_id": "applied", "source_slides": [16], "difficulty": "medium", "cognitive_level": "apply", "question": "A team uses evidence about learners’ difficulties to revise an English teaching programme. Which field is most directly reflected in this practical goal?", "explanation": "The programme revision applies linguistic research to teaching. Other branches may provide evidence, but the goal of improving instruction makes the project applied.", "example": "Lessons may be redesigned after evidence shows that students misinterpret common instructions.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Literary stylistics"}, {"id": "B", "text": "Historical sound analysis"}, {"id": "C", "text": "Applied linguistics"}, {"id": "D", "text": "Acoustic phonetics"}], "answer_id": "C"}, {"id": "LING-L02-Q077", "lecture_id": "LING-L02", "topic_id": "applied", "source_slides": [16], "difficulty": "medium", "cognitive_level": "apply", "question": "A linguist examines the wording of a disputed confession in a legal case. Which application named in the lecture is the most direct match?", "explanation": "Forensic linguistics concerns language in legal settings. The scenario involves analysing language as evidence in a case, rather than deciding the legal outcome itself.", "example": "An analysis may examine whether the wording of a statement is clear or open to more than one interpretation.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Articulatory phonetics"}, {"id": "B", "text": "Dictionary compilation"}, {"id": "C", "text": "Literary stylistics"}, {"id": "D", "text": "Forensic linguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q078", "lecture_id": "LING-L02", "topic_id": "applied", "source_slides": [16], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher uses linguistic evidence to help translators make public-health messages understandable in another language. Which field best captures this practical purpose?", "explanation": "The purpose is to improve communication through translation. Meaning, vocabulary, and context can all contribute evidence to this applied task.", "example": "A translator may replace an unfamiliar technical expression with a clear equivalent suited to the intended readers.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Applied linguistics"}, {"id": "B", "text": "Literary stylistics"}, {"id": "C", "text": "Acoustic phonetics"}, {"id": "D", "text": "Phonological pattern description"}], "answer_id": "A"}, {"id": "LING-L02-Q079", "lecture_id": "LING-L02", "topic_id": "applied", "source_slides": [16], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which project best demonstrates the broad scope of applied linguistics presented in the lecture?", "explanation": "The distinguishing emphasis is the practical language-related purpose. Applied linguistics can draw on several branches and is not restricted to classroom teaching.", "example": "Improving the clarity of official forms and improving language lessons are different applied tasks.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Using linguistic analysis to improve teaching, policy communication, translation, or courtroom language practices"}, {"id": "B", "text": "Studying a poem’s structure solely to propose an interpretation of that poem"}, {"id": "C", "text": "Listing grammatical patterns without considering any use for the findings"}, {"id": "D", "text": "Measuring vowel frequency while deliberately excluding any practical language question"}], "answer_id": "A"}, {"id": "LING-L02-Q080", "lecture_id": "LING-L02", "topic_id": "computational", "source_slides": [17], "difficulty": "easy", "cognitive_level": "understand", "question": "What is the primary object of study in computational linguistics as described in the lecture?", "explanation": "Computational linguistics investigates human languages with computational methods. A programming language may be used as a tool, but natural language remains the object being analysed or modelled.", "example": "A researcher can use a program to analyse English sentences without treating the program’s language as the research target.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Computer programming syntax without any human-language question"}, {"id": "B", "text": "Natural language investigated through computational methods and models"}, {"id": "C", "text": "Computer hardware without any language-processing task"}, {"id": "D", "text": "Handwritten letter shapes without any computational analysis"}], "answer_id": "B"}, {"id": "LING-L02-Q081", "lecture_id": "LING-L02", "topic_id": "computational", "source_slides": [17], "difficulty": "medium", "cognitive_level": "apply", "question": "A system automatically translates an Urdu sentence into English. Which field most directly addresses the computational processing involved?", "explanation": "Automatic translation requires computational handling of natural language. Translation can also be an applied concern, but the question specifically foregrounds the automated processing.", "example": "A translation program must produce an output that represents the source message in another language.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Language-attitude research"}, {"id": "B", "text": "Literary stylistics"}, {"id": "C", "text": "Articulatory phonetics"}, {"id": "D", "text": "Computational linguistics"}], "answer_id": "D"}, {"id": "LING-L02-Q082", "lecture_id": "LING-L02", "topic_id": "computational", "source_slides": [17], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which pairing correctly distinguishes automatic speech recognition from artificial speech production?", "explanation": "The lecture lists both recognizing human speech and producing artificial speech as computational areas. One deals with input, while the other creates an output signal.", "example": "Voice typing recognizes speech; a device reading a written message aloud produces artificial speech.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Recognition studies word endings; speech production studies only paragraph links."}, {"id": "B", "text": "Recognition interprets spoken input; speech production generates a spoken output."}, {"id": "C", "text": "Recognition generates a voice; speech production records a listener’s opinion."}, {"id": "D", "text": "Recognition compiles dictionary meanings; speech production ranks regional accents."}], "answer_id": "B"}, {"id": "LING-L02-Q083", "lecture_id": "LING-L02", "topic_id": "computational", "source_slides": [17], "difficulty": "medium", "cognitive_level": "understand", "question": "Which project best matches the technological aim of computational linguistics in the lecture?", "explanation": "The technological aim concerns making computers useful for natural-language analysis and processing. The defining feature is the computational language task rather than the mere presence of a computer.", "example": "A tool that converts spoken requests into usable instructions pursues a technological language-processing goal.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Developing a computer tool that analyses and processes natural-language input"}, {"id": "B", "text": "Surveying language attitudes without a computational processing goal"}, {"id": "C", "text": "Explaining a poem’s imagery without a computational method"}, {"id": "D", "text": "Comparing tongue positions without using a language-processing model"}], "answer_id": "A"}, {"id": "LING-L02-Q084", "lecture_id": "LING-L02", "topic_id": "computational", "source_slides": [15, 17], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which project best matches the lecture’s psychological aim of computational linguistics?", "explanation": "A computational model can be used to explore how people process language. The psychological aim is understanding human processing, rather than producing a tool merely because it uses a computer.", "example": "Researchers might ask whether a model’s difficulty with particular sentences resembles the difficulty observed in people.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Testing a computational model against patterns of human language processing"}, {"id": "B", "text": "Generating clearer synthetic announcements solely for a station’s public-address system"}, {"id": "C", "text": "Improving an automatic translator solely to increase its translation accuracy"}, {"id": "D", "text": "Increasing a voice-typing tool’s transcription accuracy solely for its users"}], "answer_id": "A"}, {"id": "LING-L02-Q085", "lecture_id": "LING-L02", "topic_id": "neurolinguistics", "source_slides": [18], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the central focus of neurolinguistics in the lecture?", "explanation": "Neurolinguistics investigates the neural basis of language. The lecture includes disturbances of comprehension and production associated with brain damage as one important line of evidence.", "example": "A researcher may relate a change in language abilities to evidence about an affected brain region.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "The ordering of entries in dictionaries"}, {"id": "B", "text": "Language processing and representation in the brain"}, {"id": "C", "text": "The social prestige of different accents"}, {"id": "D", "text": "The effect of sentence repetition in literary texts"}], "answer_id": "B"}, {"id": "LING-L02-Q086", "lecture_id": "LING-L02", "topic_id": "neurolinguistics", "source_slides": [18], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher relates changes in a patient’s language comprehension to evidence of brain injury. Which field is most directly involved?", "explanation": "The study connects language performance with the brain. It therefore foregrounds a neural explanation rather than a social pattern or a dictionary task.", "example": "A project can compare which language tasks are difficult after an injury without assuming that every patient has the same difficulties.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Sociolinguistics"}, {"id": "B", "text": "Neurolinguistics"}, {"id": "C", "text": "Lexicography"}, {"id": "D", "text": "Literary stylistics"}], "answer_id": "B"}, {"id": "LING-L02-Q087", "lecture_id": "LING-L02", "topic_id": "neurolinguistics", "source_slides": [18], "difficulty": "medium", "cognitive_level": "understand", "question": "Why does the lecture discuss disturbances of both language production and comprehension under neurolinguistics?", "explanation": "Producing and understanding language both depend on neural processes. Studying difficulties in either can inform research, but a behavioral observation alone does not establish a precise neural explanation.", "example": "Difficulty understanding spoken instructions and difficulty producing a sentence can motivate different language assessments.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Production belongs to the brain, but comprehension is unrelated to it."}, {"id": "B", "text": "Comprehension belongs to the brain, but production is only a social convention."}, {"id": "C", "text": "A change in language automatically identifies one exact brain location without further evidence."}, {"id": "D", "text": "Changes in either ability can provide evidence about the brain basis of language."}], "answer_id": "D"}, {"id": "LING-L02-Q088", "lecture_id": "LING-L02", "topic_id": "cognitive", "source_slides": [19], "difficulty": "easy", "cognitive_level": "understand", "question": "How does the lecture characterize the focus of cognitive linguistics?", "explanation": "The slide presents a perspective connecting language with cognition. It draws attention to how linguistic expressions help users organize and communicate information.", "example": "A researcher can investigate how speakers use linguistic categories to organize what they describe.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Language as a means of organizing, processing, and conveying information"}, {"id": "B", "text": "Language as a set of dictionary entries unrelated to thought"}, {"id": "C", "text": "Language as a legal procedure for establishing institutional authority"}, {"id": "D", "text": "Language as a speech signal studied without interpretation"}], "answer_id": "A"}, {"id": "LING-L02-Q089", "lecture_id": "LING-L02", "topic_id": "cognitive", "source_slides": [19], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher asks how linguistic categories help speakers organize information about their experience. Which approach is the closest match to the lecture’s description?", "explanation": "The question concerns language as a resource for organizing information. This is a cognitive focus, although related work can overlap with research on meaning or mental processing.", "example": "Researchers might examine how a general category such as “vehicle” organizes descriptions of cars and buses.", "reference_ids": ["lecture_02"], "options": [{"id": "A", "text": "Forensic linguistics"}, {"id": "B", "text": "Cognitive linguistics"}, {"id": "C", "text": "Acoustic phonetics"}, {"id": "D", "text": "Lexicography"}], "answer_id": "B"}, {"id": "LING-L02-Q090", "lecture_id": "LING-L02", "topic_id": "anthropological", "source_slides": [4], "difficulty": "medium", "cognitive_level": "understand", "question": "The overview names an anthropological branch without developing its definition. Which introductory description best identifies this field?", "explanation": "Linguistic anthropology examines language within social and cultural practices. This brief definition supplies context for a field named in the overview, rather than adding a new detailed topic to the lecture.", "example": "A researcher might study how ceremonial ways of speaking help transmit community traditions.", "reference_ids": ["lecture_02", "utoronto_anthropology"], "options": [{"id": "A", "text": "The measurement of speech signals without examining their cultural use"}, {"id": "B", "text": "The study of language in relation to cultural practices and social life"}, {"id": "C", "text": "The compilation of software commands without a question about human communication"}, {"id": "D", "text": "The analysis of word endings without examining community practices"}], "answer_id": "B"}]}, {"schema_version": "1.0.0", "lecture": {"id": "LING-L03", "number": 3, "title": "Phonetics and Phonology", "language": "en", "source_filename": "Lec 3 Phonetics(1).ppt", "source_slide_count": 22, "question_count": 100, "scope": "Lecture 3, including the figures on slides 7 and 8. Original scenarios and introductory explanations unpack the terms taught in the slides. Figure questions contain written descriptions and require no separate image assets.", "exam_alignment": "Concept-based practice. No past paper or official examination blueprint was supplied.", "answer_model": "Single best answer. answer_id refers to an option id, not its displayed position. Preserve option ids when shuffling.", "display_guidance": "In learning mode, display explanation followed by example after the learner answers. Source slides and clarification notes can appear in a reference panel. Display phonetic symbols with a Unicode-capable font."}, "references": [{"id": "lecture_03", "type": "user_supplied_slides", "title": "Lecture 3: Phonetics", "filename": "Lec 3 Phonetics(1).ppt", "library_file_id": "libfile_a2d367a3ea4c81919554cd579715d239"}, {"id": "eol_phonemes", "type": "scholarly_clarification", "title": "4.1 Phonemes and allophones", "publication": "Essentials of Linguistics, 2nd edition", "authors": ["Catherine Anderson", "Bronwyn Bjorkman", "Derek Denis", "Julianne Doner", "Margaret Grant", "Nathan Sanders", "Ai Taniguchi"], "url": "https://ecampusontario.pressbooks.pub/essentialsoflinguistics2/chapter/4-1-phonemes-and-allophones/", "supports": "An accent-specific realization of /t/ in writer illustrates why phonemic labels should not be equated with identical physical tokens."}, {"id": "ncvs_spectrogram", "type": "authoritative_clarification", "organization": "National Center for Voice and Speech", "title": "The Spectrograph and Spectral Analysis", "url": "https://ncvs.org/tutorials/the-spectrograph-and-spectral-analysis/", "supports": "Spectrograms represent frequency-component strengths through time; formant patterns and fundamental frequency are distinct, and analysis settings affect the display."}], "clarifications": [{"id": "CL01", "source_slides": [11, 12, 13], "question_ids": ["LING-L03-Q067", "LING-L03-Q068", "LING-L03-Q069"], "note": "Phonology is not treated as merely a subset of phonetics or as only a phoneme list. The fields interact; phonology also studies combinations and contextual realization."}, {"id": "CL02", "source_slides": [6, 7], "question_ids": ["LING-L03-Q040", "LING-L03-Q046", "LING-L03-Q051"], "note": "Spectrogram darkness is interpreted under a specified display convention. No rule assumes that vowels are always darkest or that every band directly identifies a phoneme.", "reference_ids": ["ncvs_spectrogram"]}, {"id": "CL03", "source_slides": [7, 8], "question_ids": ["LING-L03-Q047", "LING-L03-Q048", "LING-L03-Q049", "LING-L03-Q050", "LING-L03-Q051", "LING-L03-Q052"], "note": "The figures are tested through written descriptions. Exact numerical values are not inferred from their unlabelled scales; numerical scenarios supply their own values."}, {"id": "CL04", "source_slides": [15, 16, 17, 18, 19], "note": "A phone is a physical sound realization; a phoneme is an abstract contrastive category. Neither the smallest perceptible unit wording nor the claim that phones are absolute is treated as an unqualified experimental fact."}, {"id": "CL05", "source_slides": [13, 18], "question_ids": ["LING-L03-Q083", "LING-L03-Q084"], "note": "The /t/ examples do not imply identical pronunciations across contexts or accents. A flap in writer is presented only as a possible accent-specific realization.", "reference_ids": ["eol_phonemes"]}, {"id": "CL06", "source_slides": [21], "question_ids": ["LING-L03-Q095", "LING-L03-Q098"], "note": "The /i/ notation in bead and bean follows the slide’s stated convention. Other descriptions may use /iː/. Brackets identify phonetic representation, not a guarantee that every acoustic detail is shown."}, {"id": "CL07", "source_slides": [4, 5], "question_ids": ["LING-L03-Q012", "LING-L03-Q013", "LING-L03-Q014", "LING-L03-Q015", "LING-L03-Q027", "LING-L03-Q028", "LING-L03-Q029"], "note": "Basic explanatory definitions unpack airstream, voicing, amplitude, and fundamental frequency. No detailed inventory of places/manners of articulation or advanced acoustic calculations is added."}, {"id": "CL08", "source_slides": [14], "question_ids": ["LING-L03-Q094"], "note": "The examples θ and ð are retained as sound symbols, but the slide’s shared Greek-alphabet label is not used as an etymological claim or an examination fact."}], "coverage": [{"topic_id": "overview", "focus": "Phonetics: scope, evidence, and subfields", "source_slides": [2, 3, 4, 5, 9], "question_ids": ["LING-L03-Q001", "LING-L03-Q002", "LING-L03-Q003", "LING-L03-Q004", "LING-L03-Q005", "LING-L03-Q006", "LING-L03-Q007", "LING-L03-Q008"]}, {"topic_id": "articulatory", "focus": "Vocal apparatus, airstream, voicing, and articulation", "source_slides": [2, 4, 5, 9], "question_ids": ["LING-L03-Q009", "LING-L03-Q010", "LING-L03-Q011", "LING-L03-Q012", "LING-L03-Q013", "LING-L03-Q014", "LING-L03-Q015", "LING-L03-Q016", "LING-L03-Q017", "LING-L03-Q018", "LING-L03-Q019", "LING-L03-Q020", "LING-L03-Q021", "LING-L03-Q022"]}, {"topic_id": "acoustic", "focus": "Duration, amplitude, fundamental frequency, and spectra", "source_slides": [5, 9], "question_ids": ["LING-L03-Q023", "LING-L03-Q024", "LING-L03-Q025", "LING-L03-Q026", "LING-L03-Q027", "LING-L03-Q028", "LING-L03-Q029", "LING-L03-Q030", "LING-L03-Q031", "LING-L03-Q032", "LING-L03-Q033", "LING-L03-Q034", "LING-L03-Q035", "LING-L03-Q036"]}, {"topic_id": "displays", "focus": "Spectrographs, spectrograms, waveforms, and formants", "source_slides": [5, 6, 7, 8], "question_ids": ["LING-L03-Q037", "LING-L03-Q038", "LING-L03-Q039", "LING-L03-Q040", "LING-L03-Q041", "LING-L03-Q042", "LING-L03-Q043", "LING-L03-Q044", "LING-L03-Q045", "LING-L03-Q046", "LING-L03-Q047", "LING-L03-Q048", "LING-L03-Q049", "LING-L03-Q050", "LING-L03-Q051", "LING-L03-Q052"]}, {"topic_id": "auditory", "focus": "Hearing, speech perception, and listening evidence", "source_slides": [4, 5, 9, 10], "question_ids": ["LING-L03-Q053", "LING-L03-Q054", "LING-L03-Q055", "LING-L03-Q056", "LING-L03-Q057", "LING-L03-Q058", "LING-L03-Q059", "LING-L03-Q060"]}, {"topic_id": "phonology", "focus": "Sound-system knowledge and its relationship to phonetics", "source_slides": [10, 11, 12, 13], "question_ids": ["LING-L03-Q061", "LING-L03-Q062", "LING-L03-Q063", "LING-L03-Q064", "LING-L03-Q065", "LING-L03-Q066", "LING-L03-Q067", "LING-L03-Q068", "LING-L03-Q069", "LING-L03-Q070", "LING-L03-Q071", "LING-L03-Q072", "LING-L03-Q073", "LING-L03-Q074"]}, {"topic_id": "phone_phoneme", "focus": "Segments, physical realizations, abstract categories, and contrasts", "source_slides": [13, 15, 16, 17, 18, 19, 20], "question_ids": ["LING-L03-Q075", "LING-L03-Q076", "LING-L03-Q077", "LING-L03-Q078", "LING-L03-Q079", "LING-L03-Q080", "LING-L03-Q081", "LING-L03-Q082", "LING-L03-Q083", "LING-L03-Q084", "LING-L03-Q085", "LING-L03-Q086", "LING-L03-Q087", "LING-L03-Q088"]}, {"topic_id": "transcription", "focus": "Symbols, notation, segment sequences, and integrated analysis", "source_slides": [4, 5, 9, 13, 14, 15, 16, 20, 21], "question_ids": ["LING-L03-Q089", "LING-L03-Q090", "LING-L03-Q091", "LING-L03-Q092", "LING-L03-Q093", "LING-L03-Q094", "LING-L03-Q095", "LING-L03-Q096", "LING-L03-Q097", "LING-L03-Q098", "LING-L03-Q099", "LING-L03-Q100"]}], "excluded_slides": [{"slide": 1, "reason": "Introduction title only."}, {"slide": 22, "reason": "Closing thank-you slide."}], "topics": [{"id": "overview", "title": "Phonetics: scope, evidence, and subfields", "question_count": 8}, {"id": "articulatory", "title": "Vocal apparatus, airstream, voicing, and articulation", "question_count": 14}, {"id": "acoustic", "title": "Duration, amplitude, fundamental frequency, and spectra", "question_count": 14}, {"id": "displays", "title": "Spectrographs, spectrograms, waveforms, and formants", "question_count": 16}, {"id": "auditory", "title": "Hearing, speech perception, and listening evidence", "question_count": 8}, {"id": "phonology", "title": "Sound-system knowledge and its relationship to phonetics", "question_count": 14}, {"id": "phone_phoneme", "title": "Segments, physical realizations, abstract categories, and contrasts", "question_count": 14}, {"id": "transcription", "title": "Symbols, notation, segment sequences, and integrated analysis", "question_count": 12}], "statistics": {"difficulty": {"easy": 28, "medium": 48, "hard": 24}, "cognitive_level": {"remember": 16, "understand": 23, "apply": 27, "analyze": 34}, "answer_distribution": {"A": 25, "B": 25, "C": 25, "D": 25}}, "questions": [{"id": "LING-L03-Q001", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [2, 3], "difficulty": "easy", "cognitive_level": "remember", "question": "Which description best defines phonetics in this lecture?", "explanation": "Phonetics examines speech as a physical and perceptual phenomenon. It investigates what speakers produce, the sound signal that travels, and what listeners hear.", "example": "A study may examine lip movement, a recording, or listeners’ identification of a consonant.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The study of language choice across social groups"}, {"id": "B", "text": "The study of speech sounds, including their production, transmission, and perception"}, {"id": "C", "text": "The study of word meanings and their relationships"}, {"id": "D", "text": "The study of sentence structure, including subjects and objects"}], "answer_id": "B"}, {"id": "LING-L03-Q002", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [2, 3], "difficulty": "easy", "cognitive_level": "understand", "question": "What does describing speech as a physical phenomenon allow a phonetician to investigate?", "explanation": "Speech involves physical activity and a signal that can be recorded and measured. These observations provide evidence for describing sounds rather than relying only on spelling.", "example": "A researcher can measure how long a vowel lasts in a recording.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Only the historical origins of sentence patterns"}, {"id": "B", "text": "Only the social prestige attached to an accent"}, {"id": "C", "text": "Observable movements and measurable properties of speech signals"}, {"id": "D", "text": "Only the dictionary meanings of spoken words"}], "answer_id": "C"}, {"id": "LING-L03-Q003", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [3], "difficulty": "easy", "cognitive_level": "remember", "question": "Which set names the three subfields of phonetics listed in the slides?", "explanation": "The three subfields focus on producing sounds, the physical sound signal, and perceiving sounds. They provide complementary ways to investigate speech.", "example": "An experiment can combine observations of production with acoustic measurements and listening judgments.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Articulatory, acoustic, and auditory phonetics"}, {"id": "B", "text": "Auditory, lexical, and historical phonetics"}, {"id": "C", "text": "Acoustic, semantic, and pragmatic phonetics"}, {"id": "D", "text": "Articulatory, morphological, and syntactic phonetics"}], "answer_id": "A"}, {"id": "LING-L03-Q004", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [2, 3, 4, 5, 9], "difficulty": "medium", "cognitive_level": "understand", "question": "Which sequence correctly follows a spoken message from production to perception?", "explanation": "The sequence links the main concerns of articulatory, acoustic, and auditory phonetics. It is a way of organizing the process, even though real communication involves further mental processing.", "example": "A speaker says “hello,” sound travels through the air, and another person hears the greeting.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A listener perceives a signal before the speaker produces it."}, {"id": "B", "text": "The transmitted signal produces the speaker’s original articulatory movement."}, {"id": "C", "text": "A written letter must be created before a speech signal can travel."}, {"id": "D", "text": "Vocal activity produces a signal, the signal travels, and a listener perceives it."}], "answer_id": "D"}, {"id": "LING-L03-Q005", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [4, 5, 9], "difficulty": "medium", "cognitive_level": "apply", "question": "A project records tongue movement, analyses sound frequencies, and collects listeners’ judgments. Which description best fits its methods?", "explanation": "The methods address three kinds of evidence. Tongue movement concerns production, frequency analysis concerns the signal, and listener judgments concern perception.", "example": "Different measurements can explain different aspects of the same spoken consonant.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "It is exclusively acoustic because a recording is involved."}, {"id": "B", "text": "It combines articulatory, acoustic, and auditory perspectives."}, {"id": "C", "text": "It is exclusively articulatory because a tongue is involved."}, {"id": "D", "text": "It is exclusively auditory because participants give answers."}], "answer_id": "B"}, {"id": "LING-L03-Q006", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [4, 5], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which observation is directly about articulation rather than the acoustic signal?", "explanation": "Articulation concerns the actions of the speech organs. Duration, frequency, and waveform amplitude describe properties of the signal resulting from those actions.", "example": "Observing lip closure is different from measuring the sound produced when the lips open.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The recorded vowel lasts 180 milliseconds."}, {"id": "B", "text": "The speaker closes both lips during a consonant."}, {"id": "C", "text": "The waveform’s amplitude increases during the recording."}, {"id": "D", "text": "The signal contains energy concentrated in particular frequency bands."}], "answer_id": "B"}, {"id": "LING-L03-Q007", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [5, 9], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which observation is directly auditory rather than an acoustic measurement?", "explanation": "The correct observation records a perceptual judgment. The alternatives describe properties of a recorded signal or its visual display.", "example": "Two listeners can hear the same recording and give different sound-identification responses.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A spectrogram contains several dark horizontal bands."}, {"id": "B", "text": "A vowel occupies 0.2 seconds of a recording."}, {"id": "C", "text": "A signal has a measured fundamental frequency."}, {"id": "D", "text": "A listener reports hearing /p/ rather than /b/."}], "answer_id": "D"}, {"id": "LING-L03-Q008", "lecture_id": "LING-L03", "topic_id": "overview", "source_slides": [2, 4, 5, 9], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher wants evidence about what listeners actually hear in a recording. Which method most directly addresses that aim?", "explanation": "A listening task directly tests perception. Production and signal measurements can help explain perception, but they do not replace evidence about listeners’ responses.", "example": "Participants can hear two sounds and report whether they perceive them as the same or different.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Ask listeners to identify or compare the sounds they hear."}, {"id": "B", "text": "Inspect only the written spelling of the words."}, {"id": "C", "text": "Measure only the recording’s duration."}, {"id": "D", "text": "Measure the speaker’s tongue movement without a listening task."}], "answer_id": "A"}, {"id": "LING-L03-Q009", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the main concern of articulatory phonetics?", "explanation": "Articulatory phonetics examines the physical production of speech. It asks what the speech organs do, while acoustic and auditory work examine the signal and its perception.", "example": "A researcher can observe the position of the tongue while a vowel is produced.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "How sound energy is represented on a spectrogram"}, {"id": "B", "text": "How the human vocal apparatus produces speech sounds"}, {"id": "C", "text": "How sound contrasts function within a language"}, {"id": "D", "text": "How a listener classifies an ambiguous recording"}], "answer_id": "B"}, {"id": "LING-L03-Q010", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [2, 4], "difficulty": "easy", "cognitive_level": "remember", "question": "Which set contains body parts explicitly listed in the lecture’s account of speech production?", "explanation": "The lecture identifies several body parts involved in producing speech. They contribute in different ways, including supplying air and shaping its passage.", "example": "The lips can shape an opening while air passes through the vocal tract.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Teeth, pharynx, retina, fingers, and elbow"}, {"id": "B", "text": "Lungs, tongue, knee, ankle, and retina"}, {"id": "C", "text": "Lips, tongue, retina, wrist, and lungs"}, {"id": "D", "text": "Lips, tongue, teeth, pharynx, and lungs"}], "answer_id": "D"}, {"id": "LING-L03-Q011", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [2, 4], "difficulty": "medium", "cognitive_level": "apply", "question": "An investigation tracks changes in a speaker’s tongue position during vowels. Which subfield is its most direct focus?", "explanation": "Tongue position is evidence about the production mechanism. The resulting sound can also be studied acoustically, but that is a different observation.", "example": "A speaker can change the shape of the vocal tract by moving the tongue.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phonology"}, {"id": "B", "text": "Auditory phonetics"}, {"id": "C", "text": "Articulatory phonetics"}, {"id": "D", "text": "Acoustic phonetics"}], "answer_id": "C"}, {"id": "LING-L03-Q012", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [2, 4], "difficulty": "medium", "cognitive_level": "understand", "question": "What role do the lungs usually play in ordinary spoken-language production?", "explanation": "Ordinary speech commonly uses air flowing outward from the lungs. Other parts of the vocal apparatus shape that airflow into speech sounds. This does not mean every possible speech sound uses the same airstream mechanism.", "example": "A speaker can use one outward breath to produce a short phrase.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "They directly decide which word the listener understands."}, {"id": "B", "text": "They produce the tongue’s place of contact against the mouth."}, {"id": "C", "text": "They determine a phoneme’s meaning independently of language."}, {"id": "D", "text": "They provide an outgoing airflow that can be used to produce speech."}], "answer_id": "D"}, {"id": "LING-L03-Q013", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "easy", "cognitive_level": "understand", "question": "In the lecture’s articulatory framework, what is an airstream mechanism?", "explanation": "An airstream mechanism concerns the movement of air used for speech production. It belongs to the physical production process rather than to spelling or sentence interpretation.", "example": "Ordinary speech frequently uses air pushed outward from the lungs.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The way airflow is initiated and used in producing speech"}, {"id": "B", "text": "The way frequency is positioned on a spectrogram"}, {"id": "C", "text": "The way words are arranged in an utterance"}, {"id": "D", "text": "The way a listener chooses a dictionary meaning"}], "answer_id": "A"}, {"id": "LING-L03-Q014", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "easy", "cognitive_level": "understand", "question": "What does voicing refer to in a basic description of speech production?", "explanation": "Voicing is about vocal-fold vibration, not simply volume. A quiet sound can be voiced, and a loud sound can be voiceless.", "example": "A sustained [z] normally involves vocal-fold vibration, while [s] does not.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Vibration of the tongue against the teeth during every sound"}, {"id": "B", "text": "A sound being pronounced loudly enough for an audience"}, {"id": "C", "text": "Vibration of the vocal folds during a sound"}, {"id": "D", "text": "A listener correctly identifying the meaning of a word"}], "answer_id": "C"}, {"id": "LING-L03-Q015", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which statement correctly distinguishes voicing from loudness?", "explanation": "The properties answer different questions. Whether the vocal folds vibrate is not determined simply by how strong or loud a sound is.", "example": "A softly spoken vowel may be voiced even when a louder [s] is voiceless.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Voicing concerns vocal-fold vibration; loudness concerns perceived sound strength."}, {"id": "B", "text": "Only sounds produced without airflow can be voiced."}, {"id": "C", "text": "Voicing and loudness are two names for exactly the same property."}, {"id": "D", "text": "A sound becomes voiced whenever it is made louder."}], "answer_id": "A"}, {"id": "LING-L03-Q016", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher observes whether the vocal folds vibrate during a consonant. Which articulatory concern from the slides is being examined?", "explanation": "The observation directly concerns vocal-fold activity. It does not by itself establish what the sound means or which phoneme it represents in a language.", "example": "Comparing the production of [s] and [z] can reveal a difference in voicing.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Voicing"}, {"id": "B", "text": "Sound duration"}, {"id": "C", "text": "Signal amplitude"}, {"id": "D", "text": "Formant frequency"}], "answer_id": "A"}, {"id": "LING-L03-Q017", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "medium", "cognitive_level": "apply", "question": "A student examines the anatomy of the pharynx and its contribution to the vocal tract. Which area of interest listed on slide 4 does this match?", "explanation": "The question concerns the physical structures involved in production. Knowing their anatomy helps explain how the vocal tract can shape speech.", "example": "Understanding the positions of the tongue and pharynx can support an account of vocal-tract shape.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Auditory identification"}, {"id": "B", "text": "Anatomy of the vocal organs"}, {"id": "C", "text": "Phonemic contrast testing"}, {"id": "D", "text": "Frequency-spectrum measurement"}], "answer_id": "B"}, {"id": "LING-L03-Q018", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "easy", "cognitive_level": "understand", "question": "Does articulatory phonetics study only consonants?", "explanation": "The slide explicitly includes vowels and consonants. Both involve the vocal apparatus, even though their production can involve different configurations.", "example": "Tongue position can be observed during a vowel just as lip closure can be observed during a consonant.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "No; it studies the production of vowels as well as consonants."}, {"id": "B", "text": "No; it studies written letters instead of either sound type."}, {"id": "C", "text": "Yes; vowels have no physical production mechanism."}, {"id": "D", "text": "Yes; vowels can be studied only in auditory phonetics."}], "answer_id": "A"}, {"id": "LING-L03-Q019", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [2, 4], "difficulty": "medium", "cognitive_level": "apply", "question": "A camera records the rounding of a speaker’s lips during a vowel. What kind of evidence does the image provide most directly?", "explanation": "The camera records a visible part of speech production. It does not directly show how the listener hears the sound or how the language categorizes it.", "example": "An image can show rounded lips without telling us the exact frequency pattern of the resulting sound.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A direct measurement of the vowel’s meaning"}, {"id": "B", "text": "Evidence about the listener’s perceptual category"}, {"id": "C", "text": "A direct representation of the phoneme inventory"}, {"id": "D", "text": "Evidence about an articulatory configuration"}], "answer_id": "D"}, {"id": "LING-L03-Q020", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4, 5], "difficulty": "hard", "cognitive_level": "analyze", "question": "A change in tongue position is followed by a change in the sound’s frequency pattern. Which interpretation best connects the observations?", "explanation": "Speech-organ movement and the resulting signal are different but connected parts of production. Their relationship can be investigated by combining methods.", "example": "Moving the tongue changes the vocal-tract shape, which can alter the acoustic pattern of a vowel.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "An articulatory change has an acoustic consequence."}, {"id": "B", "text": "An acoustic measurement is the same physical event as tongue movement."}, {"id": "C", "text": "A phoneme’s abstract identity has been directly photographed."}, {"id": "D", "text": "A spelling change has replaced an auditory judgment."}], "answer_id": "A"}, {"id": "LING-L03-Q021", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which question is least directly addressed by observing a speaker’s vocal organs alone?", "explanation": "Observing production provides information about the speaker’s actions. Establishing a listener’s percept requires a perceptual response or other appropriate evidence about the listener.", "example": "Visible lip closure does not by itself reveal whether a particular listener heard /p/ or /b/.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Which sound a listener believes was produced"}, {"id": "B", "text": "Whether the vocal folds vibrate"}, {"id": "C", "text": "Whether the lips close during a sound"}, {"id": "D", "text": "How the tongue changes position"}], "answer_id": "A"}, {"id": "LING-L03-Q022", "lecture_id": "LING-L03", "topic_id": "articulatory", "source_slides": [4, 5, 9], "difficulty": "hard", "cognitive_level": "analyze", "question": "A study asks why a particular lip movement affects sound identification. Which combination would give the most relevant evidence?", "explanation": "The proposed explanation connects production with perception. Observing the movement, the intervening signal, and the listener’s response helps address each part of that relationship.", "example": "A project might compare two lip configurations and ask whether listeners identify the resulting sounds differently.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Inspect the spelling and assume that it fully determines perception."}, {"id": "B", "text": "Measure only word length in letters and infer lip motion from it."}, {"id": "C", "text": "Record only participants’ ages and omit the speech task."}, {"id": "D", "text": "Observe the movement, analyse the signal, and test listeners’ responses."}], "answer_id": "D"}, {"id": "LING-L03-Q023", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the main focus of acoustic phonetics?", "explanation": "Acoustic phonetics investigates the measurable signal, including its duration, amplitude, and frequency properties. It connects speech production with the sound available to a listener.", "example": "Measuring a recorded sound’s frequency pattern is an acoustic task.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The arrangement of words in a grammatical sentence"}, {"id": "B", "text": "The physical properties of the speech signal"}, {"id": "C", "text": "The speaker’s choice of word meanings"}, {"id": "D", "text": "The listener’s beliefs about a speaker’s intention"}], "answer_id": "B"}, {"id": "LING-L03-Q024", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "easy", "cognitive_level": "remember", "question": "Which set consists of acoustic properties mentioned on slide 5?", "explanation": "These properties describe aspects of the sound signal. The other sets concern articulation, meaning, or social factors rather than acoustic measurement.", "example": "A recording can be examined for both how long a sound lasts and its frequency content.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Amplitude, duration, fundamental frequency, and frequency-spectrum properties"}, {"id": "B", "text": "Word meaning, sentence meaning, reference, and implication"}, {"id": "C", "text": "Tongue position, lip shape, tooth position, and jaw movement"}, {"id": "D", "text": "Speaker age, social class, occupation, and language attitude"}], "answer_id": "A"}, {"id": "LING-L03-Q025", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "easy", "cognitive_level": "understand", "question": "What does the duration of a sound describe?", "explanation": "Duration is a time measure. It should be distinguished from frequency, amplitude, and written length.", "example": "A vowel lasting 200 milliseconds has a longer duration than one lasting 100 milliseconds.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "How long the sound lasts"}, {"id": "B", "text": "How many letters spell the word containing it"}, {"id": "C", "text": "How strongly a listener likes it"}, {"id": "D", "text": "How high its frequency is"}], "answer_id": "A"}, {"id": "LING-L03-Q026", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "medium", "cognitive_level": "apply", "question": "Two recordings of the same word contain vowels lasting 120 and 180 milliseconds. Which statement is supported?", "explanation": "The values establish a timing difference. They do not alone establish a difference in phonemic category, frequency, or amplitude.", "example": "The same speaker can lengthen a vowel while emphasizing a word without automatically creating a new word.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The second vowel necessarily has a higher fundamental frequency."}, {"id": "B", "text": "The second vowel necessarily belongs to a different phoneme."}, {"id": "C", "text": "The second vowel must have greater amplitude."}, {"id": "D", "text": "The second vowel has a longer measured duration."}], "answer_id": "D"}, {"id": "LING-L03-Q027", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "easy", "cognitive_level": "understand", "question": "In an ordinary speech waveform display, what does amplitude represent?", "explanation": "Amplitude describes the size of signal variations. It is an acoustic quantity, rather than a direct measurement of a linguistic category or an articulator’s location.", "example": "Larger vertical excursions in a consistently scaled waveform indicate greater signal amplitude.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The tongue’s distance from the teeth"}, {"id": "B", "text": "The time at which a word becomes meaningful"}, {"id": "C", "text": "The magnitude of the signal’s variation from its reference level"}, {"id": "D", "text": "The number of phonemes in a language"}], "answer_id": "C"}, {"id": "LING-L03-Q028", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "medium", "cognitive_level": "understand", "question": "Why should acoustic amplitude not simply be defined as a listener’s loudness judgment?", "explanation": "A physical measurement and a perceptual response are connected but not identical. Factors affecting hearing and the signal can influence perceived loudness.", "example": "Two listeners may judge the same recorded sound’s loudness differently.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Amplitude is a signal measurement, while loudness is a perceptual experience."}, {"id": "B", "text": "Amplitude is a grammatical category, while loudness is a written symbol."}, {"id": "C", "text": "Amplitude describes only consonants, while loudness describes only vowels."}, {"id": "D", "text": "Loudness and amplitude cannot have any relationship."}], "answer_id": "A"}, {"id": "LING-L03-Q029", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "easy", "cognitive_level": "understand", "question": "What is fundamental frequency in a periodic sound signal?", "explanation": "Fundamental frequency describes repetition rate. It is distinct from the overall length of the recording and from resonant frequency concentrations associated with formants.", "example": "A periodic signal repeating 150 times per second has a fundamental frequency of 150 Hz.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The largest spelling unit in the transcript"}, {"id": "B", "text": "The rate at which its repeating cycle occurs"}, {"id": "C", "text": "The total duration of the complete word"}, {"id": "D", "text": "The number of formant bands visible at one instant"}], "answer_id": "B"}, {"id": "LING-L03-Q030", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "medium", "cognitive_level": "apply", "question": "Two otherwise comparable periodic speech signals repeat 100 and 200 times per second. Which has the higher fundamental frequency?", "explanation": "A greater number of repetitions per second means a higher fundamental frequency. Duration measures a different property and need not decide this comparison.", "example": "One second of a 200 Hz periodic signal contains more cycles than one second of a 100 Hz signal.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Both must have the same fundamental frequency if their durations match."}, {"id": "B", "text": "The answer depends only on how many letters spell the word."}, {"id": "C", "text": "The signal repeating 200 times per second"}, {"id": "D", "text": "The signal repeating 100 times per second"}], "answer_id": "C"}, {"id": "LING-L03-Q031", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "medium", "cognitive_level": "understand", "question": "Which question concerns a sound’s frequency spectrum?", "explanation": "A frequency spectrum describes the signal in terms of frequency components and their strengths. This differs from measuring only its total duration.", "example": "Two sounds can last equally long yet distribute their energy differently across frequencies.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Which social role does its speaker hold?"}, {"id": "B", "text": "What grammatical function does its word ending express?"}, {"id": "C", "text": "How is its acoustic energy distributed across frequencies?"}, {"id": "D", "text": "How are its letters arranged alphabetically?"}], "answer_id": "C"}, {"id": "LING-L03-Q032", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher measures the mean squared amplitude of a recorded sound. Which subfield does this measurement most directly belong to?", "explanation": "Mean squared amplitude is a quantity calculated from the signal. It supplies acoustic evidence rather than a direct observation of speech-organ movement or a listener’s response.", "example": "A researcher can calculate a signal-based measure without asking participants what they heard.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Auditory phonetics"}, {"id": "B", "text": "Acoustic phonetics"}, {"id": "C", "text": "Articulatory phonetics"}, {"id": "D", "text": "Morphology"}], "answer_id": "B"}, {"id": "LING-L03-Q033", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "hard", "cognitive_level": "analyze", "question": "Two sounds have equal durations. What follows about their other acoustic properties?", "explanation": "Equality on one measure does not establish equality on others. Duration, amplitude, and frequency structure describe different aspects of a signal.", "example": "Two 150-millisecond vowels can differ in their frequency patterns.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "They must represent the same phoneme in every language."}, {"id": "B", "text": "They may still differ in amplitude or frequency structure."}, {"id": "C", "text": "They must have identical amplitude patterns."}, {"id": "D", "text": "They must have identical fundamental frequencies."}], "answer_id": "B"}, {"id": "LING-L03-Q034", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "medium", "cognitive_level": "analyze", "question": "A researcher asks whether a vowel’s measured frequency pattern changes with tongue position. Which relationship from slide 5 is being examined?", "explanation": "Tongue position concerns articulation, while the measured signal pattern is acoustic. The investigation connects a production configuration with its sound properties.", "example": "A study can record the tongue and the speech signal at the same time.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The relationship between dictionary order and word meaning"}, {"id": "B", "text": "The relationship between translation and writing-system design"}, {"id": "C", "text": "The relationship between acoustic and articulatory phonetics"}, {"id": "D", "text": "The relationship between social class and sentence punctuation"}], "answer_id": "C"}, {"id": "LING-L03-Q035", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5, 9], "difficulty": "medium", "cognitive_level": "apply", "question": "An experiment changes a recording’s duration and asks listeners which sound they hear. Which two perspectives are directly connected?", "explanation": "Duration is a property of the signal, and the response concerns perception. Manipulating one and observing the other investigates an acoustic–auditory relationship.", "example": "Listeners can hear two versions of a sound that differ only in their timing.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Acoustic properties and auditory perception"}, {"id": "B", "text": "Word meanings and sentence formation"}, {"id": "C", "text": "Tongue anatomy and dictionary selection"}, {"id": "D", "text": "Spelling conventions and grammatical roles"}], "answer_id": "A"}, {"id": "LING-L03-Q036", "lecture_id": "LING-L03", "topic_id": "acoustic", "source_slides": [5], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why can acoustic analysis be applied to a whole utterance as well as to one phone?", "explanation": "The slide relates acoustic properties to phones, phrases, and utterances. A researcher can choose a relevant interval without treating every linguistic unit as the same size.", "example": "One analysis can measure a single vowel’s duration; another can measure the timing of an entire phrase.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Signal properties can be measured over speech intervals of different sizes."}, {"id": "B", "text": "An utterance is always just one phone pronounced slowly."}, {"id": "C", "text": "A phone’s acoustic properties disappear when it enters a word."}, {"id": "D", "text": "Only individual written letters have measurable duration."}], "answer_id": "A"}, {"id": "LING-L03-Q037", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "easy", "cognitive_level": "remember", "question": "What is the relationship between a sound spectrograph and a spectrogram?", "explanation": "The instrument or analysis system and its output should be distinguished. A spectrogram represents changes in frequency-related energy over time.", "example": "A researcher examines a spectrogram generated from a recorded vowel.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A spectrograph produces a spectrogram, a visual representation of the sound signal."}, {"id": "B", "text": "A spectrogram produces the speaker’s vocal organs."}, {"id": "C", "text": "A spectrogram measures listener beliefs without analysing a signal."}, {"id": "D", "text": "A spectrograph is a phoneme, while a spectrogram is its spelling."}], "answer_id": "A"}, {"id": "LING-L03-Q038", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "easy", "cognitive_level": "remember", "question": "On the standard spectrogram described in the slides, what does the horizontal axis represent?", "explanation": "Moving horizontally follows the signal through time. A longer horizontal interval therefore represents a longer duration on the same time scale.", "example": "A sound extending from 0.1 to 0.3 seconds occupies 0.2 seconds of the display.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Time"}, {"id": "B", "text": "Phoneme category"}, {"id": "C", "text": "Frequency"}, {"id": "D", "text": "Perceived loudness"}], "answer_id": "A"}, {"id": "LING-L03-Q039", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "easy", "cognitive_level": "remember", "question": "On the standard spectrogram described in the slides, what does the vertical axis represent?", "explanation": "The vertical dimension places frequency components at different heights. It should not be confused with the vertical amplitude dimension in an ordinary waveform display.", "example": "A band higher on the frequency axis represents a higher frequency than a lower band.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Spelling order"}, {"id": "B", "text": "Time"}, {"id": "C", "text": "Word meaning"}, {"id": "D", "text": "Frequency"}], "answer_id": "D"}, {"id": "LING-L03-Q040", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "easy", "cognitive_level": "understand", "question": "In the grayscale convention described in the lecture, what does a darker spectrogram region generally indicate?", "explanation": "Darkness encodes relative signal strength in this display convention. It does not replace the time or frequency axes, and interpretation depends on consistent analysis and display settings.", "example": "At the same frequency and comparable settings, a darker patch indicates stronger displayed energy.", "reference_ids": ["lecture_03", "ncvs_spectrogram"], "options": [{"id": "A", "text": "A higher frequency regardless of vertical position"}, {"id": "B", "text": "A different phoneme regardless of the surrounding pattern"}, {"id": "C", "text": "Greater signal energy at the represented time and frequency"}, {"id": "D", "text": "A later point in time regardless of horizontal position"}], "answer_id": "C"}, {"id": "LING-L03-Q041", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "medium", "cognitive_level": "apply", "question": "A sound begins at 0.20 seconds and ends at 0.35 seconds on a spectrogram. What is its duration?", "explanation": "Duration is the end time minus the start time. The answer gives the length of the interval, rather than either endpoint or their sum.", "example": "A sound from 0.40 to 0.60 seconds lasts 0.20 seconds.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "0.20 seconds"}, {"id": "B", "text": "0.35 seconds"}, {"id": "C", "text": "0.55 seconds"}, {"id": "D", "text": "0.15 seconds"}], "answer_id": "D"}, {"id": "LING-L03-Q042", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "medium", "cognitive_level": "apply", "question": "Two bands occur at the same time on a spectrogram. One is plotted at 500 Hz and the other at 1500 Hz. Which statement is supported?", "explanation": "The values specify frequency, so they determine relative vertical position. They do not independently establish duration, intensity, or temporal order.", "example": "A frequency of 2000 Hz appears above 1000 Hz when the axis increases upward.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The 500 Hz band must occur earlier."}, {"id": "B", "text": "The 500 Hz band must be darker."}, {"id": "C", "text": "The 1500 Hz band must last longer."}, {"id": "D", "text": "The 1500 Hz band is higher on the frequency axis."}], "answer_id": "D"}, {"id": "LING-L03-Q043", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6], "difficulty": "medium", "cognitive_level": "understand", "question": "What are formants in the lecture’s description of vowel spectrograms?", "explanation": "Formants are acoustic patterns related to the filtering effect of the vocal tract. In suitable spectrograms, they appear as energy bands useful for comparing vowel qualities.", "example": "A vowel can show several formant bands at different frequency heights.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Concentrations of acoustic energy associated with vocal-tract resonances"}, {"id": "B", "text": "The letters used to spell the vowel"}, {"id": "C", "text": "The spaces separating words in a written transcript"}, {"id": "D", "text": "The full set of phonemes in a language"}], "answer_id": "A"}, {"id": "LING-L03-Q044", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6, 7], "difficulty": "medium", "cognitive_level": "apply", "question": "A vowel spectrogram shows several strong horizontal energy bands. Which concept from the lecture most directly explains these bands?", "explanation": "The lecture links these bands with concentrations of acoustic energy. They provide information about vowel quality rather than directly displaying spelling or word parts.", "example": "The positions of bands can differ when the speaker changes from one vowel to another.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Sentence boundaries"}, {"id": "B", "text": "Morphemes"}, {"id": "C", "text": "Formants"}, {"id": "D", "text": "Letters"}], "answer_id": "C"}, {"id": "LING-L03-Q045", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6, 7], "difficulty": "hard", "cognitive_level": "analyze", "question": "Two vowels last equally long but show different patterns of formant bands. Which conclusion is most appropriate?", "explanation": "Timing and frequency structure are separate aspects of the signal. The lecture uses changing band patterns to illustrate differences among vowel qualities.", "example": "Two equally long vowel recordings can show their strongest bands at different frequency positions.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Equal duration requires both vowels to have identical frequency structure."}, {"id": "B", "text": "Their acoustic vowel qualities may differ despite equal duration."}, {"id": "C", "text": "The darker vowel must be the only meaningful sound."}, {"id": "D", "text": "Their formant differences prove that their durations are unequal."}], "answer_id": "B"}, {"id": "LING-L03-Q046", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [5, 6], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which distinction best separates fundamental frequency from formants?", "explanation": "The terms describe different properties of a signal. Changes in the repetition of voicing and changes in vocal-tract filtering need not be the same change.", "example": "A speaker can change vocal pitch without changing to a completely different vowel.", "reference_ids": ["lecture_03", "ncvs_spectrogram"], "options": [{"id": "A", "text": "Fundamental frequency concerns repetition rate; formants concern resonant energy concentrations."}, {"id": "B", "text": "Fundamental frequency is duration; formants are word meanings."}, {"id": "C", "text": "Fundamental frequency is spelling; formants are phoneme counts."}, {"id": "D", "text": "Fundamental frequency and formants name the same acoustic property."}], "answer_id": "A"}, {"id": "LING-L03-Q047", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [7], "difficulty": "medium", "cognitive_level": "apply", "question": "A figure groups spectrograms under vowels, semivowels, and plosive consonants. What kind of comparison does this primarily support?", "explanation": "The figure presents signal patterns, so it is acoustic evidence. It does not directly show meanings, social evaluations, or all aspects of a sound’s linguistic status.", "example": "A student can compare sustained energy bands with changes associated with a consonant interval.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Comparing speakers’ social attitudes without any listener data"}, {"id": "B", "text": "Comparing the dictionary meanings of the sounds"}, {"id": "C", "text": "Comparing which language has the most writing symbols"}, {"id": "D", "text": "Comparing acoustic patterns associated with different sound types"}], "answer_id": "D"}, {"id": "LING-L03-Q048", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [8], "difficulty": "medium", "cognitive_level": "apply", "question": "A figure contains two line traces: the upper trace repeats a similar shape regularly, while the lower trace fluctuates irregularly. Which observation is directly supported?", "explanation": "Periodicity refers to repeated cycles in the signal. Without additional labels and scales, the traces do not establish particular words or phoneme counts.", "example": "A repeating waveform can show similar shapes at approximately regular time intervals.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The upper trace must represent a particular word."}, {"id": "B", "text": "The upper trace must contain more phonemes."}, {"id": "C", "text": "The upper trace is more periodic than the lower trace."}, {"id": "D", "text": "The lower trace must have a longer total duration."}], "answer_id": "C"}, {"id": "LING-L03-Q049", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [5, 8], "difficulty": "medium", "cognitive_level": "analyze", "question": "An ordinary waveform plots amplitude vertically over time. How does this differ from the spectrogram described in the lecture?", "explanation": "Both can represent a recording over time, but they display different signal properties. A waveform shows changes in amplitude; a spectrogram separates information by frequency.", "example": "A waveform can show large signal excursions, while a spectrogram can show vowel formant bands.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The spectrogram and waveform use identical axes and show identical information."}, {"id": "B", "text": "The spectrogram plots frequency vertically and uses shading for signal strength."}, {"id": "C", "text": "The spectrogram plots spelling vertically and word meaning horizontally."}, {"id": "D", "text": "The waveform plots frequency vertically and never shows time."}], "answer_id": "B"}, {"id": "LING-L03-Q050", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6, 8], "difficulty": "hard", "cognitive_level": "analyze", "question": "A student treats a tall peak on a waveform as if it were a high-frequency band on a spectrogram. What is the main error?", "explanation": "The meaning of a vertical position depends on the display. A waveform’s vertical amplitude cannot be interpreted as if it were a spectrogram’s frequency axis.", "example": "A larger waveform peak does not by itself establish a higher fundamental frequency.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The student has confused a vowel with a written word."}, {"id": "B", "text": "The student has confused word order with listener perception."}, {"id": "C", "text": "The student has confused a phoneme with a morpheme."}, {"id": "D", "text": "The student has confused amplitude with frequency by ignoring the display axes."}], "answer_id": "D"}, {"id": "LING-L03-Q051", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6, 7], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why should the lecture’s statement that vowels are darkest on a spectrogram not be treated as an unconditional identification rule?", "explanation": "A strong vowel may be prominent in a display, but darkness alone does not identify a sound. Comparisons need consistent settings and other acoustic evidence.", "example": "A recording-level change can alter the appearance of a display without changing the word spoken.", "reference_ids": ["lecture_03", "ncvs_spectrogram"], "options": [{"id": "A", "text": "Displayed darkness depends on energy and settings, so sound identity requires the wider pattern."}, {"id": "B", "text": "Darkness always represents the number of letters in a vowel’s spelling."}, {"id": "C", "text": "All consonants are necessarily invisible on every spectrogram."}, {"id": "D", "text": "Every dark band must correspond to a separate vowel phoneme."}], "answer_id": "A"}, {"id": "LING-L03-Q052", "lecture_id": "LING-L03", "topic_id": "displays", "source_slides": [6, 7, 8], "difficulty": "hard", "cognitive_level": "analyze", "question": "A sound diagram has no labelled axes or time scale. Which conclusion should a student avoid?", "explanation": "Qualitative patterns can be described without numerical calibration. Exact time or frequency values require an appropriate scale, not just the shape of a picture.", "example": "An unlabeled trace may look periodic, but the image alone cannot establish that it repeats at 150 Hz.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Assigning an exact duration or frequency value from the image alone"}, {"id": "B", "text": "Noting that a visible pattern repeats regularly"}, {"id": "C", "text": "Noting that one section contains changing bands"}, {"id": "D", "text": "Noting that two displayed traces have different shapes"}], "answer_id": "A"}, {"id": "LING-L03-Q053", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [9], "difficulty": "easy", "cognitive_level": "remember", "question": "What does auditory phonetics primarily investigate?", "explanation": "Auditory phonetics focuses on listeners and their perception of speech. It complements research on how sounds are produced and how their signals can be measured.", "example": "A listening experiment can ask whether participants distinguish two speech sounds.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The grammatical order of sentence elements"}, {"id": "B", "text": "The historical origins of word meanings"}, {"id": "C", "text": "The physical shapes of printed letters"}, {"id": "D", "text": "Hearing and perception of speech sounds"}], "answer_id": "D"}, {"id": "LING-L03-Q054", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [9], "difficulty": "easy", "cognitive_level": "understand", "question": "In the lecture, what is speech perception?", "explanation": "Speech perception involves making sense of the incoming speech signal. It is more than a description of the movements that originally produced the sound.", "example": "A listener can interpret a short sound sequence as a familiar spoken word.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The process of arranging dictionary entries alphabetically"}, {"id": "B", "text": "The process of counting written letters in a sentence"}, {"id": "C", "text": "The processes through which people interpret and understand speech sounds"}, {"id": "D", "text": "The process of moving only the lips during speech"}], "answer_id": "C"}, {"id": "LING-L03-Q055", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "Listeners hear two recorded consonants and judge whether they are the same or different. What is the main kind of evidence collected?", "explanation": "The responses reveal what listeners discriminate in the task. They do not directly photograph production or establish a whole phonological system.", "example": "Some participants may hear a difference that others do not reliably notice.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A complete list of phonemes established without linguistic analysis"}, {"id": "B", "text": "Direct images of vocal-fold movement"}, {"id": "C", "text": "Direct measurements of tongue contact"}, {"id": "D", "text": "Perceptual responses to speech sounds"}], "answer_id": "D"}, {"id": "LING-L03-Q056", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [5, 9], "difficulty": "hard", "cognitive_level": "analyze", "question": "A listener reports hearing the same sound category in two recordings whose durations differ slightly. Which conclusion is justified?", "explanation": "Physical differences and perceptual categories are related but not equivalent. A listener can group different signals together, although a larger or different change might affect the response.", "example": "Two slightly different recordings may both be identified as /p/.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The recordings must therefore have identical signals."}, {"id": "B", "text": "An acoustic difference need not produce a different category response in that task."}, {"id": "C", "text": "The listener must be using spelling rather than hearing."}, {"id": "D", "text": "The listener’s response proves that duration can never affect perception."}], "answer_id": "B"}, {"id": "LING-L03-Q057", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [9], "difficulty": "easy", "cognitive_level": "remember", "question": "Which field outside linguistics is explicitly linked to speech perception in the lecture?", "explanation": "The slide connects speech perception with cognitive psychology and the study of perception. These links reflect an interest in how people process sensory information.", "example": "A study can investigate the mental processes involved when listeners identify an ambiguous sound.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Literary publishing"}, {"id": "B", "text": "Economic geography"}, {"id": "C", "text": "Cognitive psychology"}, {"id": "D", "text": "Political history"}], "answer_id": "C"}, {"id": "LING-L03-Q058", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [9, 10], "difficulty": "medium", "cognitive_level": "understand", "question": "Why can speech-perception research be relevant to phonology as well as phonetics?", "explanation": "Perception involves a signal, but the way listeners organize it can relate to language-specific categories. This connection helps explain why the fields interact.", "example": "An investigation can ask whether listeners distinguish sounds that contrast in a language they know.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phonological categories can be studied without any evidence from language use."}, {"id": "B", "text": "Listeners interpret physical signals using distinctions that matter in linguistic sound systems."}, {"id": "C", "text": "Perception concerns only the written alphabet."}, {"id": "D", "text": "Every audible difference must be a separate phoneme in every language."}], "answer_id": "B"}, {"id": "LING-L03-Q059", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [9], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher asks participants to choose which of two spoken words they heard. Which observation comes most directly from the task?", "explanation": "The task collects listener decisions about a signal. Those decisions can be analysed for accuracy or patterns, but do not directly supply articulatory or acoustic measurements.", "example": "After hearing a recording, a participant may choose “kid” rather than “kit.”", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The number of letters in the speaker’s intended spelling"}, {"id": "B", "text": "The precise location of the speaker’s tongue throughout the recording"}, {"id": "C", "text": "The complete frequency spectrum calculated without signal analysis"}, {"id": "D", "text": "Their identification of the recorded speech"}], "answer_id": "D"}, {"id": "LING-L03-Q060", "lecture_id": "LING-L03", "topic_id": "auditory", "source_slides": [4, 5, 9], "difficulty": "hard", "cognitive_level": "analyze", "question": "Which combination correctly separates production, signal, and perception evidence?", "explanation": "The first sequence assigns a suitable source of evidence to each stage. A written form cannot substitute for direct evidence about what a speaker produced or a listener perceived.", "example": "A single project can investigate how an articulatory difference changes a signal and influences listeners.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Acoustic recording analysis, word meaning, and sentence punctuation"}, {"id": "B", "text": "Dictionary spelling, vocal-fold observation, and acoustic frequency"}, {"id": "C", "text": "Listener identification, dictionary spelling, and tongue anatomy"}, {"id": "D", "text": "Vocal-fold observation, acoustic recording analysis, and listener identification"}], "answer_id": "D"}, {"id": "LING-L03-Q061", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10, 13], "difficulty": "easy", "cognitive_level": "understand", "question": "What does phonology primarily investigate in the lecture?", "explanation": "Phonology examines how sounds function and pattern within a linguistic system. Its questions include sound categories, allowed combinations, and context-sensitive realization.", "example": "A researcher can ask which sound differences distinguish words in English.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The loudness of a recording without regard to sound organization"}, {"id": "B", "text": "The categories and patterns of a language’s sound system"}, {"id": "C", "text": "The printing style of phonetic symbols"}, {"id": "D", "text": "The dictionary definition of every spoken word"}], "answer_id": "B"}, {"id": "LING-L03-Q062", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10], "difficulty": "medium", "cognitive_level": "understand", "question": "What does it mean to say that phonology concerns mental representations of sounds?", "explanation": "A mental representation is not the same thing as one physical recording. It captures linguistic organization that can be reflected in many individual productions.", "example": "Different productions can be treated as instances of the same phoneme.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Every speaker must produce an acoustically identical signal for a category."}, {"id": "B", "text": "Every phoneme is a written picture stored in a dictionary."}, {"id": "C", "text": "Speakers organize sound information into abstract linguistic categories and patterns."}, {"id": "D", "text": "Speakers must consciously recite phonology rules before speaking."}], "answer_id": "C"}, {"id": "LING-L03-Q063", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [13], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher asks which sound sequences can occur at the beginnings of words in a language. Which area is most directly involved?", "explanation": "The question concerns restrictions and possibilities in a sound system. It asks about patterned combinations rather than one signal’s physical magnitude.", "example": "A sequence permitted at the start of words in one language may not be permitted in another.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Dictionary page design"}, {"id": "B", "text": "Articulatory imaging alone"}, {"id": "C", "text": "Acoustic measurement of amplitude alone"}, {"id": "D", "text": "Phonology"}], "answer_id": "D"}, {"id": "LING-L03-Q064", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [13], "difficulty": "medium", "cognitive_level": "apply", "question": "A study asks how the realization of a sound changes depending on neighboring sounds. What makes its central question phonological?", "explanation": "The slide identifies contextual realization as a phonological concern. Acoustic or articulatory methods can provide evidence for the pattern.", "example": "A speaker may produce a sound somewhat differently beside different neighboring sounds.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "It assumes that sounds have no relation to their environment."}, {"id": "B", "text": "It investigates a patterned relationship between sound realization and linguistic context."}, {"id": "C", "text": "It treats every measurable difference as a new written letter."}, {"id": "D", "text": "It determines the word’s meaning from volume alone."}], "answer_id": "B"}, {"id": "LING-L03-Q065", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10, 11], "difficulty": "medium", "cognitive_level": "apply", "question": "A speaker hears an unfamiliar word and notices that its sound sequence does not fit familiar patterns of English. Which knowledge is most directly involved?", "explanation": "Phonological knowledge includes expectations about possible sound patterns. A speaker need not know a word’s meaning or spelling to notice that its form is unusual.", "example": "A listener can judge a sound sequence as unfamiliar without knowing which language it comes from.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Knowledge of the word’s dictionary definition"}, {"id": "B", "text": "Knowledge of English sound-system patterns"}, {"id": "C", "text": "Knowledge of the recording’s exact amplitude"}, {"id": "D", "text": "Knowledge of the spelling of every English word"}], "answer_id": "B"}, {"id": "LING-L03-Q066", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "understand", "question": "Which question about a sound is most specifically phonological?", "explanation": "The correct question asks about the sound’s role in a linguistic system. The alternatives ask about directly observable physical properties of an occurrence.", "example": "Comparing English “kid” and “kit” helps investigate a word-distinguishing sound contrast.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Does it contrast with another sound to distinguish words in this language?"}, {"id": "B", "text": "How many milliseconds does this recording last?"}, {"id": "C", "text": "How large is the waveform’s highest amplitude excursion?"}, {"id": "D", "text": "How far does the speaker’s tongue move during this token?"}], "answer_id": "A"}, {"id": "LING-L03-Q067", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [11, 12, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "How should the table’s statement “phonology is a subset of phonetics” be corrected?", "explanation": "Phonetics foregrounds speech’s physical and perceptual properties; phonology foregrounds categories and patterns. Their interaction does not make one merely a list of facts contained inside the other.", "example": "A recording can provide acoustic evidence for a question about a language’s sound pattern.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phonetics is simply another name for the written alphabet."}, {"id": "B", "text": "Phonology examines spelling while phonetics examines word meaning."}, {"id": "C", "text": "The two fields cannot share evidence because their subjects are unrelated."}, {"id": "D", "text": "The fields are closely related but have different primary questions about physical signals and linguistic organization."}], "answer_id": "D"}, {"id": "LING-L03-Q068", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [11, 12], "difficulty": "hard", "cognitive_level": "analyze", "question": "What is the most careful interpretation of the table’s labels “language independent” for phonetics and “language dependent” for phonology?", "explanation": "The contrast is useful when qualified. Phonetics can study language-specific productions too, while determining a sound’s linguistic function requires information about the system in question.", "example": "A consonant can be physically described before its contrastive role in a particular language is established.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phonetic research can never investigate the speech of one language."}, {"id": "B", "text": "Physical sound properties can be described across languages, while phonemic status requires analysis of a particular language."}, {"id": "C", "text": "Phonetic evidence becomes irrelevant whenever a language is identified."}, {"id": "D", "text": "Every language must share the same inventory of phonemes."}], "answer_id": "B"}, {"id": "LING-L03-Q069", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [11, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why is phonology broader than a list of meaning-distinguishing sounds?", "explanation": "The lecture’s later description includes organization and contextual patterns. A list of phonemes is part of an account, but does not explain how those categories behave.", "example": "Knowing a language’s consonants does not by itself explain which sequences can begin its words.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "It studies only the loudest segment in each recording."}, {"id": "B", "text": "It replaces all sound questions with the meanings of whole paragraphs."}, {"id": "C", "text": "It includes a separate phoneme for every small physical difference."}, {"id": "D", "text": "It also investigates sound combinations and patterns of realization in context."}], "answer_id": "D"}, {"id": "LING-L03-Q070", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [11, 13], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which pair correctly distinguishes a phonetic question from a phonological question about the same consonant?", "explanation": "The first question concerns production. The second concerns linguistic organization. A full investigation can use both perspectives without confusing their objects of explanation.", "example": "Measuring a consonant’s duration differs from asking whether that duration helps distinguish words.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "What does the word mean, and who translated its definition?"}, {"id": "B", "text": "How is it spelled, and how much does the dictionary cost?"}, {"id": "C", "text": "Who printed the text, and how many pages does it contain?"}, {"id": "D", "text": "How is it physically produced, and what role does it play in the language’s sound system?"}], "answer_id": "D"}, {"id": "LING-L03-Q071", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [11, 12, 13], "difficulty": "medium", "cognitive_level": "apply", "question": "A researcher begins with measured differences between two sound types but wants to know whether they contrast in one language. What further kind of evidence is needed?", "explanation": "A physical difference does not automatically establish phonemic contrast. The researcher must examine how the sounds occur and what linguistic distinctions they support.", "example": "A word pair differing only in the relevant sound can be useful evidence of contrast.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Only the alphabetical order of the word list"}, {"id": "B", "text": "Evidence about their distribution and function in that language"}, {"id": "C", "text": "Only a larger printed version of their symbols"}, {"id": "D", "text": "Only the number of speakers in the recording room"}], "answer_id": "B"}, {"id": "LING-L03-Q072", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10, 13], "difficulty": "medium", "cognitive_level": "understand", "question": "How can phonological knowledge help a speaker produce meaningful utterances?", "explanation": "Sound-system knowledge is one component of language ability. It helps speakers form recognizable sound patterns, but works alongside knowledge of words, meanings, and grammatical structure.", "example": "A speaker combines familiar sounds into word forms that listeners can recognize.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "It requires every new utterance to be memorized in advance."}, {"id": "B", "text": "It makes sentence structure unnecessary in communication."}, {"id": "C", "text": "It supports the organization of sound sequences used in the language."}, {"id": "D", "text": "It supplies all word meanings without any lexical knowledge."}], "answer_id": "C"}, {"id": "LING-L03-Q073", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10], "difficulty": "medium", "cognitive_level": "analyze", "question": "A listener notices that a speaker’s pronunciation differs from familiar language patterns. What can sound-system knowledge support here?", "explanation": "The slide links sound knowledge with recognizing an accent. Noticing pronunciation differences does not justify social rankings or certain conclusions about a person’s identity.", "example": "A listener may notice an unfamiliar vowel realization without knowing the speaker’s background.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Proving that the speaker’s language has no sound system"}, {"id": "B", "text": "Recognizing a difference in accent without establishing the speaker’s worth or ability"}, {"id": "C", "text": "Determining the speaker’s intelligence from one sound"}, {"id": "D", "text": "Establishing the speaker’s exact nationality from any single difference"}], "answer_id": "B"}, {"id": "LING-L03-Q074", "lecture_id": "LING-L03", "topic_id": "phonology", "source_slides": [10, 13], "difficulty": "hard", "cognitive_level": "analyze", "question": "A researcher identifies a possible sound sequence in English but does not know whether it names an existing word. Which conclusion is most appropriate?", "explanation": "Sound-system patterns constrain possible forms but are not identical to a vocabulary list. A sequence may be pronounceable and well patterned without being an established word.", "example": "A new product name can fit English sound patterns before people learn what it refers to.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phonological patterns determine exactly which object every sequence names."}, {"id": "B", "text": "Fitting the sound patterns does not alone establish a known word or its meaning."}, {"id": "C", "text": "Every permitted sequence must already be a dictionary word."}, {"id": "D", "text": "A sequence without a dictionary entry cannot have a phonetic form."}], "answer_id": "B"}, {"id": "LING-L03-Q075", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [15], "difficulty": "easy", "cognitive_level": "remember", "question": "What is a segment in the lecture’s account of speech?", "explanation": "A segment is a unit identified within flowing speech. Identifying units supports sound analysis, but the boundaries are analytical rather than printed spaces between letters.", "example": "A learner can identify [s] as the first segment in the transcription [spɪn].", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The entire vocabulary of a language"}, {"id": "B", "text": "The social relationship between two speakers"}, {"id": "C", "text": "An identifiable small unit within the speech stream"}, {"id": "D", "text": "The written definition of a sentence"}], "answer_id": "C"}, {"id": "LING-L03-Q076", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [15, 19], "difficulty": "easy", "cognitive_level": "understand", "question": "Which description best identifies a phone in the spoken-language focus of this lecture?", "explanation": "A phone concerns a realized speech sound. It should be distinguished from a phoneme’s abstract linguistic category and from a morpheme’s meaningful or grammatical role.", "example": "A particular [p] in a recorded utterance can be examined phonetically.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A smallest meaningful word part such as a plural ending"}, {"id": "B", "text": "A written letter whose pronunciation never varies"}, {"id": "C", "text": "An abstract sentence pattern that organizes clauses"}, {"id": "D", "text": "A speech sound described at the level of physical realization"}], "answer_id": "D"}, {"id": "LING-L03-Q077", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [16, 18], "difficulty": "easy", "cognitive_level": "remember", "question": "What property is central to the lecture’s definition of a phoneme?", "explanation": "A phoneme is a contrastive sound category, not a smallest meaningful word part. Its significance depends on the language system in which it functions.", "example": "English /d/ and /t/ distinguish the words “kid” and “kit.”", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Its ability to carry an independent dictionary meaning by itself"}, {"id": "B", "text": "Its role in distinguishing meaning within a language’s sound system"}, {"id": "C", "text": "Its identity as a printed letter in every alphabet"}, {"id": "D", "text": "Its requirement to last the same time in every utterance"}], "answer_id": "B"}, {"id": "LING-L03-Q078", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [16, 18], "difficulty": "medium", "cognitive_level": "understand", "question": "Why is a phoneme described as an abstraction rather than a physical segment itself?", "explanation": "A sound system groups and contrasts productions. The category captures that organization and is not identical to one speaker’s particular physical signal.", "example": "Different tokens of a word can be treated as using the same phonemes despite physical variation.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "It can exist only as a handwritten letter."}, {"id": "B", "text": "It is a linguistic category inferred from patterns across actual sound realizations."}, {"id": "C", "text": "It has no connection with the sounds speakers produce."}, {"id": "D", "text": "It is the same thing as one fixed waveform in a recording."}], "answer_id": "B"}, {"id": "LING-L03-Q079", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [15, 16, 19], "difficulty": "medium", "cognitive_level": "analyze", "question": "Which comparison correctly relates phones and phonemes?", "explanation": "The distinction separates physical evidence from linguistic categorization. A phonetic description can be available before the sound’s phonemic status is established.", "example": "A researcher can describe a produced consonant and then investigate how it functions in the language.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phones and phonemes must correspond to different alphabets."}, {"id": "B", "text": "Phones are abstract word classes; phonemes are social roles."}, {"id": "C", "text": "Phones concern physical sound realizations; phonemes concern contrastive categories in a language."}, {"id": "D", "text": "Phones are written words; phonemes are sentence meanings."}], "answer_id": "C"}, {"id": "LING-L03-Q080", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [19, 20], "difficulty": "medium", "cognitive_level": "apply", "question": "In English, “kid” and “kit” differ in their final sound and have different meanings. What does this provide evidence for?", "explanation": "The final sounds occur in otherwise comparable word forms and distinguish meanings. This supports treating them as different phonemes in English.", "example": "“Bat” and “bad” provide another English comparison involving final /t/ and /d/.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "A difference only in the number of sound segments"}, {"id": "B", "text": "A difference in spelling with no sound contrast"}, {"id": "C", "text": "A phonemic contrast between /d/ and /t/"}, {"id": "D", "text": "A requirement that every final consonant is the same phoneme"}], "answer_id": "C"}, {"id": "LING-L03-Q081", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [19, 20], "difficulty": "medium", "cognitive_level": "apply", "question": "A student replaces /t/ with /d/ at the end of English “kit” and obtains “kid.” What has changed?", "explanation": "This replacement changes a contrastive category while leaving the other segments in the same order. The result is a different English word, not simply an alternative font or an added segment.", "example": "Changing /p/ to /b/ at the start of “pin” also produces a different word, “bin.”", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Only the font of the transcription has changed."}, {"id": "B", "text": "A word has gained an extra sound segment."}, {"id": "C", "text": "The pronunciation has changed without any possible difference in word identity."}, {"id": "D", "text": "A phoneme has been replaced, producing a different word."}], "answer_id": "D"}, {"id": "LING-L03-Q082", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [16, 19], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why must a claim about phonemic contrast identify the language being analysed?", "explanation": "Physical similarity and difference are not enough to establish linguistic function. The same broad phonetic distinction need not have the same role in every sound system.", "example": "Researchers examine evidence from the relevant language before deciding whether two sound types contrast.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Phonemic status depends only on how long a researcher records the sound."}, {"id": "B", "text": "A physical description is impossible until the word’s spelling is known."}, {"id": "C", "text": "The contrastive role of a physical sound difference depends on the language’s system."}, {"id": "D", "text": "Every language assigns exactly the same phonemic status to all sounds."}], "answer_id": "C"}, {"id": "LING-L03-Q083", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [13, 18], "difficulty": "medium", "cognitive_level": "understand", "question": "The lecture groups examples such as “tip,” “stand,” “writer,” and “cat” under /t/. What is the most careful interpretation?", "explanation": "The slashes refer to a category in a phonological analysis. Its realization can vary by position and accent. The shared label does not require an identical sound in every token.", "example": "A speaker’s /t/ at the beginning of a word can differ phonetically from its realization elsewhere.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Each spelling of the letter t necessarily represents a new phoneme."}, {"id": "B", "text": "Every speaker must produce exactly the same [t] in all four words."}, {"id": "C", "text": "The examples illustrate one phonemic category without requiring identical physical pronunciations."}, {"id": "D", "text": "The words must have the same meaning because they contain /t/."}], "answer_id": "C"}, {"id": "LING-L03-Q084", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [13, 18], "difficulty": "hard", "cognitive_level": "analyze", "question": "In some North American accents, /t/ in “writer” is realized as a flap [ɾ]. What does this illustrate?", "explanation": "A category can be realized differently in particular environments. The example is accent-specific; it is not a pronunciation rule for every English speaker.", "example": "The phonemic label /t/ can remain useful even when one occurrence is pronounced as [ɾ].", "reference_ids": ["lecture_03", "eol_phonemes"], "options": [{"id": "A", "text": "A flap realization must be used in every English accent."}, {"id": "B", "text": "Every change in physical realization automatically creates a new word."}, {"id": "C", "text": "A phoneme can have a context-sensitive physical realization different from a plain [t]."}, {"id": "D", "text": "The word has necessarily lost its phonological structure."}], "answer_id": "C"}, {"id": "LING-L03-Q085", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [17], "difficulty": "hard", "cognitive_level": "analyze", "question": "Why is physical similarity between two phones insufficient on its own to establish that they belong to one phoneme?", "explanation": "Phonemic grouping is a linguistic analysis, not a judgment of resemblance alone. Similarity can be relevant, but patterns and contrasts supply essential evidence.", "example": "Two similar consonants can distinguish words, so similarity alone cannot justify merging them.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Their distribution and contrastive function in the language must also be investigated."}, {"id": "B", "text": "Every pair of similar sounds must be one phoneme in every language."}, {"id": "C", "text": "Only differences in spelling determine phonemic membership."}, {"id": "D", "text": "Physically similar sounds can never be compared in phonology."}], "answer_id": "A"}, {"id": "LING-L03-Q086", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [15, 16], "difficulty": "medium", "cognitive_level": "apply", "question": "A recording contains several physically different repetitions of a word, but an analysis assigns the same phonemic sequence to them. Is this necessarily inconsistent?", "explanation": "A phonemic representation does not specify every detail of every production. Variation among tokens can coexist with a stable analysis of their linguistic categories.", "example": "A speaker may say “kit” more quickly on one repetition than another without changing the word.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Yes; each acoustic difference must create a different word."}, {"id": "B", "text": "No; abstract phonemic categories can be realized in physically varying tokens."}, {"id": "C", "text": "No; recordings cannot contain any measurable physical variation."}, {"id": "D", "text": "Yes; one phoneme must have an identical waveform in every token."}], "answer_id": "B"}, {"id": "LING-L03-Q087", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [16, 19, 20], "difficulty": "hard", "cognitive_level": "analyze", "question": "What does calling /t/ a meaning-distinguishing unit imply?", "explanation": "Distinguishing meaning is different from carrying an independent meaning. A phoneme participates in contrasts; a smallest meaningful unit belongs to a different level of analysis.", "example": "The contrast between “kit” and “kid” matters even though /t/ alone does not mean “kit.”", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The phoneme /t/ must be a complete sentence on its own."}, {"id": "B", "text": "Every occurrence of /t/ contributes the same dictionary meaning."}, {"id": "C", "text": "Its contrast with another phoneme can help distinguish words, though /t/ need not have a meaning by itself."}, {"id": "D", "text": "The sound /t/ must independently name a particular object."}], "answer_id": "C"}, {"id": "LING-L03-Q088", "lecture_id": "LING-L03", "topic_id": "phone_phoneme", "source_slides": [15, 16, 19], "difficulty": "hard", "cognitive_level": "analyze", "question": "What is the most careful interpretation of the slide’s statement that phones are not language-specific?", "explanation": "The useful distinction concerns description and function. A phone’s physical properties can be described, while its role in a sound system requires language-specific evidence. This does not remove phonetic variation.", "example": "An analyst can describe a consonant’s articulation before deciding whether it contrasts with another sound.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "All speakers produce physically identical tokens of a phone."}, {"id": "B", "text": "Every language uses every possible phone."}, {"id": "C", "text": "A phone cannot occur as part of a language-specific pattern."}, {"id": "D", "text": "Phones can be physically described without first deciding their phonemic role in a language."}], "answer_id": "D"}, {"id": "LING-L03-Q089", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [21], "difficulty": "easy", "cognitive_level": "remember", "question": "Which notation convention does the lecture use for phonemes?", "explanation": "Slashes mark a phonemic representation in the convention taught here. They indicate the level of analysis rather than how loudly or carefully the sound was produced.", "example": "The final phoneme of English “kit” can be represented as /t/.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Slashes, as in /t/"}, {"id": "B", "text": "Square brackets, as in [t]"}, {"id": "C", "text": "Quotation marks alone, as in “t”"}, {"id": "D", "text": "Curly brackets alone, as in {t}"}], "answer_id": "A"}, {"id": "LING-L03-Q090", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [21], "difficulty": "easy", "cognitive_level": "remember", "question": "Which notation convention does the lecture use for phones?", "explanation": "Square brackets mark a phonetic representation. A transcription can include more or less phonetic detail, so brackets do not guarantee that every physical detail is recorded.", "example": "The lecture uses [spɪn] as a phonetic representation of “spin.”", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Slashes, as in /t/"}, {"id": "B", "text": "Quotation marks alone, as in “t”"}, {"id": "C", "text": "Round brackets alone, as in (t)"}, {"id": "D", "text": "Square brackets, as in [t]"}], "answer_id": "D"}, {"id": "LING-L03-Q091", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [20], "difficulty": "easy", "cognitive_level": "apply", "question": "How many sound segments are represented in the lecture’s transcription [spɪn]?", "explanation": "The represented sequence contains [s], [p], [ɪ], and [n]. Counting these sound segments is different from assuming that every possible transcription has one symbol per written letter.", "example": "In this example, the four segments occur in the order [s] then [p] then [ɪ] then [n].", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Three"}, {"id": "B", "text": "Four"}, {"id": "C", "text": "Five"}, {"id": "D", "text": "Two"}], "answer_id": "B"}, {"id": "LING-L03-Q092", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [20], "difficulty": "medium", "cognitive_level": "apply", "question": "Which sequence reproduces the segment order of [spɪn]?", "explanation": "The order matters because a transcription represents a sequence of sounds. Recognizing the same individual symbols is not enough if their arrangement changes.", "example": "The transcription begins with the consonants [s] and [p] before the vowel [ɪ].", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "[s], [p], [ɪ], [n]"}, {"id": "B", "text": "[p], [s], [ɪ], [n]"}, {"id": "C", "text": "[s], [p], [n], [ɪ]"}, {"id": "D", "text": "[s], [ɪ], [p], [n]"}], "answer_id": "A"}, {"id": "LING-L03-Q093", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [14], "difficulty": "easy", "cognitive_level": "understand", "question": "Why are phonetic alphabets useful in the study of speech?", "explanation": "A sound-based notation helps record and compare speech. It should be distinguished from a language’s ordinary spelling system and from direct measurements of a recording.", "example": "A symbol such as [ɪ] can specify a sound more directly than relying on the spelling letter i.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "They remove the need to investigate actual speech sounds."}, {"id": "B", "text": "They represent sentence meanings without reference to sounds."}, {"id": "C", "text": "They guarantee that ordinary spelling has one fixed pronunciation in every language."}, {"id": "D", "text": "They provide symbols for representing speech sounds in writing."}], "answer_id": "D"}, {"id": "LING-L03-Q094", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [14], "difficulty": "medium", "cognitive_level": "remember", "question": "Which pair reproduces the additional sound-symbol examples shown beside p and b on slide 14?", "explanation": "The examples show symbols beyond the basic modern English alphabet. The slide’s alphabet-origin labels should not be used to infer that these two symbols have the same historical origin. Their linguistic role requires separate analysis.", "example": "A learner may encounter [θ] and [ð] in sound transcriptions even though ordinary English spelling uses th.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "p and b"}, {"id": "B", "text": "t and k"}, {"id": "C", "text": "θ and ð"}, {"id": "D", "text": "s and n"}], "answer_id": "C"}, {"id": "LING-L03-Q095", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [21], "difficulty": "medium", "cognitive_level": "apply", "question": "Using the slide’s convention that the vowel category in “bead” and “bean” is /i/, which statement is correct?", "explanation": "A phonemic label states a category in a specified analysis. English vowel transcription conventions vary, and a shared label does not erase token-level differences.", "example": "Another English description may use /iː/ for this category while still grouping the two vowels together.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The notation identifies a shared vowel phoneme in that analysis, not an identical physical token."}, {"id": "B", "text": "The notation proves that each vowel has precisely the same duration."}, {"id": "C", "text": "The notation requires all English descriptions to use exactly the same vowel symbols."}, {"id": "D", "text": "The notation proves that both whole words have identical meanings."}], "answer_id": "A"}, {"id": "LING-L03-Q096", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [16, 21], "difficulty": "hard", "cognitive_level": "analyze", "question": "What changes when an analyst writes /t/ rather than [t]?", "explanation": "The brackets and slashes identify the representational level. Changing notation alone does not alter the recorded signal or establish a new contrast.", "example": "A category /t/ can be related to particular realizations represented within square brackets.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The symbol must now name a different written letter."}, {"id": "B", "text": "The sound automatically acquires an independent word meaning."}, {"id": "C", "text": "The notation foregrounds a phonemic category rather than a phonetic sound description."}, {"id": "D", "text": "The sound must become louder in the recording."}], "answer_id": "C"}, {"id": "LING-L03-Q097", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [14, 20, 21], "difficulty": "medium", "cognitive_level": "analyze", "question": "A student counts the letters in a written word and assumes that the number must equal its speech segments. What is the main problem?", "explanation": "Sound analysis should use pronunciation evidence and an appropriate representation. Ordinary spelling can use several letters for one sound or represent sounds inconsistently.", "example": "The spelling sh in “ship” represents one initial consonant sound rather than separate [s] and [h] sounds.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "Ordinary spelling and sound segmentation do not have a guaranteed one-to-one relationship."}, {"id": "B", "text": "Every pair of written letters must represent two different phonemes."}, {"id": "C", "text": "A word can never contain more than one speech segment."}, {"id": "D", "text": "Square brackets count written syllables rather than sounds."}], "answer_id": "A"}, {"id": "LING-L03-Q098", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [15, 20, 21], "difficulty": "hard", "cognitive_level": "analyze", "question": "What does the simple transcription [spɪn] allow a learner to identify without claiming a complete acoustic record?", "explanation": "A transcription is an analytical representation, not a full recording. Its symbols indicate selected sound information, while timing and other details may require separate notation or measurements.", "example": "The sequence [spɪn] identifies four represented segments without giving the duration of each one.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The listener’s precise emotional reaction"}, {"id": "B", "text": "The fundamental frequency of every cycle"}, {"id": "C", "text": "The represented sound sequence at the chosen level of phonetic detail"}, {"id": "D", "text": "The exact waveform amplitude at every instant"}], "answer_id": "C"}, {"id": "LING-L03-Q099", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [5, 16, 20, 21], "difficulty": "hard", "cognitive_level": "analyze", "question": "A student measures the final sounds of “kid” and “kit” and also argues that /d/ and /t/ contrast in English. Which description keeps the two analyses distinct?", "explanation": "Physical measurements concern realized signals. Establishing a contrast concerns the organization of categories in a language and requires linguistic evidence, not spelling alone.", "example": "A timing difference can be measured acoustically while the word pair supports a claim about phonemic contrast.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "The measurements and contrast claim are both purely articulatory observations."}, {"id": "B", "text": "The measurements are phonetic evidence; the contrast claim is a phonological analysis."}, {"id": "C", "text": "The contrast claim is valid solely because the words use different letters."}, {"id": "D", "text": "The measurements are dictionary meanings; the contrast claim is a spelling rule."}], "answer_id": "B"}, {"id": "LING-L03-Q100", "lecture_id": "LING-L03", "topic_id": "transcription", "source_slides": [4, 5, 9, 13, 16], "difficulty": "hard", "cognitive_level": "analyze", "question": "A project records tongue movement, measures the signal, tests listeners, and investigates whether two sounds distinguish words. Which account best describes the project?", "explanation": "The methods and goals address different parts of sound production, perception, and linguistic organization. A coherent project can connect them while preserving the distinctions.", "example": "Physical differences, listener judgments, and word contrasts can contribute complementary evidence about a sound system.", "reference_ids": ["lecture_03"], "options": [{"id": "A", "text": "It is only phonology because physical evidence cannot be linguistic evidence."}, {"id": "B", "text": "It is only acoustic phonetics because every other observation is identical to a recording."}, {"id": "C", "text": "It combines articulatory, acoustic, auditory, and phonological questions."}, {"id": "D", "text": "It is only auditory phonetics because listeners are included."}], "answer_id": "C"}]}];
